from __future__ import annotations

import asyncio
import logging
import threading
import time
from contextlib import asynccontextmanager
from typing import Any, Generic, Protocol, TypeVar

from .deepseek.client import DeepSeekClient
from .pow import PowManager
from .sessions import SessionRegistry
from .store import JsonStore

log = logging.getLogger("danyapi.accounts")


class AccountPoolBusy(Exception):
    pass


@asynccontextmanager
async def account_lock(sem: asyncio.Semaphore, max_wait: float | None = None):
    if max_wait is None:
        async with sem:
            yield
        return
    try:
        await asyncio.wait_for(sem.acquire(), timeout=max_wait)
    except (TimeoutError, asyncio.TimeoutError) as exc:
        raise AccountPoolBusy() from exc
    try:
        yield
    finally:
        sem.release()


class ContextIndex:
    def __init__(
        self,
        maxsize: int = 128,
        ttl: float = 0.0,
        store: JsonStore | None = None,
    ) -> None:
        self._seqs: dict[str, tuple[str, ...]] = {}
        self._recency: dict[str, int] = {}
        self._ts: dict[str, float] = {}
        self._lock = threading.Lock()
        self._maxsize = max(1, maxsize)
        self._ttl = max(0.0, ttl)
        self._tick = 0
        self.hits = 0
        self.misses = 0
        self._store = store
        self._restore()

    def _restore(self) -> None:
        store = self._store
        if store is None:
            return
        now = time.monotonic()
        for session_id, record in store.items():
            if not isinstance(session_id, str) or not session_id:
                continue
            if not isinstance(record, list):
                continue
            sequence = tuple(item for item in record if isinstance(item, str))
            if not sequence:
                continue
            self._seqs[session_id] = sequence
            self._touch(session_id, now)
        while len(self._seqs) > self._maxsize:
            oldest = min(self._recency, key=lambda sid: self._recency[sid])
            self._seqs.pop(oldest, None)
            self._recency.pop(oldest, None)
            self._ts.pop(oldest, None)
            store.discard(oldest)

    def _expired(self, session_id: str, now: float) -> bool:
        ts = self._ts.get(session_id)
        return ts is not None and self._ttl > 0 and now - ts > self._ttl

    @property
    def size(self) -> int:
        return len(self._seqs)

    @property
    def max_size(self) -> int:
        return self._maxsize

    def lookup(self, sequence: tuple[str, ...]) -> str | None:
        if not sequence:
            return None
        now = time.monotonic()
        store = self._store
        with self._lock:
            if not self._seqs:
                self.misses += 1
                return None
            best_sid: str | None = None
            best_key = (-1, -1)
            expired: list[str] = []
            for sid, seq in self._seqs.items():
                if self._expired(sid, now):
                    expired.append(sid)
                    continue
                if not seq or len(seq) > len(sequence):
                    continue
                if sequence[: len(seq)] != seq:
                    continue
                key = (len(seq), self._recency.get(sid, 0))
                if key > best_key:
                    best_key = key
                    best_sid = sid
            for sid in expired:
                self._seqs.pop(sid, None)
                self._recency.pop(sid, None)
                self._ts.pop(sid, None)
                if store is not None:
                    store.discard(sid)
            if best_sid is not None:
                self.hits += 1
                self._touch(best_sid, now)
            else:
                self.misses += 1
            return best_sid

    def index(self, session_id: str, sequence: tuple[str, ...]) -> None:
        if not session_id or not sequence:
            return
        now = time.monotonic()
        with self._lock:
            current = self._seqs.get(session_id)
            if current is not None and len(current) >= len(sequence) and sequence == current[: len(sequence)]:
                self._touch(session_id, now)
                return
            self._seqs[session_id] = sequence
            self._touch(session_id, now)
            while len(self._seqs) > self._maxsize:
                oldest = min(self._recency, key=lambda sid: self._recency[sid])
                self._seqs.pop(oldest, None)
                self._recency.pop(oldest, None)
                self._ts.pop(oldest, None)
                if self._store is not None:
                    self._store.discard(oldest)
            if self._store is not None:
                self._store.set(session_id, list(sequence))

    def forget(self, session_id: str) -> None:
        with self._lock:
            self._seqs.pop(session_id, None)
            self._recency.pop(session_id, None)
            self._ts.pop(session_id, None)
        if self._store is not None:
            self._store.discard(session_id)

    def _touch(self, session_id: str, now: float) -> None:
        self._recency[session_id] = self._tick
        self._tick += 1
        self._ts[session_id] = now


class DeepSeekAccount:
    __slots__ = ("broken", "client", "index", "pow", "pow_upload", "sem", "sessions", "stable_id")

    def __init__(
        self,
        index: int,
        client: DeepSeekClient,
        session_cache_size: int = 128,
        ttl: float = 0.0,
        store: JsonStore | None = None,
        stable_id: str | None = None,
    ) -> None:
        self.index = index
        self.client = client
        self.pow = PowManager()
        self.pow_upload = PowManager()
        self.sem = asyncio.Semaphore(1)
        self.sessions = SessionRegistry(client, session_cache_size, ttl, store=store, key_prefix=f"{index}:")
        self.stable_id = stable_id
        self.broken = False

    def mark_broken(self) -> None:
        if not self.broken:
            self.broken = True
            log.warning("account #%d marked broken (invalid/expired token)", self.index)

    @property
    def label(self) -> str:
        return f"acct#{self.index}"


class _PoolAccount(Protocol):
    broken: bool
    sem: asyncio.Semaphore


AccountT = TypeVar("AccountT", bound=_PoolAccount)


class AccountPool(Generic[AccountT]):
    def __init__(
        self,
        accounts: list[AccountT],
        label: str = "deepseek",
        session_cache_size: int = 128,
        ttl: float = 0.0,
        context_store: JsonStore | None = None,
        affinity_store: JsonStore | None = None,
    ) -> None:
        self.accounts = accounts
        self.label = label
        self._by_session: dict[str, tuple[int, float]] = {}
        self._stable_to_idx: dict[str, int] = {}
        for i, acct in enumerate(accounts):
            sid = getattr(acct, "stable_id", None)
            if isinstance(sid, str) and sid:
                self._stable_to_idx[sid] = i
        self._rr = 0
        self._ttl = max(0.0, ttl)
        self._affinity_store = affinity_store
        self._contexts = ContextIndex(session_cache_size, ttl, store=context_store)
        self._restore_affinities()

    def _affinity_record(self, account_index: int) -> int | str:
        sid = getattr(self.accounts[account_index], "stable_id", None)
        if isinstance(sid, str) and sid:
            return sid
        return account_index

    def _resolve_affinity(self, record: Any) -> int | None:
        idx: Any = record
        if isinstance(record, list) and record:
            idx = record[0]
        if isinstance(idx, bool):
            return None
        if isinstance(idx, int):
            return idx if 0 <= idx < len(self.accounts) else None
        if isinstance(idx, str):
            return self._stable_to_idx.get(idx)
        return None

    def _restore_affinities(self) -> None:
        if self._affinity_store is None:
            return
        now = time.monotonic()
        for session_id, record in self._affinity_store.items():
            if not isinstance(session_id, str) or not session_id:
                continue
            idx = self._resolve_affinity(record)
            if idx is None:
                continue
            self._by_session[session_id] = (idx, now)

    @property
    def healthy(self) -> list[AccountT]:
        return [a for a in self.accounts if not a.broken]

    def register(self, account_index: int, session_id: str) -> None:
        now = time.monotonic()
        self._by_session[session_id] = (account_index, now)
        if self._affinity_store is not None:
            self._affinity_store.set(session_id, self._affinity_record(account_index))
        if self._ttl > 0 and len(self._by_session) > max(4096, len(self.accounts) * 1024):
            stale = [sid for sid, (_, ts) in self._by_session.items() if now - ts > self._ttl]
            for sid in stale:
                self._by_session.pop(sid, None)
                if self._affinity_store is not None:
                    self._affinity_store.discard(sid)

    def forget(self, session_id: str) -> None:
        self._by_session.pop(session_id, None)
        if self._affinity_store is not None:
            self._affinity_store.discard(session_id)

    def resolve_context(self, sequence: tuple[str, ...]) -> str | None:
        return self._contexts.lookup(sequence)

    def index_context(self, session_id: str, sequence: tuple[str, ...]) -> None:
        self._contexts.index(session_id, sequence)

    def forget_context(self, session_id: str) -> None:
        self._contexts.forget(session_id)

    def account_for_session(self, session_id: str) -> AccountT | None:
        entry = self._by_session.get(session_id)
        if entry is None:
            return None
        idx, ts = entry
        now = time.monotonic()
        if self._ttl > 0 and now - ts > self._ttl:
            self._by_session.pop(session_id, None)
            self._contexts.forget(session_id)
            if self._affinity_store is not None:
                self._affinity_store.discard(session_id)
            return None
        acct = self.accounts[idx]
        if acct is None or acct.broken:
            self._by_session.pop(session_id, None)
            self._contexts.forget(session_id)
            if self._affinity_store is not None:
                self._affinity_store.discard(session_id)
            return None
        if self._ttl > 0 and now != ts:
            self._by_session[session_id] = (idx, now)
        return acct

    def stats(self) -> dict[str, Any]:
        return {
            "label": self.label,
            "accounts": len(self.accounts),
            "healthy": len(self.healthy),
            "broken": len(self.accounts) - len(self.healthy),
            "session_affinities": len(self._by_session),
            "context_entries": self._contexts.size,
            "context_hits": self._contexts.hits,
            "context_misses": self._contexts.misses,
            "context_cache_size": self._contexts.max_size,
            "ttl_seconds": self._ttl,
        }

    async def acquire(self, session_id: str | None, max_wait: float | None = None) -> tuple[AccountT, str | None]:
        healthy = self.healthy
        if not healthy:
            raise RuntimeError(f"all {self.label} accounts are unavailable")
        if session_id:
            acct = self.account_for_session(session_id)
            if acct is not None:
                if acct.sem.locked() and max_wait is not None:
                    return await self._wait_free(acct, max_wait, session_id)
                return acct, session_id
        n = len(healthy)
        start = self._rr % n
        for i in range(n):
            idx = (start + i) % n
            acct = healthy[idx]
            if not acct.sem.locked():
                self._rr = (idx + 1) % n
                return acct, None
        if max_wait is not None:
            return await self._wait_free(None, max_wait, None)
        acct = healthy[start]
        return acct, None

    async def _wait_free(
        self,
        preferred: AccountT | None,
        max_wait: float,
        session_id: str | None,
    ) -> tuple[AccountT, str | None]:
        deadline = time.monotonic() + max_wait
        while True:
            if preferred is not None and not preferred.broken:
                candidates = [preferred]
            else:
                candidates = self.healthy
            if not candidates:
                raise AccountPoolBusy()
            for i, acct in enumerate(candidates):
                if not acct.sem.locked():
                    if session_id is not None:
                        return acct, session_id
                    self._rr = (i + 1) % len(candidates)
                    return acct, None
            if time.monotonic() >= deadline:
                raise AccountPoolBusy()
            await asyncio.sleep(0.05)

    def add_account(self, account: AccountT) -> None:
        idx = len(self.accounts)
        self.accounts.append(account)
        sid = getattr(account, "stable_id", None)
        if isinstance(sid, str) and sid:
            self._stable_to_idx[sid] = idx

from __future__ import annotations

import json
import uuid
from collections.abc import AsyncIterator, Iterator
from dataclasses import dataclass, field
from typing import Any


class ResponsesInputError(ValueError):
    pass


TEXT_PART_TYPES = {"input_text", "output_text", "text", "summary_text"}
IMAGE_PART_TYPES = {"input_image", "image_url"}
SUPPORTED_ROLES = {"user", "assistant", "system", "developer", "tool", "function"}


def _as_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, (int, float, bool)):
        return str(value)
    if isinstance(value, list):
        parts: list[str] = []
        for item in value:
            if isinstance(item, str):
                parts.append(item)
            elif isinstance(item, dict):
                text = item.get("text")
                if isinstance(text, str):
                    parts.append(text)
                elif item.get("type") == "output_text" and isinstance(item.get("content"), str):
                    parts.append(item["content"])
            else:
                parts.append(_as_text(item))
        return "".join(parts)
    if isinstance(value, dict):
        if isinstance(value.get("text"), str):
            return value["text"]
        return json.dumps(value, ensure_ascii=False)
    return str(value)


def _normalize_content(content: Any) -> Any:
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if not isinstance(content, list):
        return _as_text(content)
    parts: list[Any] = []
    for item in content:
        if isinstance(item, str):
            parts.append({"type": "text", "text": item})
            continue
        if not isinstance(item, dict):
            raise ResponsesInputError("each content part must be an object")
        part_type = item.get("type")
        if part_type in TEXT_PART_TYPES:
            parts.append({"type": "text", "text": _as_text(item.get("text"))})
        elif part_type in IMAGE_PART_TYPES:
            image_url = item.get("image_url")
            if isinstance(image_url, dict):
                image_url = image_url.get("url")
            if not isinstance(image_url, str) or not image_url:
                raise ResponsesInputError("input_image requires an image_url string")
            parts.append({"type": "image_url", "image_url": image_url})
        elif part_type == "refusal":
            parts.append({"type": "text", "text": _as_text(item.get("refusal"))})
        elif part_type in ("input_file", "file", "input_audio"):
            continue
        elif isinstance(item.get("text"), str):
            parts.append({"type": "text", "text": item["text"]})
    if not parts:
        return ""
    if all(isinstance(part, dict) and part.get("type") == "text" for part in parts):
        return "".join(part["text"] for part in parts)
    return parts


def _normalize_item(item: Any) -> list[dict]:
    if not isinstance(item, dict):
        raise ResponsesInputError("each input item must be an object")
    item_type = item.get("type")
    if item_type in ("function_call", "computer_call", "custom_tool_call"):
        call_id = item.get("call_id") or item.get("id") or f"call_{uuid.uuid4().hex[:12]}"
        name = item.get("name") or ""
        arguments = item.get("arguments")
        if isinstance(arguments, (dict, list)):
            arguments = json.dumps(arguments, ensure_ascii=False)
        return [
            {
                "role": "assistant",
                "content": "",
                "tool_calls": [
                    {
                        "id": call_id,
                        "type": "function",
                        "function": {"name": name, "arguments": arguments if isinstance(arguments, str) else "{}"},
                    }
                ],
            }
        ]
    if item_type in ("function_call_output", "computer_call_output", "custom_tool_call_output"):
        call_id = item.get("call_id") or item.get("id") or ""
        return [{"role": "tool", "tool_call_id": call_id, "content": _as_text(item.get("output"))}]
    if item_type in ("reasoning", "item_reference", "web_search_call", "file_search_call", "code_interpreter_call"):
        return []
    role = item.get("role")
    if role is None and item_type == "message":
        role = "assistant"
    if not isinstance(role, str):
        raise ResponsesInputError("input item requires a role or a supported type")
    if role == "developer":
        role = "system"
    if role not in SUPPORTED_ROLES:
        raise ResponsesInputError(f"unsupported role: {role}")
    return [{"role": role, "content": _normalize_content(item.get("content"))}]


def normalize_input(input_value: Any) -> list[dict]:
    if input_value is None:
        return []
    if isinstance(input_value, str):
        return [{"role": "user", "content": input_value}]
    if isinstance(input_value, dict):
        return _normalize_item(input_value)
    if isinstance(input_value, list):
        messages: list[dict] = []
        for item in input_value:
            messages.extend(_normalize_item(item))
        return messages
    raise ResponsesInputError("input must be a string or an array of input items")


def convert_tools(tools: Any) -> list[Any] | None:
    if not isinstance(tools, list):
        return None
    converted: list[dict] = []
    for tool in tools:
        if not isinstance(tool, dict):
            continue
        if isinstance(tool.get("function"), dict):
            converted.append(tool)
            continue
        tool_type = tool.get("type")
        if tool_type == "function" or (isinstance(tool.get("name"), str) and tool_type in (None, "function")):
            function: dict[str, Any] = {"name": tool.get("name")}
            if "description" in tool:
                function["description"] = tool["description"]
            if "parameters" in tool:
                function["parameters"] = tool["parameters"]
            if "strict" in tool:
                function["strict"] = tool["strict"]
            converted.append({"type": "function", "function": function})
    return converted or None


def convert_tool_choice(tool_choice: Any) -> Any:
    if tool_choice is None:
        return None
    if isinstance(tool_choice, str):
        return tool_choice
    if isinstance(tool_choice, dict):
        choice_type = tool_choice.get("type")
        if choice_type in ("auto", "none", "required"):
            return choice_type
        name = tool_choice.get("name")
        if not isinstance(name, str) and isinstance(tool_choice.get("function"), dict):
            name = tool_choice["function"].get("name")
        if isinstance(name, str) and name:
            return {"type": "function", "function": {"name": name}}
    return None


def response_text_format(text: Any) -> dict | None:
    if isinstance(text, dict):
        fmt = text.get("format")
        if isinstance(fmt, dict):
            return fmt
        if isinstance(fmt, str):
            return {"type": fmt}
        return None
    if isinstance(text, str):
        return {"type": text}
    return None


def extract_response_format(text: Any, response_format: Any) -> Any:
    fmt = None
    if isinstance(text, dict):
        fmt = text.get("format")
    if fmt is None:
        fmt = response_format
    if fmt is None:
        return None
    if isinstance(fmt, str):
        return fmt
    if not isinstance(fmt, dict):
        return None
    fmt_type = fmt.get("type")
    if fmt_type == "json_object":
        return {"type": "json_object"}
    if fmt_type != "json_schema":
        return None
    schema = fmt.get("schema")
    if schema is None and isinstance(fmt.get("json_schema"), dict):
        nested = fmt["json_schema"]
        return {"type": "json_schema", "json_schema": nested}
    if schema is None:
        return None
    json_schema: dict[str, Any] = {"name": fmt.get("name") or "response", "schema": schema}
    if "strict" in fmt:
        json_schema["strict"] = fmt["strict"]
    if "description" in fmt:
        json_schema["description"] = fmt["description"]
    return {"type": "json_schema", "json_schema": json_schema}


@dataclass
class RequestInfo:
    model: str
    instructions: str | None = None
    max_output_tokens: int | None = None
    temperature: float | None = None
    top_p: float | None = None
    tool_choice: Any = None
    tools: list[Any] | None = None
    parallel_tool_calls: bool | None = None
    previous_response_id: str | None = None
    store: bool = True
    metadata: Any = None
    user: str | None = None
    text_format: dict | None = None
    truncation: str = "disabled"
    reasoning: Any = None
    extras: dict[str, Any] = field(default_factory=dict)


def _usage_to_responses(usage: Any) -> dict | None:
    if not isinstance(usage, dict):
        return None
    input_tokens = int(usage.get("prompt_tokens") or usage.get("input_tokens") or 0)
    output_tokens = int(usage.get("completion_tokens") or usage.get("output_tokens") or 0)
    total_tokens = int(usage.get("total_tokens") or (input_tokens + output_tokens))
    return {
        "input_tokens": input_tokens,
        "input_tokens_details": {"cached_tokens": int(usage.get("cached_tokens") or 0)},
        "output_tokens": output_tokens,
        "output_tokens_details": {"reasoning_tokens": int(usage.get("reasoning_tokens") or 0)},
        "total_tokens": total_tokens,
    }


def build_response_object(
    info: RequestInfo,
    response_id: str,
    created_at: int,
    output: list[dict],
    status: str = "completed",
    usage: Any = None,
    error: dict | None = None,
    incomplete_details: dict | None = None,
) -> dict:
    return {
        "id": response_id,
        "object": "response",
        "created_at": created_at,
        "status": status,
        "error": error,
        "incomplete_details": incomplete_details,
        "instructions": info.instructions,
        "max_output_tokens": info.max_output_tokens,
        "model": info.model,
        "output": output,
        "parallel_tool_calls": True if info.parallel_tool_calls is None else info.parallel_tool_calls,
        "previous_response_id": info.previous_response_id,
        "reasoning": info.reasoning if info.reasoning is not None else {"effort": None, "summary": None},
        "store": info.store,
        "temperature": info.temperature,
        "text": {"format": info.text_format or {"type": "text"}},
        "tool_choice": info.tool_choice if info.tool_choice is not None else "auto",
        "tools": info.tools or [],
        "top_p": info.top_p,
        "truncation": info.truncation,
        "usage": _usage_to_responses(usage),
        "user": info.user,
        "metadata": info.metadata if isinstance(info.metadata, dict) else {},
    }


def output_items_from_message(message: Any) -> list[dict]:
    if not isinstance(message, dict):
        return []
    items: list[dict] = []
    reasoning = message.get("reasoning_content")
    if isinstance(reasoning, str) and reasoning:
        items.append(
            {
                "id": f"rs_{uuid.uuid4().hex}",
                "type": "reasoning",
                "summary": [{"type": "summary_text", "text": reasoning}],
            }
        )
    content = message.get("content")
    text = _as_text(content)
    tool_calls = message.get("tool_calls")
    has_calls = isinstance(tool_calls, list) and bool(tool_calls)
    if text or not has_calls:
        items.append(
            {
                "id": f"msg_{uuid.uuid4().hex}",
                "type": "message",
                "status": "completed",
                "role": "assistant",
                "content": [{"type": "output_text", "text": text, "annotations": []}],
            }
        )
    if isinstance(tool_calls, list):
        for call in tool_calls:
            if not isinstance(call, dict):
                continue
            function = call.get("function")
            if not isinstance(function, dict):
                function = call
            arguments = function.get("arguments")
            if isinstance(arguments, (dict, list)):
                arguments = json.dumps(arguments, ensure_ascii=False)
            items.append(
                {
                    "id": f"fc_{uuid.uuid4().hex}",
                    "type": "function_call",
                    "call_id": call.get("id") or f"call_{uuid.uuid4().hex[:12]}",
                    "name": function.get("name") or "",
                    "arguments": arguments if isinstance(arguments, str) else "{}",
                    "status": "completed",
                }
            )
    return items


def messages_from_output(output: Any) -> list[dict]:
    if not isinstance(output, list):
        return []
    text_parts: list[str] = []
    calls: list[dict] = []
    for item in output:
        if not isinstance(item, dict):
            continue
        item_type = item.get("type")
        if item_type == "message":
            content = item.get("content")
            if isinstance(content, list):
                for part in content:
                    if isinstance(part, dict) and isinstance(part.get("text"), str):
                        text_parts.append(part["text"])
            elif isinstance(content, str):
                text_parts.append(content)
        elif item_type == "function_call":
            calls.append(
                {
                    "id": item.get("call_id") or item.get("id") or f"call_{uuid.uuid4().hex[:12]}",
                    "type": "function",
                    "function": {"name": item.get("name") or "", "arguments": item.get("arguments") or "{}"},
                }
            )
    messages: list[dict] = []
    text = "".join(text_parts)
    if text or not calls:
        messages.append({"role": "assistant", "content": text})
    if calls:
        messages.append({"role": "assistant", "content": "", "tool_calls": calls})
    return messages


INCOMPLETE_REASONS = {
    "length": "max_output_tokens",
    "content_filter": "content_filter",
}


def response_from_chat(chat: Any, info: RequestInfo, response_id: str, created_at: int) -> dict:
    if not isinstance(chat, dict):
        raise ResponsesInputError("provider returned an invalid response")
    choices = chat.get("choices")
    choice = choices[0] if isinstance(choices, list) and choices else {}
    message = choice.get("message") if isinstance(choice, dict) else None
    output = output_items_from_message(message)
    finish = choice.get("finish_reason") if isinstance(choice, dict) else None
    error = chat.get("error") if isinstance(chat.get("error"), dict) else None
    status = "completed"
    incomplete_details = None
    if error is not None or finish == "response_incomplete":
        status = "incomplete"
    elif finish in INCOMPLETE_REASONS:
        status = "incomplete"
        incomplete_details = {"reason": INCOMPLETE_REASONS[finish]}
    return build_response_object(
        info,
        response_id,
        created_at,
        output=output,
        status=status,
        usage=chat.get("usage"),
        error=error,
        incomplete_details=incomplete_details,
    )


def sse_event(event_type: str, data: dict) -> str:
    return f"event: {event_type}\ndata: {json.dumps(data, ensure_ascii=False)}\n\n"


def _iter_sse_payloads(chunk: Any) -> Iterator[dict | None]:
    if not isinstance(chunk, str):
        return
    for block in chunk.split("\n\n"):
        data_line = None
        for line in block.splitlines():
            if line.startswith("data:"):
                data_line = line[5:].strip()
        if data_line is None:
            continue
        if data_line == "[DONE]":
            yield None
            continue
        try:
            payload = json.loads(data_line)
        except (ValueError, TypeError):
            continue
        if isinstance(payload, dict):
            yield payload


def _error_payload(error: Any) -> dict:
    if isinstance(error, dict):
        return {
            "type": error.get("type") or "server_error",
            "code": error.get("code") or error.get("finish_reason"),
            "message": error.get("message") or "stream error",
            "param": error.get("param"),
        }
    return {"type": "server_error", "code": None, "message": str(error), "param": None}


class _StreamState:
    def __init__(self, info: RequestInfo, response_id: str, created_at: int) -> None:
        self.info = info
        self.response_id = response_id
        self.created_at = created_at
        self.sequence = 0
        self.output_index = 0
        self.output: list[dict] = []
        self.reasoning_id: str | None = None
        self.reasoning_index: int | None = None
        self.reasoning_text = ""
        self.reasoning_open = False
        self.message_id: str | None = None
        self.message_index: int | None = None
        self.message_text = ""
        self.message_open = False
        self.tool_items: dict[int, dict] = {}
        self.usage: Any = None
        self.finish: str | None = None

    def next_sequence(self) -> int:
        value = self.sequence
        self.sequence += 1
        return value

    def emit(self, event_type: str, data: dict) -> str:
        payload = {"type": event_type, "sequence_number": self.next_sequence()}
        payload.update(data)
        return sse_event(event_type, payload)

    def reasoning_delta(self, text: str) -> Iterator[str]:
        if not self.reasoning_open:
            self.reasoning_open = True
            self.reasoning_id = f"rs_{uuid.uuid4().hex}"
            self.reasoning_index = self.output_index
            self.output_index += 1
            item = {"id": self.reasoning_id, "type": "reasoning", "summary": []}
            yield self.emit("response.output_item.added", {"output_index": self.reasoning_index, "item": item})
            part = {"type": "summary_text", "text": ""}
            yield self.emit(
                "response.reasoning_summary_part.added",
                {"item_id": self.reasoning_id, "output_index": self.reasoning_index, "summary_index": 0, "part": part},
            )
        self.reasoning_text += text
        yield self.emit(
            "response.reasoning_summary_text.delta",
            {"item_id": self.reasoning_id, "output_index": self.reasoning_index, "summary_index": 0, "delta": text},
        )

    def close_reasoning(self) -> Iterator[str]:
        if not self.reasoning_open:
            return
        self.reasoning_open = False
        yield self.emit(
            "response.reasoning_summary_text.done",
            {"item_id": self.reasoning_id, "output_index": self.reasoning_index, "summary_index": 0, "text": self.reasoning_text},
        )
        part = {"type": "summary_text", "text": self.reasoning_text}
        yield self.emit(
            "response.reasoning_summary_part.done",
            {"item_id": self.reasoning_id, "output_index": self.reasoning_index, "summary_index": 0, "part": part},
        )
        item = {"id": self.reasoning_id, "type": "reasoning", "summary": [part]}
        self.output.append(item)
        yield self.emit("response.output_item.done", {"output_index": self.reasoning_index, "item": item})

    def message_delta(self, text: str) -> Iterator[str]:
        yield from self.close_reasoning()
        if not self.message_open:
            self.message_open = True
            self.message_id = f"msg_{uuid.uuid4().hex}"
            self.message_index = self.output_index
            self.output_index += 1
            item = {"id": self.message_id, "type": "message", "status": "in_progress", "role": "assistant", "content": []}
            yield self.emit("response.output_item.added", {"output_index": self.message_index, "item": item})
            part = {"type": "output_text", "text": "", "annotations": []}
            yield self.emit(
                "response.content_part.added",
                {"item_id": self.message_id, "output_index": self.message_index, "content_index": 0, "part": part},
            )
        self.message_text += text
        yield self.emit(
            "response.output_text.delta",
            {"item_id": self.message_id, "output_index": self.message_index, "content_index": 0, "delta": text},
        )

    def close_message(self) -> Iterator[str]:
        if not self.message_open:
            return
        self.message_open = False
        yield self.emit(
            "response.output_text.done",
            {"item_id": self.message_id, "output_index": self.message_index, "content_index": 0, "text": self.message_text},
        )
        part = {"type": "output_text", "text": self.message_text, "annotations": []}
        yield self.emit(
            "response.content_part.done",
            {"item_id": self.message_id, "output_index": self.message_index, "content_index": 0, "part": part},
        )
        item = {"id": self.message_id, "type": "message", "status": "completed", "role": "assistant", "content": [part]}
        self.output.append(item)
        yield self.emit("response.output_item.done", {"output_index": self.message_index, "item": item})

    def tool_delta(self, tool_calls: Any) -> Iterator[str]:
        yield from self.close_message()
        yield from self.close_reasoning()
        if not isinstance(tool_calls, list):
            return
        for call in tool_calls:
            if not isinstance(call, dict):
                continue
            index = call.get("index")
            if not isinstance(index, int):
                index = 0
            entry = self.tool_items.get(index)
            function = call.get("function")
            if not isinstance(function, dict):
                function = {}
            if entry is None:
                entry = {
                    "id": f"fc_{uuid.uuid4().hex}",
                    "call_id": call.get("id") or f"call_{uuid.uuid4().hex[:12]}",
                    "name": function.get("name") or "",
                    "arguments": "",
                    "output_index": self.output_index,
                    "open": True,
                }
                self.output_index += 1
                self.tool_items[index] = entry
                item = {
                    "id": entry["id"],
                    "type": "function_call",
                    "call_id": entry["call_id"],
                    "name": entry["name"],
                    "arguments": "",
                    "status": "in_progress",
                }
                yield self.emit("response.output_item.added", {"output_index": entry["output_index"], "item": item})
            if function.get("name") and not entry["name"]:
                entry["name"] = function["name"]
            arguments = function.get("arguments")
            if isinstance(arguments, str) and arguments:
                entry["arguments"] += arguments
                yield self.emit(
                    "response.function_call_arguments.delta",
                    {"item_id": entry["id"], "output_index": entry["output_index"], "delta": arguments},
                )

    def close_tools(self) -> Iterator[str]:
        for index in sorted(self.tool_items):
            entry = self.tool_items[index]
            if not entry.get("open"):
                continue
            entry["open"] = False
            yield self.emit(
                "response.function_call_arguments.done",
                {"item_id": entry["id"], "output_index": entry["output_index"], "arguments": entry["arguments"]},
            )
            item = {
                "id": entry["id"],
                "type": "function_call",
                "call_id": entry["call_id"],
                "name": entry["name"],
                "arguments": entry["arguments"],
                "status": "completed",
            }
            self.output.append(item)
            yield self.emit("response.output_item.done", {"output_index": entry["output_index"], "item": item})

    def close_all(self) -> Iterator[str]:
        yield from self.close_reasoning()
        yield from self.close_message()
        yield from self.close_tools()


async def translate_stream(
    chat_stream: AsyncIterator[str],
    info: RequestInfo,
    response_id: str,
    created_at: int,
    on_complete: Any = None,
) -> AsyncIterator[str]:
    state = _StreamState(info, response_id, created_at)
    initial = build_response_object(info, response_id, created_at, output=[], status="in_progress")
    yield state.emit("response.created", {"response": initial})
    yield state.emit("response.in_progress", {"response": initial})
    error: Any = None
    async for chunk in chat_stream:
        for payload in _iter_sse_payloads(chunk):
            if payload is None:
                continue
            if isinstance(payload.get("error"), dict):
                error = payload["error"]
                continue
            usage = payload.get("usage")
            if isinstance(usage, dict):
                state.usage = usage
            choices = payload.get("choices")
            if not isinstance(choices, list):
                continue
            for choice in choices:
                if not isinstance(choice, dict):
                    continue
                delta = choice.get("delta")
                if isinstance(delta, dict):
                    reasoning = delta.get("reasoning_content")
                    if isinstance(reasoning, str) and reasoning:
                        for line in state.reasoning_delta(reasoning):
                            yield line
                    content = delta.get("content")
                    if isinstance(content, str) and content:
                        for line in state.message_delta(content):
                            yield line
                    if delta.get("tool_calls"):
                        for line in state.tool_delta(delta["tool_calls"]):
                            yield line
                finish = choice.get("finish_reason")
                if isinstance(finish, str) and finish:
                    state.finish = finish
    for line in state.close_all():
        yield line
    if error is not None:
        payload = {"type": "error", "sequence_number": state.next_sequence()}
        payload.update(_error_payload(error))
        yield sse_event("error", payload)
        return
    final = build_response_object(info, response_id, created_at, output=state.output, status="completed", usage=state.usage)
    if callable(on_complete):
        on_complete(final)
    yield state.emit("response.completed", {"response": final})

from __future__ import annotations

import hashlib
import logging
import secrets
import time
from pathlib import Path

from ..config import settings
from .models import ByokAccount
from .store import UserStore

log = logging.getLogger("danyapi.byok")


def _hash_password(password: str, salt: str) -> str:
    return hashlib.sha256(f"{password}::{salt}".encode()).hexdigest()


class ByokManager:
    def __init__(self, store: UserStore, salt: str) -> None:
        self._store = store
        self._salt = salt
        self._session_keys: dict[str, tuple[str, float]] = {}
        self._max_sessions = 1024

    @classmethod
    def from_settings(cls) -> ByokManager | None:
        if not settings.byok_mode:
            return None
        try:
            base_dir = None
            cache_dir = settings.cache_dir
            if cache_dir:
                base_dir = Path(cache_dir) / "byok"
            store = UserStore(base_dir)
            return cls(store=store, salt=settings.byok_salt)
        except Exception as exc:
            log.error("failed to initialize byok manager: %s", exc)
            return None

    def login(self, username: str, password: str) -> str | None:
        user = self._store.get_user_by_name(username)
        if user is None:
            return None
        expected = _hash_password(password, self._salt)
        if user.get("password_hash") != expected:
            return None
        session_key = secrets.token_urlsafe(32)
        now = time.monotonic()
        self._session_keys[session_key] = (user["id"], now)
        self._cleanup_sessions()
        return session_key

    def register(self, username: str, password: str) -> tuple[bool, str]:
        existing = self._store.get_user_by_name(username)
        if existing is not None:
            return False, "username already taken"
        user_id = secrets.token_urlsafe(16)
        pw_hash = _hash_password(password, self._salt)
        created = self._store.register_user(user_id, username, pw_hash)
        if not created:
            return False, "registration failed"
        return True, user_id

    def logout(self, session_key: str) -> bool:
        return self._session_keys.pop(session_key, None) is not None

    def get_session_user(self, session_key: str) -> str | None:
        entry = self._session_keys.get(session_key)
        if entry is None:
            return None
        user_id, ts = entry
        if 0 < settings.session_ttl < time.monotonic() - ts:
            del self._session_keys[session_key]
            return None
        return user_id

    def add_token(self, user_id: str, provider: str, token_str: str) -> dict[str, str]:
        return self._store.add_token(user_id, provider, token_str)

    def remove_token(self, user_id: str, provider: str) -> bool:
        return self._store.remove_token(user_id, provider)

    def get_user_tokens(self, user_id: str) -> list[dict[str, str]]:
        return self._store.get_tokens_list(user_id)

    def get_provider_token(self, user_id: str, provider: str) -> str | None:
        return self._store.get_token(user_id, provider)

    def get_token_count(self, user_id: str, provider: str) -> int:
        return self._store.get_token_count(user_id, provider)

    def user_has_token(self, user_id: str, provider: str) -> bool:
        return self.get_token_count(user_id, provider) > 0

    def build_account(self, user_id: str, provider: str) -> ByokAccount | None:
        token = self.get_provider_token(user_id, provider)
        if token is None:
            return None
        acc_id = f"byok-{secrets.token_urlsafe(8)}"
        return ByokAccount(id=acc_id, provider=provider, token=token)

    def delete_account(self, user_id: str) -> bool:
        return self._store.delete_user(user_id)

    def auth_check(self, session_key: str) -> str | None:
        return self.get_session_user(session_key)

    def _cleanup_sessions(self) -> None:
        cutoff = time.monotonic() - (settings.session_ttl or 86400)
        stale = [k for k, (_, ts) in self._session_keys.items() if ts < cutoff]
        for k in stale:
            del self._session_keys[k]
        if len(self._session_keys) > self._max_sessions:
            oldest = min(self._session_keys, key=lambda k: self._session_keys[k][1])
            del self._session_keys[oldest]

    def restore(self) -> None:
        pass

from __future__ import annotations

import logging

from fastapi import Cookie, HTTPException, Request

log = logging.getLogger("danyapi.byok.middleware")


BYOK_SESSION_COOKIE = "byok_session"


class ByokAuth:
    def __init__(self, user_id: str | None) -> None:
        self.user_id = user_id
        self.authenticated: bool = user_id is not None


async def byok_dependency(request: Request, session_key: str | None = Cookie(None)) -> ByokAuth:
    from . import get_manager

    if session_key is None:
        return ByokAuth(user_id=None)

    mgr = get_manager()
    if mgr is None:
        return ByokAuth(user_id=None)

    user_id = mgr.auth_check(session_key)
    if user_id is None:
        raise HTTPException(status_code=401, detail="invalid or expired session")

    return ByokAuth(user_id=user_id)

from __future__ import annotations

import logging
from typing import Any

log = logging.getLogger("danyapi.byok")


class ByokUser:
    __slots__ = ("id", "password_hash", "username")

    def __init__(self, id: str, username: str, password_hash: str) -> None:
        self.id = id
        self.username = username
        self.password_hash = password_hash

    def to_dict(self) -> dict[str, Any]:
        return {"id": self.id, "username": self.username, "password_hash": self.password_hash}

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> ByokUser:
        return cls(id=data["id"], username=data["username"], password_hash=data["password_hash"])


class ByokAccount:
    __slots__ = ("id", "provider", "token")

    def __init__(self, id: str, provider: str, token: str) -> None:
        self.id = id
        self.provider = provider
        self.token = token

    def to_dict(self) -> dict[str, Any]:
        return {"id": self.id, "provider": self.provider, "token": self.token}

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> ByokAccount:
        return cls(id=data["id"], provider=data["provider"], token=data["token"])


class UserTokens:
    def __init__(self, user_id: str) -> None:
        self.user_id = user_id
        self.accounts: list[ByokAccount] = []
        self.updated_at: float = 0.0

    def add_or_replace(self, account: ByokAccount) -> None:
        for i, acc in enumerate(self.accounts):
            if acc.provider == account.provider:
                self.accounts[i] = account
                return
        self.accounts.append(account)

    def remove_by_provider(self, provider: str) -> bool:
        before = len(self.accounts)
        self.accounts = [a for a in self.accounts if a.provider != provider]
        return len(self.accounts) < before

    def get_by_provider(self, provider: str) -> ByokAccount | None:
        for acc in self.accounts:
            if acc.provider == provider:
                return acc
        return None

    def to_dict(self) -> dict[str, Any]:
        return {
            "user_id": self.user_id,
            "accounts": [a.to_dict() for a in self.accounts],
            "updated_at": self.updated_at,
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> UserTokens:
        ut = cls(user_id=data["user_id"])
        ut.accounts = [ByokAccount.from_dict(a) for a in data.get("accounts", [])]
        ut.updated_at = data.get("updated_at", 0.0)
        return ut

from __future__ import annotations

import json
import logging
import os
import threading
from pathlib import Path
from typing import Any

log = logging.getLogger("danyapi.byok.store")


def _cache_dir() -> Path:
    raw = os.environ.get("DANYAPI_CACHE_DIR", "")
    if raw and os.path.isdir(raw):
        return Path(raw)
    try:
        tmp = Path(os.getenv("TEMP", "/tmp"))  # nosec B108
        return tmp / "danyapi"
    except (OSError, ValueError):
        return Path("/tmp")  # nosec B108


class UserStore:
    def __init__(self, base_dir: Path | None = None) -> None:
        self._base = base_dir or (_cache_dir() / "byok")
        self._lock = threading.Lock()
        self._users: dict[str, dict[str, Any]] = {}
        self._names: dict[str, str] = {}
        self._loaded = False
        self._load()

    def _path_for_user(self, user_id: str) -> Path:
        return self._base / f"user_{user_id}.json"

    def _path_for_names(self) -> Path:
        return self._base / "names.json"

    def _ensure_dir(self) -> None:
        try:
            self._base.mkdir(parents=True, exist_ok=True)
        except OSError:
            pass

    def _load(self) -> None:
        self._ensure_dir()
        names_path = self._path_for_names()
        if names_path.exists():
            try:
                data = json.loads(names_path.read_text(encoding="utf-8"))
                if isinstance(data, dict):
                    self._users.update(data)
                    self._names = {v["username"]: k for k, v in data.items()}
            except (json.JSONDecodeError, OSError):
                self._users.clear()
                self._names.clear()
        self._loaded = True

    def save_all(self) -> None:
        self._ensure_dir()
        try:
            self._path_for_names().write_text(
                json.dumps(self._users, indent=2, ensure_ascii=False),
                encoding="utf-8",
            )
        except OSError as exc:
            log.warning("store save failed: %s", exc)

    def get_user_by_name(self, username: str) -> dict[str, Any] | None:
        user_id = self._names.get(username)
        if user_id is None:
            return None
        return self._users.get(user_id)

    def get_user(self, user_id: str) -> dict[str, Any] | None:
        return self._users.get(user_id)

    def register_user(self, user_id: str, username: str, password_hash: str) -> bool:
        if user_id in self._users:
            return False
        self._users[user_id] = {"id": user_id, "username": username, "password_hash": password_hash}
        self._names[username] = user_id
        self.save_all()
        return True

    def update_password(self, user_id: str, password_hash: str) -> None:
        user = self._users.get(user_id)
        if user is not None:
            user["password_hash"] = password_hash

    def delete_user(self, user_id: str) -> bool:
        if user_id not in self._users:
            return False
        name = self._users.pop(user_id, {}).get("username", "")
        self._names.pop(name, None)
        path = self._path_for_user(user_id)
        try:
            path.unlink(missing_ok=True)
        except OSError:
            pass
        self.save_all()
        return True

    def _match_provider(self, acc: dict[str, Any], provider: str) -> bool:
        return acc.get("provider") == provider

    def get_token_count(self, user_id: str, provider: str) -> int:
        accs = self._load_tokens(user_id)
        return sum(1 for a in accs if self._match_provider(a, provider))

    def get_tokens_list(self, user_id: str) -> list[dict[str, Any]]:
        accs = self._load_tokens(user_id)
        return [{"provider": a.get("provider", ""), "token": a.get("token", "")} for a in accs]

    def add_token(self, user_id: str, provider: str, token: str) -> dict[str, Any]:
        accs = self._load_tokens(user_id)
        found = False
        for acc in accs:
            if self._match_provider(acc, provider):
                acc["token"] = token
                found = True
                break
        if not found:
            from uuid import uuid4

            accs.append({"id": uuid4().hex, "provider": provider, "token": token})
        self._save_tokens(user_id, accs)
        return {"provider": provider, "token": token}

    def remove_token(self, user_id: str, provider: str) -> bool:
        accs = self._load_tokens(user_id)
        before = len(accs)
        accs = [a for a in accs if not self._match_provider(a, provider)]
        if len(accs) < before:
            self._save_tokens(user_id, accs)
            return True
        return False

    def get_token(self, user_id: str, provider: str) -> str | None:
        accs = self._load_tokens(user_id)
        for acc in accs:
            if self._match_provider(acc, provider):
                return acc.get("token")
        return None

    def _tokens_path(self, user_id: str) -> Path:
        return self._base / f"tokens_{user_id}.json"

    def _load_tokens(self, user_id: str) -> list[dict[str, Any]]:
        path = self._tokens_path(user_id)
        if path.exists():
            try:
                data = json.loads(path.read_text(encoding="utf-8"))
                if isinstance(data, list):
                    return data
            except (json.JSONDecodeError, OSError):
                pass
        return []

    def _save_tokens(self, user_id: str, accs: list[dict[str, Any]]) -> None:
        path = self._tokens_path(user_id)
        try:
            path.write_text(json.dumps(accs, indent=2, ensure_ascii=False), encoding="utf-8")
        except OSError as exc:
            log.warning("tokens save failed: %s", exc)

from __future__ import annotations

import math
import os
import uuid
from pathlib import Path
from typing import Any


def _noop_load_dotenv(*args: Any, **kwargs: Any) -> bool:
    return False


try:
    from dotenv import load_dotenv
except ImportError:
    load_dotenv = _noop_load_dotenv

load_dotenv(dotenv_path=Path(__file__).resolve().parents[1] / ".env", override=False)


def _env_int(key: str, default: int) -> int:
    try:
        return int(os.environ.get(key, default))
    except ValueError:
        return default


def _env_float(key: str, default: float) -> float:
    try:
        value = float(os.environ.get(key, default))
    except ValueError:
        return default
    return value if math.isfinite(value) else default


def _env_float_opt(key: str) -> float | None:
    raw = os.environ.get(key, "")
    try:
        value = float(raw) if raw else None
    except ValueError:
        return None
    if value is None or not math.isfinite(value):
        return None
    return value if value > 0 else None


def _env_str(key: str, default: str = "") -> str:
    return os.environ.get(key, default).strip()


def _uuid4_hex() -> str:
    return uuid.uuid4().hex


class Settings:
    def __init__(self) -> None:
        self.host = os.environ.get("DANYAPI_HOST", "0.0.0.0")
        self.port = _env_int("DANYAPI_PORT", 8000)
        tokens = [t.strip() for t in os.environ.get("DEEPSEEK_TOKENS", "").split(",") if t.strip()]
        self.deepseek_tokens = tokens
        qwen_tokens = [t.strip() for t in os.environ.get("QWEN_TOKENS", "").split(",") if t.strip()]
        self.qwen_tokens = qwen_tokens
        self.timeout = _env_float("DANYAPI_TIMEOUT", 60.0)
        self.acquire_timeout = _env_float_opt("DANYAPI_ACQUIRE_TIMEOUT")
        self.session_cache_size = _env_int("DANYAPI_SESSION_CACHE_SIZE", 128)
        self.session_ttl = _env_float("DANYAPI_SESSION_TTL_SECONDS", 3600.0)
        self.log_level = _env_str("DANYAPI_LOG_LEVEL", "INFO") or "INFO"
        self.log_file = _env_str("DANYAPI_LOG_FILE")
        self.log_max_bytes = _env_int("DANYAPI_LOG_MAX_BYTES", 10 * 1024 * 1024)
        self.log_backup_count = _env_int("DANYAPI_LOG_BACKUP_COUNT", 3)
        self.cache_dir = _env_str("DANYAPI_CACHE_DIR")
        self.cache_enabled = os.environ.get("DANYAPI_CACHE_DISABLED", "").strip().lower() not in ("1", "true", "yes", "on")
        self.human_delay_min = _env_float("DANYAPI_HUMAN_DELAY_MIN", 0.5)
        self.human_delay_max = _env_float("DANYAPI_HUMAN_DELAY_MAX", 3.0)
        self.usage_enabled = os.environ.get("DANYAPI_USAGE_ENABLED", "1").strip().lower() not in ("0", "false", "no", "off")
        self.usage_max_records = _env_int("DANYAPI_USAGE_MAX_RECORDS", 1000)
        self.auto_update = os.environ.get("DANYAPI_AUTO_UPDATE", "1").strip().lower() not in ("0", "false", "no", "off")
        self.byok_mode = os.environ.get("BYOK_MODE", "").strip().lower() in ("1", "true", "yes", "on")
        self.byok_salt = _env_str("BYOK_SALT") or _uuid4_hex()


settings = Settings()

from __future__ import annotations

import logging
import time
import uuid
from dataclasses import dataclass, field

import httpx

log = logging.getLogger("danyapi.deepseek")

BASE_URL = "https://chat.deepseek.com"

CLIENT_HEADERS = {
    "x-client-bundle-id": "com.deepseek.chat",
    "x-client-platform": "web",
    "x-client-version": "2.3.0",
    "x-client-locale": "en-US",
    "x-client-timezone-offset": "0",
}

USER_AGENT = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36"


def new_device_id() -> str:
    return str(uuid.uuid4())


@dataclass
class DeepSeekSession:
    id: str
    title: str = ""
    last_message_id: str | None = None
    accumulated_tokens: int = 0
    extra: dict = field(default_factory=dict)


class DeepSeekError(Exception):
    def __init__(self, biz_code: int, biz_msg: str):
        super().__init__(f"DeepSeek biz error {biz_code}: {biz_msg}")
        self.biz_code = biz_code
        self.biz_msg = biz_msg


class DeepSeekClient:
    def __init__(
        self,
        token: str | None = None,
        device_id: str | None = None,
        timeout: float = 60.0,
    ) -> None:
        self.token = token
        self.device_id = device_id or new_device_id()
        headers = {
            "User-Agent": USER_AGENT,
            "Referer": "https://chat.deepseek.com/",
            "Origin": "https://chat.deepseek.com",
            "Accept": "*/*",
            **CLIENT_HEADERS,
        }
        if token:
            headers["Authorization"] = f"Bearer {token}"
        self.http = httpx.AsyncClient(
            base_url=BASE_URL,
            headers=headers,
            timeout=httpx.Timeout(timeout),
            follow_redirects=True,
        )

    async def aclose(self) -> None:
        await self.http.aclose()

    async def _post(self, path: str, json_body: dict | None = None) -> dict:
        try:
            resp = await self.http.post(path, json=json_body)
        except httpx.HTTPError as exc:
            raise DeepSeekError(-1, f"http request failed: {exc}") from exc
        try:
            resp.raise_for_status()
        except httpx.HTTPStatusError as exc:
            raise DeepSeekError(exc.response.status_code, exc.response.text[:300]) from exc
        try:
            return resp.json()
        except ValueError as exc:
            raise DeepSeekError(-1, f"invalid JSON response from {path}: {resp.text[:300]}") from exc

    @staticmethod
    def _biz(resp: dict) -> dict:
        if not isinstance(resp, dict):
            raise DeepSeekError(-1, "unexpected response shape")
        code = resp.get("code")
        if code:
            raise DeepSeekError(code, resp.get("msg") or resp.get("message") or "")
        data = resp.get("data")
        if not isinstance(data, dict):
            data = {}
        if data.get("biz_code"):
            raise DeepSeekError(data["biz_code"], data.get("biz_msg", ""))
        biz_data = data.get("biz_data")
        return biz_data if isinstance(biz_data, dict) else {}

    async def check_auth(self) -> bool:
        try:
            resp = await self.http.get(
                "/api/v0/client/settings",
                params={"did": self.device_id, "scope": "main"},
            )
            return resp.json().get("code") == 0
        except (httpx.HTTPError, ValueError):
            return False

    async def get_user(self) -> dict:
        resp = await self._post("/api/v0/users", None)
        biz = self._biz(resp)
        return biz if isinstance(biz, dict) else {}

    async def create_pow_challenge(self, target_path: str = "/api/v0/chat/completion") -> dict:
        resp = await self._post("/api/v0/chat/create_pow_challenge", {"target_path": target_path})
        biz = self._biz(resp)
        challenge = biz.get("challenge")
        if not challenge:
            raise DeepSeekError(-1, "no pow challenge in response")
        log.debug("deepseek pow challenge OK (%s)", target_path)
        return challenge

    async def create_session(self) -> DeepSeekSession:
        started = time.monotonic()
        resp = await self._post("/api/v0/chat_session/create", {})
        biz = self._biz(resp)
        raw = biz.get("chat_session")
        if not isinstance(raw, dict) or not raw.get("id"):
            raise DeepSeekError(-1, "no chat_session in response")
        session = DeepSeekSession(id=raw["id"], title=raw.get("title") or "")
        log.info("deepseek create session success (%.0fms)", (time.monotonic() - started) * 1000)
        return session

    async def fetch_page(self, pinned: bool = False, count: int = 20) -> list[dict]:
        body = {"pinned": pinned, "count": count, "mode": "lte"}
        resp = await self._post("/api/v0/chat_session/fetch_page", body)
        biz = self._biz(resp)
        return (biz or {}).get("chat_sessions", []) or []

    async def upload_file(
        self,
        data: bytes,
        filename: str,
        content_type: str,
        model_type: str,
        thinking_enabled: bool = False,
        pow_headers: dict | None = None,
    ) -> dict:
        started = time.monotonic()
        headers = {
            "X-File-Size": str(len(data)),
            "X-Model-Type": model_type,
            "X-Thinking-Enabled": "1" if thinking_enabled else "0",
        }
        if pow_headers:
            headers.update(pow_headers)
        try:
            resp = await self.http.post(
                "/api/v0/file/upload_file",
                files={"file": (filename, data, content_type)},
                headers=headers,
            )
        except httpx.HTTPError as exc:
            raise DeepSeekError(-1, f"http request failed: {exc}") from exc
        try:
            resp.raise_for_status()
        except httpx.HTTPStatusError as exc:
            raise DeepSeekError(exc.response.status_code, exc.response.text[:300]) from exc
        try:
            payload = resp.json()
        except ValueError as exc:
            raise DeepSeekError(-1, "invalid JSON from file upload") from exc
        biz = self._biz(payload)
        file_info = biz.get("id") if isinstance(biz, dict) else None
        if not isinstance(biz, dict) or not file_info:
            raise DeepSeekError(-1, "file upload failed: no file id in response")
        log.info("deepseek upload file success: %s (%.0fms)", filename, (time.monotonic() - started) * 1000)
        return biz

    async def fetch_files(self, file_ids: list[str]) -> list[dict]:
        if not file_ids:
            return []
        try:
            resp = await self.http.get(
                "/api/v0/file/fetch_files",
                params={"file_ids": ",".join(file_ids)},
            )
        except httpx.HTTPError as exc:
            raise DeepSeekError(-1, f"http request failed: {exc}") from exc
        try:
            resp.raise_for_status()
        except httpx.HTTPStatusError as exc:
            raise DeepSeekError(exc.response.status_code, exc.response.text[:300]) from exc
        try:
            payload = resp.json()
        except ValueError as exc:
            raise DeepSeekError(-1, "invalid JSON from fetch_files") from exc
        biz = self._biz(payload)
        return (biz or {}).get("files", []) if isinstance(biz, dict) else []

    async def history_messages(self, chat_session_id: str) -> list[dict]:
        try:
            resp = await self.http.get(
                "/api/v0/chat/history_messages",
                params={"chat_session_id": chat_session_id},
            )
            resp.raise_for_status()
            payload = resp.json()
        except httpx.HTTPStatusError as exc:
            raise DeepSeekError(exc.response.status_code, exc.response.text[:300]) from exc
        except httpx.HTTPError as exc:
            raise DeepSeekError(-1, f"http request failed: {exc}") from exc
        except ValueError as exc:
            raise DeepSeekError(-1, "invalid JSON from history_messages") from exc
        biz = self._biz(payload)
        return biz.get("chat_messages", []) if isinstance(biz, dict) else []

    async def rename_session(self, chat_session_id: str, title: str) -> None:
        self._biz(
            await self._post(
                "/api/v0/chat_session/update_title",
                {
                    "chat_session_id": chat_session_id,
                    "title": title,
                },
            )
        )

    async def delete_session(self, chat_session_id: str) -> None:
        self._biz(await self._post("/api/v0/chat_session/delete", {"chat_session_id": chat_session_id}))

    async def completion(
        self,
        chat_session_id: str,
        prompt: str,
        parent_message_id: str | None,
        model_type: str = "default",
        thinking_enabled: bool = False,
        search_enabled: bool = False,
        ref_file_ids: list[str] | None = None,
        pow_headers: dict | None = None,
    ) -> httpx.Response:
        body = {
            "chat_session_id": chat_session_id,
            "parent_message_id": parent_message_id,
            "model_type": model_type,
            "prompt": prompt,
            "ref_file_ids": ref_file_ids or [],
            "thinking_enabled": thinking_enabled,
            "search_enabled": search_enabled,
            "action": None,
            "preempt": False,
        }
        headers = {"Accept": "text/event-stream"}
        if pow_headers:
            headers.update(pow_headers)
        req = self.http.build_request("POST", "/api/v0/chat/completion", json=body, headers=headers)
        return await self.http.send(req, stream=True)

    async def stop_stream(self, chat_session_id: str, message_id: str | None) -> None:
        self._biz(
            await self._post(
                "/api/v0/chat/stop_stream",
                {
                    "chat_session_id": chat_session_id,
                    "message_id": message_id,
                },
            )
        )

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#if defined(_WIN32)
#include <windows.h>
#else
#include <pthread.h>
#include <unistd.h>
#endif

#define RATE 136
#define ROUNDS 23
#define MAX_DIGITS 20

static const uint64_t RC[24] = {
    0x0000000000000001ULL, 0x0000000000008082ULL, 0x800000000000808aULL,
    0x8000000080008000ULL, 0x000000000000808bULL, 0x0000000080000001ULL,
    0x8000000080008081ULL, 0x8000000000008009ULL, 0x000000000000008aULL,
    0x0000000000000088ULL, 0x0000000080008009ULL, 0x000000008000000aULL,
    0x000000008000808bULL, 0x800000000000008bULL, 0x8000000000008089ULL,
    0x8000000000008003ULL, 0x8000000000008002ULL, 0x8000000000000080ULL,
    0x000000000000800aULL, 0x800000008000000aULL, 0x8000000080008081ULL,
    0x8000000000008080ULL, 0x0000000080000001ULL, 0x8000000080008008ULL,
};

static inline uint64_t rotl64(uint64_t x, int n) {
  return (x << n) | (x >> (64 - n));
}

static void keccak_f(uint64_t *s) {
  uint64_t bc[5], t, p[25];
  for (int r = 0; r < ROUNDS; r++) {
    bc[0] = s[0] ^ s[5] ^ s[10] ^ s[15] ^ s[20];
    bc[1] = s[1] ^ s[6] ^ s[11] ^ s[16] ^ s[21];
    bc[2] = s[2] ^ s[7] ^ s[12] ^ s[17] ^ s[22];
    bc[3] = s[3] ^ s[8] ^ s[13] ^ s[18] ^ s[23];
    bc[4] = s[4] ^ s[9] ^ s[14] ^ s[19] ^ s[24];

    t = bc[4] ^ rotl64(bc[1], 1);
    s[0] ^= t;
    s[5] ^= t;
    s[10] ^= t;
    s[15] ^= t;
    s[20] ^= t;
    t = bc[0] ^ rotl64(bc[2], 1);
    s[1] ^= t;
    s[6] ^= t;
    s[11] ^= t;
    s[16] ^= t;
    s[21] ^= t;
    t = bc[1] ^ rotl64(bc[3], 1);
    s[2] ^= t;
    s[7] ^= t;
    s[12] ^= t;
    s[17] ^= t;
    s[22] ^= t;
    t = bc[2] ^ rotl64(bc[4], 1);
    s[3] ^= t;
    s[8] ^= t;
    s[13] ^= t;
    s[18] ^= t;
    s[23] ^= t;
    t = bc[3] ^ rotl64(bc[0], 1);
    s[4] ^= t;
    s[9] ^= t;
    s[14] ^= t;
    s[19] ^= t;
    s[24] ^= t;

    p[0] = s[0];
    p[10] = rotl64(s[1], 1);
    p[20] = rotl64(s[2], 62);
    p[5] = rotl64(s[3], 28);
    p[15] = rotl64(s[4], 27);
    p[16] = rotl64(s[5], 36);
    p[1] = rotl64(s[6], 44);
    p[11] = rotl64(s[7], 6);
    p[21] = rotl64(s[8], 55);
    p[6] = rotl64(s[9], 20);
    p[7] = rotl64(s[10], 3);
    p[17] = rotl64(s[11], 10);
    p[2] = rotl64(s[12], 43);
    p[12] = rotl64(s[13], 25);
    p[22] = rotl64(s[14], 39);
    p[23] = rotl64(s[15], 41);
    p[8] = rotl64(s[16], 45);
    p[18] = rotl64(s[17], 15);
    p[3] = rotl64(s[18], 21);
    p[13] = rotl64(s[19], 8);
    p[14] = rotl64(s[20], 18);
    p[24] = rotl64(s[21], 2);
    p[9] = rotl64(s[22], 61);
    p[19] = rotl64(s[23], 56);
    p[4] = rotl64(s[24], 14);

    for (int y = 0; y < 25; y += 5) {
      uint64_t a0 = p[y], a1 = p[y + 1], a2 = p[y + 2], a3 = p[y + 3],
               a4 = p[y + 4];
      s[y] = a0 ^ ((~a1) & a2);
      s[y + 1] = a1 ^ ((~a2) & a3);
      s[y + 2] = a2 ^ ((~a3) & a4);
      s[y + 3] = a3 ^ ((~a4) & a0);
      s[y + 4] = a4 ^ ((~a0) & a1);
    }
    s[0] ^= RC[r + 1];
  }
}

static void absorb_prefix(uint64_t st[25], const uint8_t *prefix, size_t len) {
  memset(st, 0, 25 * sizeof(uint64_t));
  size_t off = 0;
  while (len - off >= RATE) {
    for (size_t i = 0; i < RATE; i += 8) {
      uint64_t w = 0;
      for (int b = 0; b < 8; b++)
        w |= (uint64_t)prefix[off + i + b] << (8 * b);
      st[i / 8] ^= w;
    }
    keccak_f(st);
    off += RATE;
  }
  for (size_t i = 0; i < len - off; i++)
    st[i / 8] ^= (uint64_t)prefix[off + i] << (8 * (i % 8));
}

static int to_digits(uint64_t v, char *buf) {
  char tmp[MAX_DIGITS];
  int n = 0;
  do {
    if (n >= MAX_DIGITS)
      break;
    tmp[n++] = (char)('0' + (int)(v % 10));
    v /= 10;
  } while (v > 0);
  for (int i = 0; i < n; i++)
    buf[i] = tmp[n - 1 - i];
  return n;
}

static void inc_digits(char *buf, int *dlen) {
  if (*dlen < 1 || *dlen > MAX_DIGITS)
    return;
  int i = *dlen - 1;
  while (i >= 0 && buf[i] == '9') {
    buf[i] = '0';
    i--;
  }
  if (i < 0) {
    buf[0] = '1';
    for (int j = 1; j <= *dlen; j++)
      buf[j] = '0';
    (*dlen)++;
  } else {
    buf[i]++;
  }
}

static int check_counter(const uint64_t base[25], size_t off0,
                         const char *digits, int dlen,
                         const uint8_t target[32]) {
  uint64_t st[25];
  memcpy(st, base, sizeof(st));
  size_t off = off0;
  for (int i = 0; i < dlen; i++) {
    st[off >> 3] ^= (uint64_t)(uint8_t)digits[i] << (8 * (off & 7));
    off++;
    if (off == RATE) {
      keccak_f(st);
      off = 0;
    }
  }
  st[off >> 3] ^= (uint64_t)0x06 << (8 * (off & 7));
  off++;
  if (off == RATE) {
    keccak_f(st);
  }
  st[16] ^= (uint64_t)0x80 << 56;
  keccak_f(st);
  return memcmp(st, target, 32) == 0;
}

typedef struct {
  const uint64_t *base;
  size_t off0;
  const uint8_t *target;
  uint64_t start;
  uint64_t end;
  uint64_t result;
} WorkerArgs;

static void run_worker(WorkerArgs *a) {
  a->result = UINT64_MAX;
  if (a->start >= a->end)
    return;
  char digits[MAX_DIGITS];
  int dlen = to_digits(a->start, digits);
  for (uint64_t c = a->start; c < a->end; c++) {
    if (check_counter(a->base, a->off0, digits, dlen, a->target)) {
      a->result = c;
      return;
    }
    inc_digits(digits, &dlen);
  }
}

#if defined(_WIN32)
static DWORD WINAPI worker(LPVOID arg) {
  run_worker((WorkerArgs *)arg);
  return 0;
}
#else
static void *worker(void *arg) {
  run_worker((WorkerArgs *)arg);
  return NULL;
}
#endif

static int detect_threads(void) {
#if defined(_WIN32)
  SYSTEM_INFO si;
  GetSystemInfo(&si);
  int n = (int)si.dwNumberOfProcessors;
  return n > 0 ? n : 1;
#else
  long n = sysconf(_SC_NPROCESSORS_ONLN);
  return n > 0 ? (int)n : 1;
#endif
}

static int hex_to_bytes(const char *hex, uint8_t *out) {
  size_t n = strlen(hex);
  if (n % 2)
    return -1;
  for (size_t i = 0; i < n; i += 2) {
    int hi = hex[i], lo = hex[i + 1];
    int hv = (hi >= '0' && hi <= '9')   ? hi - '0'
             : (hi >= 'a' && hi <= 'f') ? hi - 'a' + 10
             : (hi >= 'A' && hi <= 'F') ? hi - 'A' + 10
                                        : -1;
    int lv = (lo >= '0' && lo <= '9')   ? lo - '0'
             : (lo >= 'a' && lo <= 'f') ? lo - 'a' + 10
             : (lo >= 'A' && lo <= 'F') ? lo - 'A' + 10
                                        : -1;
    if (hv < 0 || lv < 0)
      return -1;
    out[i / 2] = (uint8_t)((hv << 4) | lv);
  }
  return (int)(n / 2);
}

static const char *find_json_str(const char *json, const char *key, char *buf,
                                 size_t bufsz) {
  char pat[64];
  snprintf(pat, sizeof(pat), "\"%s\"", key);
  const char *p = strstr(json, pat);
  if (!p)
    return NULL;
  p = strchr(p + strlen(pat), ':');
  if (!p)
    return NULL;
  p++;
  while (*p == ' ' || *p == '\t')
    p++;
  if (*p != '"')
    return NULL;
  p++;
  size_t i = 0;
  while (*p && *p != '"' && i + 1 < bufsz)
    buf[i++] = *p++;
  buf[i] = '\0';
  return buf;
}

static long long find_json_ll(const char *json, const char *key) {
  char pat[64];
  snprintf(pat, sizeof(pat), "\"%s\"", key);
  const char *p = strstr(json, pat);
  if (!p)
    return -1;
  p = strchr(p + strlen(pat), ':');
  if (!p)
    return -1;
  return strtoll(p + 1, NULL, 10);
}

int main(void) {
  char input[8192];
  size_t n = fread(input, 1, sizeof(input) - 1, stdin);
  input[n] = '\0';

  char challenge[128] = {0}, salt[4096] = {0};
  if (!find_json_str(input, "challenge", challenge, sizeof(challenge)) ||
      !find_json_str(input, "salt", salt, sizeof(salt))) {
    puts("{\"error\":\"missing challenge/salt\"}");
    return 1;
  }
  long long expire_at = find_json_ll(input, "expire_at");
  long long difficulty = find_json_ll(input, "difficulty");
  if (expire_at < 0 || difficulty <= 0) {
    puts("{\"error\":\"bad expire_at/difficulty\"}");
    return 1;
  }

  uint8_t target[32];
  if (hex_to_bytes(challenge, target) != 32) {
    puts("{\"error\":\"bad challenge hex\"}");
    return 1;
  }

  char prefix[4120];
  int plen = snprintf(prefix, sizeof(prefix), "%s_%lld_", salt, expire_at);
  if (plen < 0 || (size_t)plen >= sizeof(prefix)) {
    puts("{\"error\":\"salt too long\"}");
    return 1;
  }

  uint64_t base[25];
  absorb_prefix(base, (const uint8_t *)prefix, (size_t)plen);
  size_t off0 = (size_t)plen % RATE;

  uint64_t limit =
      difficulty < 2000000000LL ? (uint64_t)difficulty : 2000000000ULL;
  if (limit == 0) {
    puts("{\"error\":\"answer not found in range\"}");
    return 1;
  }

  int nthreads = detect_threads();
  const char *env = getenv("POW_SOLVER_THREADS");
  if (env && env[0]) {
    int v = atoi(env);
    if (v > 0)
      nthreads = v;
  }
#if defined(_WIN32)
  if (nthreads > 64)
    nthreads = 64;
#endif
  if ((uint64_t)nthreads > limit)
    nthreads = (int)limit;

  WorkerArgs *args = (WorkerArgs *)calloc((size_t)nthreads, sizeof(WorkerArgs));
  if (!args) {
    puts("{\"error\":\"out of memory\"}");
    return 1;
  }
#if defined(_WIN32)
  HANDLE *threads = (HANDLE *)calloc((size_t)nthreads, sizeof(HANDLE));
#else
  pthread_t *threads = (pthread_t *)calloc((size_t)nthreads, sizeof(pthread_t));
#endif
  if (!threads) {
    free(args);
    puts("{\"error\":\"out of memory\"}");
    return 1;
  }

  uint64_t chunk = (limit + (uint64_t)nthreads - 1) / (uint64_t)nthreads;
  for (int i = 0; i < nthreads; i++) {
    args[i].base = base;
    args[i].off0 = off0;
    args[i].target = target;
    args[i].start = (uint64_t)i * chunk;
    uint64_t end = args[i].start + chunk;
    args[i].end = end > limit ? limit : end;
    args[i].result = UINT64_MAX;
#if defined(_WIN32)
    threads[i] = CreateThread(NULL, 0, worker, &args[i], 0, NULL);
    if (!threads[i])
      run_worker(&args[i]);
#else
    pthread_create(&threads[i], NULL, worker, &args[i]);
#endif
  }

#if defined(_WIN32)
  for (int i = 0; i < nthreads; i++) {
    if (threads[i]) {
      WaitForSingleObject(threads[i], INFINITE);
      CloseHandle(threads[i]);
    }
  }
#else
  for (int i = 0; i < nthreads; i++)
    pthread_join(threads[i], NULL);
#endif

  uint64_t best = UINT64_MAX;
  for (int i = 0; i < nthreads; i++)
    if (args[i].result < best)
      best = args[i].result;

  free(threads);
  free(args);

  if (best != UINT64_MAX) {
    printf("{\"answer\":%llu}\n", (unsigned long long)best);
    return 0;
  }
  puts("{\"error\":\"answer not found in range\"}");
  return 1;
}

const fs = require('fs');
const path = require('path');
const wasmPath = path.join(__dirname, 'sha3_wasm_bg.wasm');
const wasmBuf = fs.readFileSync(wasmPath);

let instancePromise = null;
function getInstance() {
  if (!instancePromise) instancePromise = WebAssembly.instantiate(wasmBuf, {});
  return instancePromise;
}

function solve(challenge, prefix, difficulty) {
  return getInstance().then(({ instance }) => {
    const { memory, wasm_solve, __wbindgen_add_to_stack_pointer, __wbindgen_export_0: malloc } = instance.exports;
    let m = new Uint8Array(memory.buffer);
    let view = new DataView(memory.buffer);
    function refresh() { m = new Uint8Array(memory.buffer); view = new DataView(memory.buffer); }
    function writeStr(ptr, s) { for (let i = 0; i < s.length; i++) m[ptr + i] = s.charCodeAt(i); }
    const hexPtr = malloc(challenge.length, 1); refresh(); writeStr(hexPtr, challenge);
    const pPtr = malloc(prefix.length, 1); refresh(); writeStr(pPtr, prefix);
    const retptr = __wbindgen_add_to_stack_pointer(-16);
    try {
      wasm_solve(retptr, hexPtr, challenge.length, pPtr, prefix.length, difficulty);
      refresh();
      const status = view.getInt32(retptr, true);
      const value = view.getFloat64(retptr + 8, true);
      return status !== 0 ? Number(value) : null;
    } finally {
      __wbindgen_add_to_stack_pointer(16);
    }
  });
}

let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => { input += chunk; });
process.stdin.on('end', () => {
  let req;
  try {
    req = JSON.parse(input);
  } catch (e) {
    process.stdout.write(JSON.stringify({ error: 'bad json: ' + e.message }));
    process.exit(1);
    return;
  }
  const prefix = `${req.salt}_${req.expire_at}_`;
  solve(req.challenge, prefix, req.difficulty)
    .then(answer => {
      if (answer === null) {
        process.stdout.write(JSON.stringify({ error: 'solver returned no answer' }));
      } else {
        process.stdout.write(JSON.stringify({ answer }));
      }
    })
    .catch(err => {
      process.stdout.write(JSON.stringify({ error: String(err && err.message || err) }));
      process.exit(1);
    });
});

from __future__ import annotations

import logging
import re
import sys
from logging.handlers import RotatingFileHandler
from pathlib import Path

DEFAULT_FORMAT = "(%(asctime)s) %(message)s"
DEFAULT_DATEFMT = "%H:%M:%S"
RESET = "\033[0m"
LEVEL_COLORS = {
    "INFO": "\033[37m",
    "WARNING": "\033[33m",
    "ERROR": "\033[31m",
    "CRITICAL": "\033[31m",
}
SUCCESS_COLOR = "\033[32m"
SUCCESS_PATTERN = re.compile(r"\b(ok|ready|success)\b", re.IGNORECASE)
LIFECYCLE_MESSAGES = {
    "Waiting for application startup.",
    "Application startup complete.",
    "Waiting for application shutdown.",
    "Application shutdown complete.",
}
LIFECYCLE_PREFIXES = ("Started server process", "Finished server process")
UVICORN_RUNNING = "Uvicorn running on"
DANYAPI_RUNNING = "DanyAPI running on"
CONSOLE_HANDLER_NAME = "danyapi-console"
FILE_HANDLER_NAME = "danyapi-file"
DEFAULT_LOG_LEVEL = "INFO"
DEFAULT_MAX_BYTES = 10 * 1024 * 1024
DEFAULT_BACKUP_COUNT = 3
_FALLBACK_LEVEL_NAMES = {"CRITICAL", "ERROR", "WARNING", "INFO", "DEBUG", "NOTSET"}


def _level_names() -> set[str]:
    get_mapping = getattr(logging, "getLevelNamesMapping", None)
    if get_mapping is not None:
        return set(get_mapping())
    return set(_FALLBACK_LEVEL_NAMES)


def _resolve_level(level: str | None) -> str:
    normalized = str(level or "").strip().upper()
    if normalized in _level_names():
        return normalized
    return DEFAULT_LOG_LEVEL


def _coerce_max_bytes(value: int) -> int:
    if value and value > 0:
        return value
    return DEFAULT_MAX_BYTES


def _coerce_backup_count(value: int) -> int:
    if value >= 0:
        return value
    return DEFAULT_BACKUP_COUNT


def _make_file_handler(log_file: str, max_bytes: int, backup_count: int) -> RotatingFileHandler:
    path = Path(log_file)
    path.parent.mkdir(parents=True, exist_ok=True)
    handler = RotatingFileHandler(
        str(path),
        maxBytes=max_bytes,
        backupCount=backup_count,
        encoding="utf-8",
    )
    handler.setFormatter(logging.Formatter(DEFAULT_FORMAT, DEFAULT_DATEFMT))
    return handler


class _LifecycleFilter(logging.Filter):
    def filter(self, record: logging.LogRecord) -> bool:
        if record.name == "uvicorn.access":
            return False
        message = record.getMessage()
        if message in LIFECYCLE_MESSAGES:
            return False
        if message.startswith(LIFECYCLE_PREFIXES):
            return False
        if UVICORN_RUNNING in message:
            record.msg = message.replace(UVICORN_RUNNING, DANYAPI_RUNNING)
            record.args = ()
        return True


def _is_success(message: str) -> bool:
    return SUCCESS_PATTERN.search(message) is not None


class _ColorFormatter(logging.Formatter):
    def __init__(self) -> None:
        super().__init__(DEFAULT_FORMAT, DEFAULT_DATEFMT)
        stream = sys.stderr if sys.stderr is not None else sys.stdout
        self._use_color = bool(stream and stream.isatty())

    def format(self, record: logging.LogRecord) -> str:
        text = super().format(record)
        if not self._use_color:
            return text
        color = LEVEL_COLORS.get(record.levelname, "")
        if record.levelname == "INFO" and _is_success(record.getMessage()):
            color = SUCCESS_COLOR
        if not color:
            return text
        return f"{color}{text}{RESET}"


def _has_handler(root: logging.Logger, name: str) -> bool:
    return any(getattr(handler, "name", None) == name for handler in root.handlers)


def _enable_windows_vt() -> None:
    if sys.platform != "win32":
        return
    try:
        import ctypes
        from ctypes import wintypes

        kernel32 = ctypes.windll.kernel32
        kernel32.GetStdHandle.argtypes = [wintypes.DWORD]
        kernel32.GetStdHandle.restype = wintypes.HANDLE
        kernel32.GetConsoleMode.argtypes = [wintypes.HANDLE, ctypes.POINTER(wintypes.DWORD)]
        kernel32.GetConsoleMode.restype = wintypes.BOOL
        kernel32.SetConsoleMode.argtypes = [wintypes.HANDLE, wintypes.DWORD]
        kernel32.SetConsoleMode.restype = wintypes.BOOL
        enable_virtual_terminal_processing = 0x0004
        invalid_handle = wintypes.HANDLE(-1).value
        for std_handle in (-11, -12):
            handle = kernel32.GetStdHandle(std_handle)
            if not handle or handle == invalid_handle:
                continue
            mode = wintypes.DWORD()
            if not kernel32.GetConsoleMode(handle, ctypes.byref(mode)):
                continue
            if not mode.value & enable_virtual_terminal_processing:
                kernel32.SetConsoleMode(handle, mode.value | enable_virtual_terminal_processing)
    except Exception:
        logging.getLogger(__name__).debug("failed to enable windows VT mode", exc_info=True)


def configure() -> None:
    from danyapi.config import settings

    _enable_windows_vt()

    for noisy in ("httpx", "httpcore"):
        logging.getLogger(noisy).setLevel(logging.WARNING)

    level = _resolve_level(settings.log_level)
    root = logging.getLogger()
    root.setLevel(level)

    if not _has_handler(root, CONSOLE_HANDLER_NAME):
        console = logging.StreamHandler()
        console.name = CONSOLE_HANDLER_NAME
        console.setLevel(level)
        console.setFormatter(_ColorFormatter())
        console.addFilter(_LifecycleFilter())
        root.addHandler(console)

    if settings.log_file and not _has_handler(root, FILE_HANDLER_NAME):
        path = Path(settings.log_file)
        if path.is_dir():
            logging.getLogger(__name__).warning(
                "log file %s is a directory, using console only",
                path,
            )
        else:
            try:
                file_handler = _make_file_handler(
                    str(path),
                    _coerce_max_bytes(settings.log_max_bytes),
                    _coerce_backup_count(settings.log_backup_count),
                )
            except OSError as exc:
                logging.getLogger(__name__).warning("cannot open log file %s: %s, using console only", path, exc)
            else:
                file_handler.name = FILE_HANDLER_NAME
                file_handler.setLevel(level)
                file_handler.addFilter(_LifecycleFilter())
                root.addHandler(file_handler)


def uvicorn_log_config() -> dict:
    from danyapi.config import settings

    level = _resolve_level(settings.log_level)
    return {
        "version": 1,
        "disable_existing_loggers": False,
        "loggers": {
            "uvicorn": {"handlers": [], "level": level, "propagate": True},
            "uvicorn.error": {"handlers": [], "level": level, "propagate": True},
            "uvicorn.access": {"handlers": [], "level": level, "propagate": True},
        },
    }

from __future__ import annotations

import asyncio
import base64
import json
import logging
import struct
import subprocess
from pathlib import Path

log = logging.getLogger("danyapi.pow")

_MASK64 = (1 << 64) - 1

_RC = [
    0x0000000000000001,
    0x0000000000008082,
    0x800000000000808A,
    0x8000000080008000,
    0x000000000000808B,
    0x0000000080000001,
    0x8000000080008081,
    0x8000000000008009,
    0x000000000000008A,
    0x0000000000000088,
    0x0000000080008009,
    0x000000008000000A,
    0x000000008000808B,
    0x800000000000008B,
    0x8000000000008089,
    0x8000000000008003,
    0x8000000000008002,
    0x8000000000000080,
    0x000000000000800A,
    0x800000008000000A,
    0x8000000080008081,
    0x8000000000008080,
    0x0000000080000001,
    0x8000000080008008,
]

_ROT = [
    [0, 36, 3, 41, 18],
    [1, 44, 10, 45, 2],
    [62, 6, 43, 15, 61],
    [28, 55, 25, 21, 56],
    [27, 20, 39, 8, 14],
]

_ROUNDS = 23

_ROUND_CONSTANTS = _RC[1:24]

_PYTHON_SOLVE_LIMIT = 2_000_000


def _rol(x: int, n: int) -> int:
    return ((x << n) | (x >> (64 - n))) & _MASK64


def _keccak_f(state: list[int]) -> list[int]:
    for rc in _ROUND_CONSTANTS:
        c = [state[x] ^ state[x + 5] ^ state[x + 10] ^ state[x + 15] ^ state[x + 20] for x in range(5)]
        d = [c[(x - 1) % 5] ^ _rol(c[(x + 1) % 5], 1) for x in range(5)]
        for x in range(5):
            for y in range(5):
                state[x + 5 * y] ^= d[x]
        b = [0] * 25
        for x in range(5):
            for y in range(5):
                b[y + 5 * ((2 * x + 3 * y) % 5)] = _rol(state[x + 5 * y], _ROT[x][y])
        for x in range(5):
            for y in range(5):
                state[x + 5 * y] = b[x + 5 * y] ^ ((~b[(x + 1) % 5 + 5 * y]) & b[(x + 2) % 5 + 5 * y])
        state[0] ^= rc
    return state


def deepseek_hash_v1(data: bytes, output_bytes: int = 32) -> bytes:
    rate = 136
    state = [0] * 25
    block = bytearray(data)
    block.append(0x06)
    padlen = rate - (len(block) % rate)
    block += bytes(padlen)
    block[-1] |= 0x80
    for off in range(0, len(block), rate):
        chunk = block[off : off + rate]
        for i in range(0, rate, 8):
            state[i // 8] ^= struct.unpack_from("<Q", chunk, i)[0]
        _keccak_f(state)
    out = bytearray()
    while len(out) < output_bytes:
        take = min(rate, output_bytes - len(out))
        for i in range(0, take, 8):
            out += struct.pack("<Q", state[i // 8])
        if len(out) < output_bytes:
            _keccak_f(state)
    return bytes(out[:output_bytes])


def deepseek_hash_v1_hex(data: bytes) -> str:
    return deepseek_hash_v1(data).hex()


_SOLVER_DIR = Path(__file__).resolve().parent / "deepseek"
_NODE_SOLVER = _SOLVER_DIR / "pow_solver.js"


def _find_native_solver() -> Path | None:
    for name in ("pow_solver.exe", "pow_solver"):
        p = _SOLVER_DIR / name
        if p.exists():
            return p
    return None


def solve_python(challenge_hex: str, salt: str, expire_at: int, difficulty: int) -> int | None:
    prefix = f"{salt}_{expire_at}_".encode()
    target = challenge_hex
    limit = max(0, min(int(difficulty), _PYTHON_SOLVE_LIMIT))
    for c in range(limit):
        if deepseek_hash_v1_hex(prefix + str(c).encode()) == target:
            return c
    return None


def _run_solver(script: Path, challenge_hex: str, salt: str, expire_at: int, difficulty: int) -> int | None:
    payload = {
        "challenge": challenge_hex,
        "salt": salt,
        "expire_at": expire_at,
        "difficulty": int(difficulty),
    }
    if script.suffix == ".js":
        cmd = ["node", str(script)]
    else:
        cmd = [str(script)]
    proc = subprocess.run(
        cmd,
        input=json.dumps(payload),
        capture_output=True,
        text=True,
        timeout=60,
        check=False,
    )
    if proc.returncode != 0:
        raise RuntimeError(f"{script.name} failed: {proc.stderr[:300]}")
    out = json.loads(proc.stdout.strip())
    if "error" in out:
        raise RuntimeError(out["error"])
    return out.get("answer")


def solve_native(challenge_hex: str, salt: str, expire_at: int, difficulty: int) -> int | None:
    native = _find_native_solver()
    if native is None:
        raise FileNotFoundError("native pow_solver binary not built")
    return _run_solver(native, challenge_hex, salt, expire_at, difficulty)


def solve_node(challenge_hex: str, salt: str, expire_at: int, difficulty: int) -> int | None:
    if not _NODE_SOLVER.exists():
        raise FileNotFoundError("pow_solver.js not found")
    return _run_solver(_NODE_SOLVER, challenge_hex, salt, expire_at, difficulty)


async def solve_challenge(challenge_hex: str, salt: str, expire_at: int, difficulty: int) -> int | None:
    for solver in (solve_native, solve_node, solve_python):
        try:
            answer = await asyncio.to_thread(solver, challenge_hex, salt, expire_at, difficulty)
            if answer is not None:
                return answer
        except Exception as exc:
            log.warning("pow solver %s failed (%s), trying next", solver.__name__, exc)
    return None


class PowManager:
    def __init__(self) -> None:
        self._lock = asyncio.Lock()
        self._header: dict | None = None
        self._refill: asyncio.Task | None = None

    async def _build(self, fetch) -> dict:
        challenge = await fetch()
        missing = [k for k in ("challenge", "salt", "algorithm", "signature", "target_path") if not challenge.get(k)]
        if missing:
            raise RuntimeError(f"pow challenge missing fields: {', '.join(missing)}")
        expire_at = challenge.get("expire_at")
        difficulty = challenge.get("difficulty")
        if isinstance(expire_at, bool) or not isinstance(expire_at, (int, float)):
            raise RuntimeError("pow challenge has invalid expire_at")
        if isinstance(difficulty, bool) or not isinstance(difficulty, (int, float)) or difficulty <= 0:
            raise RuntimeError("pow challenge has invalid difficulty")
        answer = await solve_challenge(
            challenge["challenge"],
            challenge["salt"],
            int(expire_at),
            int(difficulty),
        )
        if answer is None:
            raise RuntimeError("pow solver returned no answer")
        payload = {
            "algorithm": challenge["algorithm"],
            "challenge": challenge["challenge"],
            "salt": challenge["salt"],
            "answer": answer,
            "signature": challenge["signature"],
            "target_path": challenge["target_path"],
        }
        raw = json.dumps(payload, separators=(",", ":")).encode()
        return {"X-DS-PoW-Response": base64.b64encode(raw).decode()}

    async def _refill_if_empty(self, fetch) -> None:
        try:
            async with self._lock:
                if self._header is None:
                    self._header = await self._build(fetch)
        except Exception as exc:
            log.warning("pow prefetch failed: %s", exc)
        finally:
            self._refill = None

    def _kick_refill(self, fetch) -> None:
        if self._refill is None or self._refill.done():
            self._refill = asyncio.create_task(self._refill_if_empty(fetch))

    async def make_header(self, fetch) -> dict:
        async with self._lock:
            if self._header is not None:
                header = self._header
                self._header = None
            else:
                header = None
        if header is not None:
            self._kick_refill(fetch)
            return header
        header = await self._build(fetch)
        self._kick_refill(fetch)
        return header

from __future__ import annotations
import asyncio import logging from typing import Any
from ..sessions import SessionRegistry from ..store import JsonStore from .client import QwenClient, QwenSession
log = logging.getLogger("danyapi.qwen")
class QwenSessionRegistry(SessionRegistry): def __init__( self, client: QwenClient, maxsize: int = 128, ttl: float = 0.0, store: JsonStore | None = None, key_prefix: str = "", ) -> None: super().__init__(client, maxsize, ttl, store=store, key_prefix=key_prefix)
def _serialize(self, session: QwenSession) -> dict: return { "id": session.id, "title": session.title, "last_response_id": session.last_response_id, "model": session.model, "accumulated_input_tokens": getattr(session, "accumulated_input_tokens", 0), "accumulated_output_tokens": getattr(session, "accumulated_output_tokens", 0), }
def _deserialize(self, record: Any) -> QwenSession: if not isinstance(record, dict) or not record.get("id"): raise ValueError("invalid session record") input_tokens = record.get("accumulated_input_tokens") output_tokens = record.get("accumulated_output_tokens") return QwenSession( id=record["id"], title=record.get("title") or "", last_response_id=record.get("last_response_id"), model=record.get("model"), accumulated_input_tokens=int(input_tokens) if isinstance(input_tokens, (int, float)) else 0, accumulated_output_tokens=int(output_tokens) if isinstance(output_tokens, (int, float)) else 0, )
async def _create(self, **kwargs) -> QwenSession: model = kwargs.get("model") or "" chat_id = await self._client.create_chat(model=model, chat_mode="normal") return QwenSession(id=chat_id, model=model)
def _reuse(self, session: QwenSession, session_id: str, **kwargs) -> bool: wanted = kwargs.get("model") or "" if session.model is None: session.model = wanted return True return session.model == wanted
def _update_last(self, session: QwenSession, message_id: str) -> None: session.last_response_id = message_id
async def obtain(self, session_id: str | None = None, model: str | None = None, **kwargs) -> tuple[QwenSession, str]: return await super().obtain(session_id, model=model or "")
class QwenAccount: __slots__ = ("broken", "client", "index", "sem", "sessions", "stable_id")
def __init__( self, index: int, client: QwenClient, session_cache_size: int = 128, ttl: float = 0.0, store: JsonStore | None = None, stable_id: str | None = None, ) -> None: self.index = index self.client = client self.sem = asyncio.Semaphore(1) self.sessions = QwenSessionRegistry(client, session_cache_size, ttl, store=store, key_prefix=f"{index}:") self.stable_id = stable_id self.broken = False
def mark_broken(self) -> None: if not self.broken: self.broken = True log.warning("qwen account #%d marked broken (invalid/expired token)", self.index)
@property def label(self) -> str: return f"qwen-acct#{self.index}"

from __future__ import annotations
import asyncio import json import logging import random import time import uuid from collections.abc import Iterator from typing import Any
import httpx from fastapi import HTTPException
from .. import tools as toolemu from ..accounts import account_lock from ..config import settings from ..deepseek.stream import IncrementalSSE from ..usage import record_usage from .client import QwenClient, QwenError from .stream import QwenStreamReconstructor, error_code
log = logging.getLogger("danyapi.qwen.api")
MAX_RETRIES = 5 RETRY_BACKOFF_SEC = 1.0 RETRY_BACKOFF_MAX_SEC = 8.0
RETRYABLE_HTTP_STATUSES = {408, 425, 429, 500, 502, 503, 504} STALE_SESSION_STATUSES = {400, 404}
def _retry_delay(attempt: int) -> float: return min(RETRY_BACKOFF_SEC * (2 ** (attempt - 1)), RETRY_BACKOFF_MAX_SEC)
def _is_retryable_http(exc: HTTPException) -> bool: return exc.status_code in RETRYABLE_HTTP_STATUSES
RETRYABLE_ERROR_CODES = { "Too_Many_Requests", "RateLimited", "quotaLimited", "Internal_Server_Error", "Server_Busy", "server_busy", "Busy", "busy", }
AUTH_ERROR_CODES = { "unauthorized", "Unauthorized", "Invalid token", "Forbidden", "forbidden", }
RATE_LIMIT_ERROR_CODES = { "Too_Many_Requests", "RateLimited", "quotaLimited", }
CONTEXT_LIMIT_MARKERS = ("context", "maxinput", "toolong", "lengthexceeded", "tokenlimit")
class ContextLimitError(Exception): pass
def _is_context_limit_code(code) -> bool: if not isinstance(code, str) or not code: return False compact = "".join(ch for ch in code.lower() if ch.isalnum()) return any(marker in compact for marker in CONTEXT_LIMIT_MARKERS)
def _is_context_limit(rec: QwenStreamReconstructor) -> bool: return _is_context_limit_code(error_code(rec.error))
def _drop_session(pool, account, session_key) -> None: pool.forget(session_key) pool.forget_context(session_key) account.sessions.forget(session_key)
def _error_status(code) -> int: if code in RATE_LIMIT_ERROR_CODES: return 429 if code in AUTH_ERROR_CODES: return 401 return 502
def _handle_account_error(account, exc: Exception) -> None: code = getattr(exc, "code", None) if code in AUTH_ERROR_CODES: account.mark_broken() log.warning("qwen account #%d auth error %s: %s", account.index, code, exc) else: log.warning("qwen account #%d error: %s", account.index, exc)
async def _prepare_session(account, pool, existing_sid: str | None, model_id: str, context_seq: tuple[str, ...] | None = None): try: session, session_key = await account.sessions.obtain(existing_sid, model_id) except QwenError as exc: _handle_account_error(account, exc) raise HTTPException(_error_status(exc.code), f"Qwen error: {exc}") from exc pool.register(account.index, session_key) if existing_sid and session_key != existing_sid: pool.forget(existing_sid) pool.forget_context(existing_sid) account.sessions.forget(existing_sid) if context_seq: pool.index_context(session_key, context_seq) return session, session_key
async def _send_completion(client: QwenClient, session, prompt: str, model_id: str, thinking: bool, search: bool, chat_type: str = "t2t"): try: resp = await client.completion( chat_session_id=session.id, prompt=prompt, parent_message_id=session.last_response_id, model=model_id, thinking=thinking, search=search, chat_type=chat_type, ) except httpx.HTTPStatusError as exc: raise HTTPException(exc.response.status_code, exc.response.text[:500]) from exc except httpx.HTTPError as exc: raise HTTPException(502, f"Qwen request failed: {exc}") from exc
if resp.status_code != 200: body = await resp.aread() await resp.aclose() raise HTTPException(resp.status_code, body[:500].decode("utf-8", errors="replace"))
content_type = resp.headers.get("content-type", "") if "text/event-stream" not in content_type: body = await resp.aread() await resp.aclose() text = body[:500].decode("utf-8", errors="replace") if "text/html" in content_type or b"requestInfo" in body: raise HTTPException(502, "Qwen WAF challenge: request blocked by anti-bot, try again later") try: payload = json.loads(body) except json.JSONDecodeError: raise HTTPException(502, f"Qwen request failed: {text}") from None if isinstance(payload, dict): error = payload.get("error") if isinstance(error, dict): code = error.get("code") if _is_context_limit_code(code): raise ContextLimitError() from None raise HTTPException(_error_status(code), error.get("message") or error.get("details") or "Qwen error") data = payload.get("data") if isinstance(data, dict) and data.get("code"): if _is_context_limit_code(data["code"]): raise ContextLimitError() from None raise HTTPException(_error_status(data["code"]), data.get("details") or data.get("message") or "Qwen error") raise HTTPException(502, f"Qwen request failed: {text}") return resp
def _is_retryable_error(rec: QwenStreamReconstructor) -> bool: return bool(rec.error and error_code(rec.error) in RETRYABLE_ERROR_CODES and not rec.has_content)
def _error_body(rec: QwenStreamReconstructor) -> str: err = rec.error or {} return json.dumps( { "error": { "message": err.get("details") or err.get("message") or "Qwen server error, try again later", "code": err.get("code"), } }, ensure_ascii=False, )
def _sse(data: dict) -> str: return f"data: {json.dumps(data, ensure_ascii=False)}\n\n"
def _stream_error_lines( chunk_id: str, created: int, model: str, message: str, session_key: str | None = None, code: str | None = None, finish_reason: str = "error", ) -> Iterator[str]: error: dict = {"message": message} if code: error["code"] = code yield _sse( { "id": chunk_id, "object": "chat.completion.chunk", "created": created, "model": model, "error": error, "choices": [{"index": 0, "delta": {}, "finish_reason": finish_reason}], } ) yield _sse( { "id": chunk_id, "session_id": session_key, "object": "chat.completion.chunk", "choices": [], } ) yield "data: [DONE]\n\n"
def _stream_context_limit_lines(chunk_id: str, created: int, model: str, session_key: str | None = None) -> Iterator[str]: yield from _stream_error_lines( chunk_id, created, model, "context length exceeded: conversation too long, start a new conversation", session_key, "context_length_exceeded", "length", )
async def _try_stop_stream(client, session_id: str, message_id: str | None) -> None: if not session_id or not message_id: return try: await client.stop_stream(session_id, message_id) except Exception as exc: log.debug("stop_stream failed for %s: %s", session_id, exc)
async def _human_delay() -> None: delay = random.uniform(settings.human_delay_min, settings.human_delay_max) if delay > 0: await asyncio.sleep(delay)
def _accumulate_usage(session, rec: QwenStreamReconstructor) -> dict: current = rec.usage_tokens prompt_tokens = current["prompt_tokens"] completion_tokens = current["completion_tokens"] total_tokens = current["total_tokens"] or prompt_tokens + completion_tokens prev_input = int(getattr(session, "accumulated_input_tokens", 0) or 0) prev_output = int(getattr(session, "accumulated_output_tokens", 0) or 0) session.accumulated_input_tokens = prev_input + prompt_tokens session.accumulated_output_tokens = prev_output + completion_tokens return { "prompt_tokens": prompt_tokens, "completion_tokens": completion_tokens, "total_tokens": total_tokens, }
async def _collect_response( account: Any, pool: Any, session: Any, session_key: str | None, prompt: str, model_id: str, thinking: bool, search: bool, chat_type: str, existing_sid: str | None, context_seq: tuple[str, ...] | None, messages: list[Any] | None, tools: Any, tool_choice: Any, response_format: Any, had_cached_session: bool, tool_mode: bool, tool_schemas: Any, ) -> tuple[QwenStreamReconstructor, Any, Any, str, bool, Any]: stop_response_id: str | None = None stale_rebuilt = False attempt = 0 rec: QwenStreamReconstructor | None = None try: while True: try: resp = await _send_completion(account.client, session, prompt, model_id, thinking, search, chat_type) except ContextLimitError: _drop_session(pool, account, session_key) raise HTTPException(400, "context length exceeded: conversation too long, start a new conversation") from None except HTTPException as exc: if exc.status_code == 401: account.mark_broken() if exc.status_code in STALE_SESSION_STATUSES and had_cached_session and not stale_rebuilt and messages is not None: stale_rebuilt = True _drop_session(pool, account, session_key) try: prompt, tool_mode = toolemu.build_prompt(messages, tools, tool_choice, False, response_format) tool_schemas = toolemu.tool_schema_map(tools) except ValueError as build_exc: raise exc from build_exc log.warning("qwen chat %s is stale (%s), rebuilt full history into a fresh chat", session_key, exc.status_code) session, session_key = await _prepare_session(account, pool, existing_sid, model_id, context_seq) stop_response_id = None continue if _is_retryable_http(exc) and attempt < MAX_RETRIES: attempt += 1 delay = _retry_delay(attempt) log.warning( "qwen provider error (%s), retry %d/%d in %.1fs", exc.status_code, attempt, MAX_RETRIES, delay, ) await asyncio.sleep(delay) continue raise rec = QwenStreamReconstructor() incremental = IncrementalSSE() try: async for chunk in resp.aiter_bytes(): for event in incremental.feed(chunk): rec.handle(event) for event in incremental.finish(): rec.handle(event) except (httpx.HTTPError, RuntimeError) as exc: if rec.response_id: stop_response_id = rec.response_id await _try_stop_stream(account.client, session.id, stop_response_id) raise HTTPException(502, f"Stream processing failed: {exc}") from exc finally: if rec.response_id: stop_response_id = rec.response_id try: await resp.aclose() except Exception as exc: log.debug("response close failed: %s", exc) await _try_stop_stream(account.client, session.id, stop_response_id) if _is_retryable_error(rec) and attempt < MAX_RETRIES: attempt += 1 delay = _retry_delay(attempt) log.warning( "qwen retryable error (%s), retry %d/%d in %.1fs", error_code(rec.error), attempt, MAX_RETRIES, delay, ) await _try_stop_stream(account.client, session.id, stop_response_id) await asyncio.sleep(delay) continue return rec, session, session_key, prompt, tool_mode, tool_schemas except BaseException: if rec is not None and rec.response_id: stop_response_id = rec.response_id await _try_stop_stream(account.client, session.id, stop_response_id) raise
async def collect_non_stream( account, pool, existing_sid, lock, prompt, model, model_id, thinking, search, tool_mode=False, tool_schemas=None, context_seq: tuple[str, ...] | None = None, messages=None, tools=None, tool_choice=None, response_format=None, user=None, ): await _human_delay() async with account_lock(lock, settings.acquire_timeout): session, session_key = await _prepare_session(account, pool, existing_sid, model_id, context_seq) if session_key != existing_sid and messages is not None: try: prompt, tool_mode = toolemu.build_prompt(messages, tools, tool_choice, False, response_format) except ValueError: pass tool_schemas = toolemu.tool_schema_map(tools) had_cached_session = bool(existing_sid) and account.sessions.get(existing_sid) is not None rec, session, session_key, prompt, tool_mode, tool_schemas = await _collect_response( account, pool, session, session_key, prompt, model_id, thinking, search, "t2t", existing_sid, context_seq, messages, tools, tool_choice, response_format, had_cached_session, tool_mode, tool_schemas, )
if _is_context_limit(rec) and not rec.has_content: _drop_session(pool, account, session_key) raise HTTPException(400, "context length exceeded: conversation too long, start a new conversation") usage = _accumulate_usage(session, rec) account.sessions.touch_last_message(session_key, rec.response_id) record_usage( "qwen", model, usage["prompt_tokens"], usage["completion_tokens"], usage["total_tokens"], user=user, session_id=session_key, )
if not rec.has_content and rec.error: raise HTTPException(_error_status(error_code(rec.error)), _error_body(rec))
if tool_mode: parsed = toolemu.parse_tool_calls(rec.content, tool_schemas) if parsed is not None: tool_calls, tool_text = parsed if tool_calls: message = toolemu.format_tool_message(tool_calls, tool_text, rec.reasoning) finish = "tool_calls" else: message = {"role": "assistant", "content": rec.content} if rec.reasoning: message["reasoning_content"] = rec.reasoning finish = "stop" else: message = {"role": "assistant", "content": rec.content} if rec.reasoning: message["reasoning_content"] = rec.reasoning finish = "stop" else: message = {"role": "assistant", "content": rec.content} if rec.reasoning: message["reasoning_content"] = rec.reasoning finish = "stop" return { "id": f"chatcmpl-{uuid.uuid4().hex}", "object": "chat.completion", "created": int(time.time()), "model": model, "choices": [{"index": 0, "message": message, "finish_reason": finish}], "usage": usage, "session_id": session_key, }
async def stream_openai( account, pool, existing_sid, lock, prompt, model, model_id, thinking, search, tool_mode=False, tool_schemas=None, include_usage=False, context_seq: tuple[str, ...] | None = None, messages=None, tools=None, tool_choice=None, response_format=None, user=None, ): chunk_id = f"chatcmpl-{uuid.uuid4().hex}" created = int(time.time())
await _human_delay() async with account_lock(lock, settings.acquire_timeout): try: session, session_key = await _prepare_session(account, pool, existing_sid, model_id, context_seq) except HTTPException as exc: detail = exc.detail if isinstance(exc.detail, str) else str(exc.detail) for line in _stream_error_lines(chunk_id, created, model, detail): yield line return
if session_key != existing_sid and messages is not None: try: prompt, tool_mode = toolemu.build_prompt(messages, tools, tool_choice, False, response_format) except ValueError: pass tool_schemas = toolemu.tool_schema_map(tools)
rec: QwenStreamReconstructor | None = None content_buf = "" stop_response_id: str | None = None had_cached_session = bool(existing_sid) and account.sessions.get(existing_sid) is not None stale_rebuilt = False attempt = 0 while True: try: resp = await _send_completion(account.client, session, prompt, model_id, thinking, search) except ContextLimitError: _drop_session(pool, account, session_key) for line in _stream_context_limit_lines(chunk_id, created, model, session_key): yield line return except HTTPException as exc: if exc.status_code == 401: account.mark_broken() if exc.status_code in STALE_SESSION_STATUSES and had_cached_session and not stale_rebuilt and messages is not None: stale_rebuilt = True _drop_session(pool, account, session_key) try: prompt, tool_mode = toolemu.build_prompt(messages, tools, tool_choice, False, response_format) tool_schemas = toolemu.tool_schema_map(tools) except ValueError: detail = exc.detail if isinstance(exc.detail, str) else str(exc.detail) for line in _stream_error_lines(chunk_id, created, model, detail, session_key): yield line return log.warning("qwen chat %s is stale (%s), rebuilt full history into a fresh chat", session_key, exc.status_code) try: session, session_key = await _prepare_session(account, pool, existing_sid, model_id, context_seq) except HTTPException as prep_exc: detail = prep_exc.detail if isinstance(prep_exc.detail, str) else str(prep_exc.detail) for line in _stream_error_lines(chunk_id, created, model, detail, session_key): yield line return stop_response_id = None continue if _is_retryable_http(exc) and attempt < MAX_RETRIES: attempt += 1 delay = _retry_delay(attempt) log.warning( "qwen provider error (%s), retry %d/%d in %.1fs", exc.status_code, attempt, MAX_RETRIES, delay, ) await asyncio.sleep(delay) continue detail = exc.detail if isinstance(exc.detail, str) else str(exc.detail) for line in _stream_error_lines(chunk_id, created, model, detail, session_key): yield line return rec = QwenStreamReconstructor() incremental = IncrementalSSE() got_content = False pending: list[str] = [] role_sent = False stopped = False try: async for chunk in resp.aiter_bytes(): for event in incremental.feed(chunk): rec.handle(event) c_diff, r_diff = rec.take_diffs() if c_diff or r_diff: got_content = True if not role_sent: role_sent = True pending.append( _sse( { "id": chunk_id, "object": "chat.completion.chunk", "created": created, "model": model, "choices": [ { "index": 0, "delta": {"role": "assistant"}, "finish_reason": None, } ], } ) ) delta: dict = {} if c_diff: if tool_mode: content_buf += c_diff else: delta["content"] = c_diff if r_diff: delta["reasoning_content"] = r_diff if delta: pending.append( _sse( { "id": chunk_id, "object": "chat.completion.chunk", "created": created, "model": model, "choices": [ { "index": 0, "delta": delta, "finish_reason": None, } ], } ) ) if got_content: for line in pending: yield line pending.clear() except BaseException: stopped = True if rec.response_id: stop_response_id = rec.response_id await _try_stop_stream(account.client, session.id, stop_response_id) raise finally: if rec.response_id: stop_response_id = rec.response_id try: await resp.aclose() except Exception as exc: log.debug("response close failed: %s", exc) if not stopped: await _try_stop_stream(account.client, session.id, stop_response_id) if got_content: break if _is_retryable_error(rec) and attempt < MAX_RETRIES: attempt += 1 delay = _retry_delay(attempt) log.warning( "qwen retryable error (%s), retry %d/%d in %.1fs", error_code(rec.error), attempt, MAX_RETRIES, delay, ) await _try_stop_stream(account.client, session.id, stop_response_id) await asyncio.sleep(delay) continue break
assert rec is not None if _is_context_limit(rec) and not rec.has_content: _drop_session(pool, account, session_key) for line in _stream_context_limit_lines(chunk_id, created, model, session_key): yield line return usage = _accumulate_usage(session, rec) account.sessions.touch_last_message(session_key, rec.response_id) record_usage( "qwen", model, usage["prompt_tokens"], usage["completion_tokens"], usage["total_tokens"], user=user, session_id=session_key, )
if not rec.has_content and rec.error: err = rec.error code = error_code(rec.error) for line in _stream_error_lines( chunk_id, created, model, err.get("details") or err.get("message") or "Qwen server error, try again later", session_key, code, code or "error", ): yield line return
if tool_mode: parsed = toolemu.parse_tool_calls(content_buf, tool_schemas) if parsed is not None: tool_calls, tool_text = parsed if tool_calls: for delta in toolemu.tool_call_deltas(tool_calls, tool_text): yield _sse( { "id": chunk_id, "object": "chat.completion.chunk", "created": created, "model": model, "choices": [{"index": 0, "delta": delta, "finish_reason": None}], } ) finish = "tool_calls" else: yield _sse( { "id": chunk_id, "object": "chat.completion.chunk", "created": created, "model": model, "choices": [ { "index": 0, "delta": {"content": content_buf}, "finish_reason": None, } ], } ) finish = "stop" else: if content_buf: yield _sse( { "id": chunk_id, "object": "chat.completion.chunk", "created": created, "model": model, "choices": [ { "index": 0, "delta": {"content": content_buf}, "finish_reason": None, } ], } ) finish = "stop" else: finish = "stop"
yield _sse( { "id": chunk_id, "object": "chat.completion.chunk", "created": created, "model": model, "choices": [{"index": 0, "delta": {}, "finish_reason": finish}], } ) if include_usage: yield _sse( { "id": chunk_id, "object": "chat.completion.chunk", "created": created, "model": model, "choices": [], "usage": usage, } ) yield _sse( { "id": chunk_id, "session_id": session_key, "object": "chat.completion.chunk", "choices": [], } ) yield "data: [DONE]\n\n"
async def collect_image( account, pool, existing_sid, lock, prompt, model, model_id, context_seq: tuple[str, ...] | None = None, user=None, ): await _human_delay() async with account_lock(lock, settings.acquire_timeout): session, session_key = await _prepare_session(account, pool, existing_sid, model_id, context_seq) had_cached_session = bool(existing_sid) and account.sessions.get(existing_sid) is not None rec, session, session_key, _prompt, _tool_mode, _tool_schemas = await _collect_response( account, pool, session, session_key, prompt, model_id, False, False, "t2i", existing_sid, context_seq, None, None, None, None, had_cached_session, False, None, )
if _is_context_limit(rec) and not rec.has_content: _drop_session(pool, account, session_key) raise HTTPException(400, "context length exceeded: conversation too long, start a new conversation") usage = _accumulate_usage(session, rec) account.sessions.touch_last_message(session_key, rec.response_id) record_usage( "qwen", model, usage["prompt_tokens"], usage["completion_tokens"], usage["total_tokens"], user=user, session_id=session_key, )
if not rec.has_content and rec.error: raise HTTPException(_error_status(error_code(rec.error)), _error_body(rec))
return { "image_urls": rec.image_urls, "revised_prompt": rec.content or "", "usage": usage, "session_id": session_key, }

from __future__ import annotations

import re
from typing import Any

from ..sseutil import SSEEvent

ANSWER_PHASES = {"answer", "deep_research_answer", "ReportGeneration", "PdfMdGen"}
IMAGE_PHASES = {"image", "image_generation", "image_gen", "t2i"}
THINK_PHASES = {"think", "DeepThinking"}
SUMMARY_PHASE = "thinking_summary"

_IMAGE_URL_RE = re.compile(r"!\[[^\]]*\]\((https?://[^\s)>'\"]+)\)|(https?://cdn\.qwenlm\.ai/[^\s)>'\"]+)")
_TRAILING_PUNCT = ".,;:!?"


def _delta_text(delta: dict, key: str) -> str:
    value = delta.get(key)
    return value if isinstance(value, str) else ""


def _extract_image_urls(text: str) -> list[str]:
    urls: list[str] = []
    for match in _IMAGE_URL_RE.finditer(text):
        url = (match.group(1) or match.group(2) or "").rstrip(_TRAILING_PUNCT)
        if url:
            urls.append(url)
    return urls


def _summary_text(item: Any) -> str:
    if isinstance(item, str):
        return item
    if isinstance(item, dict):
        for key in ("text", "content", "value", "summary"):
            value = item.get(key)
            if isinstance(value, str) and value:
                return value
    return ""


class QwenStreamReconstructor:
    def __init__(self) -> None:
        self.response_id: str | None = None
        self.content: str = ""
        self.reasoning: str = ""
        self.image_urls: list[str] = []
        self.image_size: tuple[int, int] | None = None
        self.finished: bool = False
        self.error: dict | None = None
        self.usage: dict = {}
        self._prev_content: str = ""
        self._prev_reasoning: str = ""
        self._seen_image_urls: set[str] = set()

    def _collect_image_urls(self, text: str) -> None:
        for url in _extract_image_urls(text):
            if url not in self._seen_image_urls:
                self._seen_image_urls.add(url)
                self.image_urls.append(url)

    def handle(self, event: SSEEvent) -> None:
        data = event.data
        if not isinstance(data, dict):
            return
        created = data.get("response.created")
        if isinstance(created, dict) and created.get("response_id"):
            self.response_id = created["response_id"]
        if data.get("response.stopped"):
            self.finished = True
        if data.get("done"):
            self.finished = True
        if data.get("response_id"):
            self.response_id = data["response_id"]
        if isinstance(data.get("usage"), dict):
            self.usage = data["usage"]
        if data.get("error"):
            error = data["error"]
            self.error = error if isinstance(error, dict) else {"code": "Internal_Server_Error", "details": error}
            return
        choices = data.get("choices")
        if not isinstance(choices, list) or not choices:
            return
        delta = choices[0].get("delta")
        if not isinstance(delta, dict):
            return
        if delta.get("status") == "finished":
            self.finished = True
        phase = delta.get("phase") or ""
        if phase in IMAGE_PHASES:
            text = _delta_text(delta, "content")
            if text:
                self._collect_image_urls(text)
                self.content += text
            image_field = delta.get("image_url") or delta.get("image")
            if isinstance(image_field, str) and image_field.startswith("http"):
                if image_field not in self._seen_image_urls:
                    self._seen_image_urls.add(image_field)
                    self.image_urls.append(image_field)
            extra = delta.get("extra")
            if isinstance(extra, dict):
                hw = extra.get("output_image_hw")
                if isinstance(hw, list) and hw:
                    pair = hw[0]
                    if isinstance(pair, list) and len(pair) >= 2:
                        try:
                            w, h = int(pair[0]), int(pair[1])
                        except (TypeError, ValueError):
                            w = h = 0
                        if w > 0 and h > 0:
                            self.image_size = (w, h)
                for key in ("image_url", "image_urls", "images", "url"):
                    val = extra.get(key)
                    if isinstance(val, str) and val.startswith("http"):
                        if val not in self._seen_image_urls:
                            self._seen_image_urls.add(val)
                            self.image_urls.append(val)
                    elif isinstance(val, list):
                        for item in val:
                            item_url = item if isinstance(item, str) else (item.get("url") if isinstance(item, dict) else None)
                            if isinstance(item_url, str) and item_url.startswith("http"):
                                if item_url not in self._seen_image_urls:
                                    self._seen_image_urls.add(item_url)
                                    self.image_urls.append(item_url)
        elif phase in ANSWER_PHASES:
            text = _delta_text(delta, "content")
            if text:
                self.content += text
                self._collect_image_urls(text)
        elif phase in THINK_PHASES:
            text = _delta_text(delta, "content")
            if text:
                self.reasoning += text
        elif phase == SUMMARY_PHASE:
            extra = delta.get("extra")
            if isinstance(extra, dict):
                summary = extra.get("summary_thought")
                if isinstance(summary, dict):
                    items = summary.get("content")
                    if isinstance(items, list):
                        joined = "\n\n".join(text for text in (_summary_text(item) for item in items) if text)
                        if joined:
                            self.reasoning = joined

    def take_diffs(self) -> tuple[str, str]:
        content, reasoning = self.content, self.reasoning
        c_diff = content.removeprefix(self._prev_content)
        r_diff = reasoning.removeprefix(self._prev_reasoning)
        self._prev_content, self._prev_reasoning = content, reasoning
        return c_diff, r_diff

    @property
    def has_content(self) -> bool:
        return bool(self.content or self.reasoning or self.image_urls)

    @property
    def usage_tokens(self) -> dict:
        def _int(value: Any) -> int:
            return int(value) if isinstance(value, (int, float)) else 0

        return {
            "prompt_tokens": _int(self.usage.get("input_tokens")),
            "completion_tokens": _int(self.usage.get("output_tokens")),
            "total_tokens": _int(self.usage.get("total_tokens")),
        }


def error_code(error: dict | None) -> str | None:
    if not error:
        return None
    code = error.get("code")
    return code if isinstance(code, str) else None

from __future__ import annotations

import asyncio
import threading
import time
from collections import OrderedDict
from typing import Any

from .store import JsonStore


class SessionRegistry:
    def __init__(
        self,
        client: Any,
        maxsize: int = 128,
        ttl: float = 0.0,
        store: JsonStore | None = None,
        key_prefix: str = "",
    ) -> None:
        self._client = client
        self._sessions: OrderedDict[str, tuple[Any, float]] = OrderedDict()
        self._lock = threading.Lock()
        self._maxsize = max(1, maxsize)
        self._ttl = max(0.0, ttl)
        self._store = store
        self._key_prefix = key_prefix
        self._creation_lock = asyncio.Lock()
        self._restore()

    def _now(self) -> float:
        return time.monotonic()

    def _expired(self, session_id: str, now: float) -> bool:
        return self._ttl > 0 and now - self._sessions[session_id][1] > self._ttl

    def _session_key(self, session_id: str) -> str:
        return f"{self._key_prefix}{session_id}"

    def _serialize(self, session: Any) -> dict[str, Any]:
        return {
            "id": session.id,
            "title": getattr(session, "title", ""),
            "last_message_id": getattr(session, "last_message_id", None),
            "accumulated_tokens": getattr(session, "accumulated_tokens", 0),
        }

    def _deserialize(self, record: Any) -> Any:
        if not isinstance(record, dict) or not record.get("id"):
            raise ValueError("invalid session record")
        from .deepseek.client import DeepSeekSession

        accumulated = record.get("accumulated_tokens")
        accumulated_tokens = int(accumulated) if isinstance(accumulated, (int, float)) else 0
        return DeepSeekSession(
            id=record["id"],
            title=record.get("title") or "",
            last_message_id=record.get("last_message_id"),
            accumulated_tokens=accumulated_tokens,
        )

    def _restore(self) -> None:
        if self._store is None:
            return
        prefix = self._key_prefix
        by_canonical: dict[str, Any] = {}
        for key, record in self._store.items():
            if prefix:
                if not key.startswith(prefix):
                    continue
                session_id = key[len(prefix) :]
            else:
                session_id = key
            if not session_id:
                if prefix and key == prefix:
                    self._store.discard(key)
                continue
            try:
                session = self._deserialize(record)
            except Exception:
                continue
            canonical = by_canonical.get(session.id)
            if canonical is not None:
                session = canonical
            else:
                by_canonical[session.id] = session
            self._sessions[session_id] = (session, self._now())
        while len(self._sessions) > self._maxsize:
            oldest, _ = self._sessions.popitem(last=False)
            self._store.discard(self._session_key(oldest))

    async def _create(self, **kwargs: Any) -> Any:
        return await self._client.create_session(**kwargs)

    def _reuse(self, session: Any, session_id: str, **kwargs: Any) -> bool:
        return True

    def can_reuse(self, session_id: str | None, **kwargs: Any) -> bool:
        if not session_id:
            return False
        session = self.get(session_id)
        return session is not None and self._reuse(session, session_id, **kwargs)

    def _update_last(self, session: Any, message_id: str) -> None:
        session.last_message_id = message_id

    def get(self, session_id: str | None) -> Any | None:
        if not session_id:
            return None
        now = self._now()
        with self._lock:
            entry = self._sessions.get(session_id)
            if entry is None:
                return None
            if self._expired(session_id, now):
                self._sessions.pop(session_id, None)
                if self._store is not None:
                    self._store.discard(self._session_key(session_id))
                return None
            session = entry[0]
            self._sessions.move_to_end(session_id)
            self._sessions[session_id] = (session, now)
            return session

    async def obtain(self, session_id: str | None, **kwargs: Any) -> tuple[Any, str]:
        async with self._creation_lock:
            if session_id:
                existing = self.get(session_id)
                if existing is not None and self._reuse(existing, session_id, **kwargs):
                    return existing, session_id
            session = await self._create(**kwargs)
            new_id = session.id
            bind_key = session_id or new_id
            now = self._now()
            with self._lock:
                self._sessions[new_id] = (session, now)
                if bind_key != new_id:
                    self._sessions[bind_key] = (session, now)
                self._sessions.move_to_end(bind_key)
                if bind_key != new_id:
                    self._sessions.move_to_end(new_id)
                while len(self._sessions) > self._maxsize:
                    protect = {new_id, bind_key}
                    evictable = [k for k in self._sessions if k not in protect]
                    if not evictable:
                        break
                    oldest = min(evictable, key=lambda k: self._sessions[k][1])
                    self._sessions.pop(oldest, None)
                    if self._store is not None:
                        self._store.discard(self._session_key(oldest))
                if self._store is not None:
                    self._store.set(self._session_key(new_id), self._serialize(session))
                    if bind_key != new_id:
                        self._store.set(self._session_key(bind_key), self._serialize(session))
            return session, bind_key

    def touch_last_message(self, session_id: str, message_id: str | None) -> None:
        session = self.get(session_id)
        if session is not None and message_id:
            self._update_last(session, message_id)
            if self._store is not None:
                self._store.set(self._session_key(session_id), self._serialize(session))
                if session_id != session.id:
                    self._store.set(self._session_key(session.id), self._serialize(session))

    def forget(self, session_id: str) -> None:
        with self._lock:
            self._sessions.pop(session_id, None)
        if self._store is not None:
            self._store.discard(self._session_key(session_id))

    def close_all(self) -> None:
        with self._lock:
            self._sessions.clear()
        if self._store is not None:
            prefix = self._key_prefix
            for key, _ in self._store.items():
                if key.startswith(prefix):
                    self._store.discard(key)

from __future__ import annotations

import json
from collections.abc import Iterator
from typing import Any


class SSEEvent:
    __slots__ = ("data", "event")

    def __init__(self, event: str | None, data: Any) -> None:
        self.event = event
        self.data = data


def _decode(raw_data: str) -> Any:
    try:
        return json.loads(raw_data)
    except json.JSONDecodeError:
        return raw_data


def parse_sse(data: str) -> list[SSEEvent]:
    events: list[SSEEvent] = []
    event_name: str | None = None
    data_lines: list[str] = []
    for raw_line in data.split("\n"):
        line = raw_line.strip("\r")
        if line == "":
            if data_lines:
                events.append(SSEEvent(event_name, _decode("\n".join(data_lines))))
            event_name = None
            data_lines = []
            continue
        if line.startswith("event:"):
            event_name = line[len("event:") :].strip()
        elif line.startswith("data:"):
            data_lines.append(line[len("data:") :].strip())
    if data_lines:
        events.append(SSEEvent(event_name, _decode("\n".join(data_lines))))
    return events


MAIN_RESPONSE_TYPES = ("RESPONSE", "TEMPLATE_RESPONSE")
THINK_TYPES = ("THINK",)


class IncrementalSSE:
    def __init__(self) -> None:
        self._buffer = b""

    def feed(self, chunk: bytes) -> Iterator[SSEEvent]:
        self._buffer += chunk
        while True:
            idx = self._buffer.find(b"\n\n")
            if idx == -1:
                idx = self._buffer.find(b"\r\n\r\n")
                if idx == -1:
                    break
                block = self._buffer[:idx].decode("utf-8", errors="replace")
                self._buffer = self._buffer[idx + 4 :]
            else:
                block = self._buffer[:idx].decode("utf-8", errors="replace")
                self._buffer = self._buffer[idx + 2 :]
            yield from parse_sse(block)

    def finish(self) -> Iterator[SSEEvent]:
        if self._buffer.strip():
            yield from parse_sse(self._buffer.decode("utf-8", errors="replace"))
        self._buffer = b""


def _normalise_key(key: str) -> str:
    return "id" if key == "message_id" else key


def _navigate(node: Any, parts: list[str]) -> Any:
    cur: Any = node
    for raw_part in parts:
        part = _normalise_key(raw_part)
        try:
            if isinstance(cur, list):
                idx = int(part)
                if idx >= len(cur) or idx < -len(cur):
                    return None
                cur = cur[idx]
            elif isinstance(cur, dict):
                cur = cur[part]
            else:
                return None
        except (KeyError, ValueError, TypeError):
            return None
    return cur


def _set_path(target: dict, parts: list[str], value: Any) -> None:
    node: Any = target
    for i, raw_part in enumerate(parts):
        part = _normalise_key(raw_part)
        if i == len(parts) - 1:
            if isinstance(node, dict):
                node[part] = value
            elif isinstance(node, list):
                try:
                    idx = int(part)
                except ValueError:
                    return
                if -len(node) <= idx < len(node):
                    node[idx] = value
            return
        try:
            if isinstance(node, list):
                idx = int(part)
                if idx >= len(node) or idx < -len(node):
                    return
                node = node[idx]
            elif isinstance(node, dict):
                if part not in node or not isinstance(node[part], (dict, list)):
                    node[part] = {}
                node = node[part]
            else:
                return
        except (KeyError, ValueError, TypeError):
            return


def _init_message(message: dict, value: Any) -> None:
    source = value.get("response") if isinstance(value, dict) else None
    if not isinstance(source, dict):
        return
    message.clear()
    for key, val in source.items():
        message[_normalise_key(key)] = val


def _apply_delta(message: dict, op: str, path: str, value: Any) -> None:
    if op == "BATCH":
        values = value if isinstance(value, list) else []
        for sub in values:
            if not isinstance(sub, dict):
                continue
            sub_op = sub.get("o", "SET")
            sub_path = sub.get("p", "")
            if sub_path and path and not sub_path.startswith("response/"):
                sub_path = f"{path}/{sub_path}"
            _apply_delta(message, sub_op, sub_path, sub.get("v"))
        return

    parts = [p for p in (path or "").split("/") if p]
    if not parts:
        _init_message(message, value)
        return
    if parts[0] != "response":
        return
    rest = parts[1:]
    if not rest:
        if op == "SET":
            _init_message(message, value)
        return

    if op == "APPEND":
        node = _navigate(message, rest[:-1])
        key = _normalise_key(rest[-1])
        if isinstance(node, list):
            try:
                idx = int(key)
            except ValueError:
                return
            if idx >= len(node) or idx < 0:
                return
            cur = node[idx]
            if isinstance(cur, str) and isinstance(value, str):
                node[idx] = cur + value
        elif isinstance(node, dict):
            if key not in node:
                node[key] = value
            elif isinstance(node[key], str) and isinstance(value, str):
                node[key] += value
            elif isinstance(node[key], list):
                if isinstance(value, list):
                    node[key].extend(value)
                else:
                    node[key].append(value)
            else:
                node[key] = value
        return

    if op == "SET":
        _set_path(message, rest, value)


def _fragment_text(fragment: Any) -> str:
    if isinstance(fragment, str):
        return fragment
    if not isinstance(fragment, dict):
        return ""
    content = fragment.get("content")
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        out = []
        for item in content:
            if isinstance(item, str):
                out.append(item)
            elif isinstance(item, dict) and isinstance(item.get("text"), str):
                out.append(item["text"])
        return "".join(out)
    return ""


class MessageReconstructor:
    def __init__(self) -> None:
        self.message: dict = {}
        self._last_op = "SET"
        self._last_path = ""
        self._prev_content = ""
        self._prev_reasoning = ""
        self.response_message_id: str | None = None
        self.hint_error: dict | None = None

    def handle(self, event: SSEEvent) -> None:
        if event.event == "ready":
            if isinstance(event.data, dict):
                self.response_message_id = event.data.get("response_message_id")
            return
        if event.event in ("toast", "hint"):
            if isinstance(event.data, dict) and event.data.get("type") == "error":
                self.hint_error = {
                    "message": event.data.get("content") or event.data.get("message") or "",
                    "finish_reason": event.data.get("finish_reason"),
                }
            return
        if event.event not in (None, "delta"):
            return
        data = event.data
        if not isinstance(data, dict) or "v" not in data:
            return
        op = data.get("o", self._last_op)
        path = data.get("p", self._last_path)
        if op != "BATCH":
            self._last_op = op
            self._last_path = path
        _apply_delta(self.message, op, path, data["v"])

    def _aggregate(self, types: tuple[str, ...]) -> str:
        fragments = self.message.get("fragments") or []
        parts = []
        for frag in fragments:
            if isinstance(frag, dict) and frag.get("type") in types:
                parts.append(_fragment_text(frag))
        return "".join(parts)

    @property
    def content(self) -> str:
        return self._aggregate(MAIN_RESPONSE_TYPES)

    @property
    def reasoning(self) -> str:
        return self._aggregate(THINK_TYPES)

    def take_diffs(self) -> tuple[str, str]:
        content, reasoning = self.content, self.reasoning
        c_diff = content.removeprefix(self._prev_content)
        r_diff = reasoning.removeprefix(self._prev_reasoning)
        self._prev_content, self._prev_reasoning = content, reasoning
        return c_diff, r_diff

    def extend_with(self, other: MessageReconstructor) -> None:
        old_content = self.content
        old_reasoning = self.reasoning
        other_fragments = (other.message or {}).get("fragments")
        if isinstance(other_fragments, list) and other_fragments:
            fragments = self.message.get("fragments")
            if isinstance(fragments, list):
                fragments.extend(other_fragments)
            else:
                self.message["fragments"] = list(other_fragments)
        if other.id:
            self.message["id"] = other.id
        if other.status:
            self.message["status"] = other.status
        if other.accumulated_tokens:
            self.message["accumulated_token_usage"] = other.accumulated_tokens
        self.hint_error = other.hint_error
        self._prev_content = old_content
        self._prev_reasoning = old_reasoning

    @property
    def status(self) -> str | None:
        return self.message.get("status")

    @property
    def id(self) -> str | None:
        return self.message.get("id")

    @property
    def accumulated_tokens(self) -> int:
        value = self.message.get("accumulated_token_usage")
        return int(value) if isinstance(value, (int, float)) and value > 0 else 0

    @property
    def usage(self) -> dict:
        total = self.accumulated_tokens
        return {"prompt_tokens": 0, "completion_tokens": total, "total_tokens": total}

from __future__ import annotations

import json
import logging
import os
import tempfile
import threading
from pathlib import Path
from typing import Any

from .config import settings

log = logging.getLogger("danyapi.store")

DEFAULT_CACHE_SUBDIR = "danyapi"


def cache_root() -> Path:
    override = settings.cache_dir
    if override:
        root = Path(override)
    else:
        root = Path(tempfile.gettempdir()) / DEFAULT_CACHE_SUBDIR
    try:
        root.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        log.warning("cannot create cache dir %s: %s", root, exc)
    return root


class JsonStore:
    def __init__(self, name: str, scope: str | None = None) -> None:
        self._scope = scope
        self._data: dict[str, Any] = {}
        self._lock = threading.Lock()
        self._path: Path | None = None
        if scope:
            safe = "".join(ch if ch.isalnum() or ch in "-_." else "_" for ch in f"{name}-{scope}")
            self._path = cache_root() / f"{safe}.json"
            self._load()

    @property
    def enabled(self) -> bool:
        return self._path is not None

    def _load(self) -> None:
        if self._path is None:
            return
        try:
            raw = self._path.read_text(encoding="utf-8")
        except (FileNotFoundError, OSError, UnicodeError):
            return
        try:
            data = json.loads(raw)
        except ValueError:
            return
        if isinstance(data, dict):
            self._data = data

    def _write(self) -> None:
        if self._path is None:
            return
        tmp = self._path.with_name(self._path.name + ".tmp")
        try:
            tmp.write_text(json.dumps(self._data, ensure_ascii=False), encoding="utf-8")
            os.replace(tmp, self._path)
        except (OSError, TypeError, ValueError) as exc:
            log.warning("cache write failed for %s: %s", self._path, exc)
            try:
                tmp.unlink(missing_ok=True)
            except OSError:
                pass

    def get(self, key: str, default: Any = None) -> Any:
        with self._lock:
            return self._data.get(key, default)

    def set(self, key: str, value: Any) -> None:
        with self._lock:
            if key in self._data and self._data[key] == value:
                return
            self._data[key] = value
            self._write()

    def pop(self, key: str, default: Any = None) -> Any:
        with self._lock:
            if key not in self._data:
                return default
            value = self._data.pop(key)
            self._write()
            return value

    def discard(self, key: str) -> None:
        with self._lock:
            if key in self._data:
                self._data.pop(key)
                self._write()

    def clear(self) -> None:
        with self._lock:
            if not self._data:
                return
            self._data.clear()
            self._write()

    def items(self) -> list[tuple[str, Any]]:
        with self._lock:
            return list(self._data.items())

    def __len__(self) -> int:
        with self._lock:
            return len(self._data)

    def __contains__(self, key: str) -> bool:
        with self._lock:
            return key in self._data

from __future__ import annotations

import re
from typing import Any

_CJK_RE = re.compile(r"[\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff\u3040-\u30ff\uac00-\ud7af]")
_IMAGE_TOKEN_COST = 85


def _is_cjk(ch: str) -> bool:
    return _CJK_RE.match(ch) is not None


def estimate_tokens(text: str | None) -> int:
    if not text:
        return 0
    cjk = sum(1 for ch in text if _is_cjk(ch))
    other = len(text) - cjk
    if other == 0:
        return cjk
    return cjk + max(1, other // 4)


def count_message_tokens(message: Any) -> int:
    if not isinstance(message, dict):
        return 0
    tokens = 3
    content = message.get("content")
    if isinstance(content, str):
        tokens += estimate_tokens(content)
    elif isinstance(content, list):
        for item in content:
            if isinstance(item, dict):
                text = item.get("text")
                if isinstance(text, str):
                    tokens += estimate_tokens(text)
                elif item.get("type") == "image_url":
                    tokens += _IMAGE_TOKEN_COST
            elif isinstance(item, str):
                tokens += estimate_tokens(item)
    tool_calls = message.get("tool_calls")
    if isinstance(tool_calls, list):
        for call in tool_calls:
            if not isinstance(call, dict):
                continue
            function = call.get("function")
            if isinstance(function, dict):
                name = function.get("name")
                if isinstance(name, str):
                    tokens += estimate_tokens(name)
                arguments = function.get("arguments")
                if isinstance(arguments, str):
                    tokens += estimate_tokens(arguments)
    return tokens


def count_messages_tokens(messages: list[Any]) -> int:
    return sum(count_message_tokens(message) for message in messages)


def count_prompt_tokens(prompt: str | None) -> int:
    return estimate_tokens(prompt)

from __future__ import annotations

import logging
import threading
import time
from typing import Any

from .store import JsonStore

log = logging.getLogger("danyapi.usage")

_tracker: list[UsageTracker | None] = [None]
_tracker_lock = threading.Lock()


def init_tracker(store: JsonStore | None = None, max_records: int = 1000) -> UsageTracker:
    with _tracker_lock:
        tracker = UsageTracker(store=store, max_records=max_records)
        _tracker[0] = tracker
        return tracker


def get_tracker() -> UsageTracker | None:
    return _tracker[0]


def reset_tracker() -> None:
    with _tracker_lock:
        _tracker[0] = None


def record_usage(
    provider: str,
    model: str,
    prompt_tokens: int,
    completion_tokens: int,
    total_tokens: int,
    user: str | None = None,
    session_id: str | None = None,
) -> None:
    tracker = get_tracker()
    if tracker is not None:
        tracker.record(provider, model, prompt_tokens, completion_tokens, total_tokens, user=user, session_id=session_id)


class UsageTracker:
    def __init__(self, store: JsonStore | None = None, max_records: int = 1000) -> None:
        self._store = store
        self._max_records = max(1, max_records)
        self._lock = threading.Lock()
        self._totals: dict[str, int] = {"requests": 0, "prompt_tokens": 0, "completion_tokens": 0, "total_tokens": 0}
        self._by_model: dict[str, dict[str, int]] = {}
        self._by_provider: dict[str, dict[str, int]] = {}
        self._by_user: dict[str, dict[str, int]] = {}
        self._recent: list[dict[str, Any]] = []
        self._restore()

    def _restore(self) -> None:
        if self._store is None:
            return
        data = self._store.get("usage")
        if not isinstance(data, dict):
            return
        totals = data.get("totals")
        if isinstance(totals, dict):
            merged = {"requests": 0, "prompt_tokens": 0, "completion_tokens": 0, "total_tokens": 0}
            for key, value in totals.items():
                if key in merged and isinstance(value, (int, float)):
                    merged[key] = int(value)
            self._totals = merged
        for attr, key in (("_by_model", "by_model"), ("_by_provider", "by_provider"), ("_by_user", "by_user")):
            bucket = data.get(key)
            if isinstance(bucket, dict):
                restored: dict[str, dict[str, int]] = {}
                for name, entry in bucket.items():
                    if isinstance(entry, dict):
                        row = {"requests": 0, "prompt_tokens": 0, "completion_tokens": 0, "total_tokens": 0}
                        for field, value in entry.items():
                            if field in row and isinstance(value, (int, float)):
                                row[field] = int(value)
                        restored[name] = row
                setattr(self, attr, restored)

    def _serialize(self) -> dict[str, Any]:
        return {
            "totals": dict(self._totals),
            "by_model": {key: dict(value) for key, value in self._by_model.items()},
            "by_provider": {key: dict(value) for key, value in self._by_provider.items()},
            "by_user": {key: dict(value) for key, value in self._by_user.items()},
        }

    @staticmethod
    def _add(bucket: dict[str, dict[str, int]], key: str, prompt_tokens: int, completion_tokens: int, total_tokens: int) -> None:
        entry = bucket.setdefault(key, {"requests": 0, "prompt_tokens": 0, "completion_tokens": 0, "total_tokens": 0})
        entry["requests"] += 1
        entry["prompt_tokens"] += prompt_tokens
        entry["completion_tokens"] += completion_tokens
        entry["total_tokens"] += total_tokens

    def record(
        self,
        provider: str,
        model: str,
        prompt_tokens: int,
        completion_tokens: int,
        total_tokens: int,
        user: str | None = None,
        session_id: str | None = None,
    ) -> None:
        prompt_tokens = max(0, int(prompt_tokens or 0))
        completion_tokens = max(0, int(completion_tokens or 0))
        total_tokens = max(0, int(total_tokens or 0))
        if total_tokens == 0:
            total_tokens = prompt_tokens + completion_tokens
        with self._lock:
            self._totals["requests"] += 1
            self._totals["prompt_tokens"] += prompt_tokens
            self._totals["completion_tokens"] += completion_tokens
            self._totals["total_tokens"] += total_tokens
            self._add(self._by_model, model or "unknown", prompt_tokens, completion_tokens, total_tokens)
            self._add(self._by_provider, provider or "unknown", prompt_tokens, completion_tokens, total_tokens)
            if user:
                self._add(self._by_user, user, prompt_tokens, completion_tokens, total_tokens)
            self._recent.append(
                {
                    "ts": time.time(),
                    "provider": provider,
                    "model": model,
                    "prompt_tokens": prompt_tokens,
                    "completion_tokens": completion_tokens,
                    "total_tokens": total_tokens,
                    "user": user,
                    "session_id": session_id,
                }
            )
            if len(self._recent) > self._max_records:
                del self._recent[: len(self._recent) - self._max_records]
            if self._store is not None:
                try:
                    self._store.set("usage", self._serialize())
                except Exception as exc:
                    log.debug("usage store write failed: %s", exc)

    def snapshot(self) -> dict[str, Any]:
        with self._lock:
            return {
                "totals": dict(self._totals),
                "by_model": {key: dict(value) for key, value in self._by_model.items()},
                "by_provider": {key: dict(value) for key, value in self._by_provider.items()},
                "by_user": {key: dict(value) for key, value in self._by_user.items()},
                "recent": list(self._recent),
            }

    def reset(self) -> None:
        with self._lock:
            self._totals = {"requests": 0, "prompt_tokens": 0, "completion_tokens": 0, "total_tokens": 0}
            self._by_model.clear()
            self._by_provider.clear()
            self._by_user.clear()
            self._recent.clear()
            if self._store is not None:
                try:
                    self._store.discard("usage")
                except Exception as exc:
                    log.debug("usage store clear failed: %s", exc)

$ErrorActionPreference = "Stop"

$RepoUrl = "https://github.com/FANATFANATA/DanyAPI"
$Branch = "main"
$ZipUrl = "$RepoUrl/archive/refs/heads/$Branch.zip"
$Target = $env:DANYAPI_DIR
if (-not $Target) { $Target = Join-Path $HOME "DanyAPI" }

function Find-Python {
    foreach ($name in @("py", "python")) {
        $cmd = Get-Command $name -ErrorAction SilentlyContinue
        if ($cmd) { return $cmd.Source }
    }
    return $null
}

function Install-FromZip {
    param([string]$Dest)
    $zip = Join-Path $env:TEMP "danyapi.zip"
    $extract = Join-Path $env:TEMP "danyapi-extract"
    Write-Host "Downloading $ZipUrl"
    Invoke-WebRequest -Uri $ZipUrl -OutFile $zip
    if (Test-Path $extract) { Remove-Item -Recurse -Force $extract }
    Expand-Archive -Path $zip -DestinationPath $extract
    $src = Join-Path $extract "DanyAPI-$Branch"
    if (-not (Test-Path $src)) { throw "Unexpected archive layout" }
    if (Test-Path $Dest) { Remove-Item -Recurse -Force $Dest }
    Move-Item $src $Dest
    Remove-Item -Force $zip
}

$python = Find-Python
if (-not $python) {
    Write-Host ""
    Write-Host "Python was not found. Install Python 3.10+ from https://www.python.org/downloads/ and run the command again."
    exit 1
}

Write-Host "DanyAPI will be installed into: $Target"

if (Test-Path (Join-Path $Target ".git")) {
    Write-Host "Updating existing checkout..."
    Push-Location $Target
    try {
        & git pull --ff-only
        if ($LASTEXITCODE -ne 0) { throw "git pull failed" }
    }
    finally {
        Pop-Location
    }
}
elseif (Get-Command git -ErrorAction SilentlyContinue) {
    if (Test-Path $Target) { Remove-Item -Recurse -Force $Target }
    Write-Host "Cloning $RepoUrl ..."
    & git clone $RepoUrl $Target
    if ($LASTEXITCODE -ne 0) {
        Write-Host "git clone failed, trying the source archive."
        if (Test-Path $Target) { Remove-Item -Recurse -Force $Target }
        Install-FromZip -Dest $Target
    }
}
else {
    Write-Host "git not found, downloading the source archive instead."
    Install-FromZip -Dest $Target
}

$setup = Join-Path $Target "docs\setup.py"
if (-not (Test-Path $setup)) {
    Write-Host "Could not find $setup in the checkout."
    exit 1
}

& $python $setup
exit $LASTEXITCODE

