class _InputState:
    eof_seen = False


_input_state = _InputState()


def _read_input(prompt):
    try:
        return input(prompt)
    except EOFError:
        _input_state.eof_seen = True
        return None


def ask(question, default):
    suffix = " [Y/n]" if default else " [y/N]"
    while True:
        raw = _read_input(f"{question}{suffix}: ")
        if raw is None:
            return default
        raw = raw.strip().lower()
        if raw == "":
            return default
        if raw in ("y", "yes"):
            return True
        if raw in ("n", "no"):
            return False
        print("    answer y or n")


def is_termux():
    return "com.termux" in sys.prefix or Path("/data/data/com.termux").exists()


def ensure_rust_on_termux():
    if shutil.which("rustc"):
        return True
    pkg = shutil.which("pkg")
    if pkg is None:
        print("Termux detected but 'pkg' is missing; cannot install Rust automatically.")
        print("Run: pkg install -y rust binutils clang cmake")
        return False
    print("Rust not found. Installing Rust toolchain for Termux (needed to build pydantic-core)...")
    rc = subprocess.call([pkg, "install", "-y", "rust", "binutils", "clang", "cmake"])
    return rc == 0


def rustup_target_reachable():
    try:
        proc = subprocess.run(
            ["rustup", "target", "list", "--installed"],
            capture_output=True,
            text=True,
            timeout=30,
            check=False,
        )
    except (OSError, subprocess.TimeoutExpired):
        return True
    lines = {line.strip() for line in proc.stdout.splitlines() if line.strip()}
    return "aarch64-unknown-linux-android" in lines


def run_pip(req):
    cmd = [sys.executable, "-m", "pip", "install", "-r", req]
    env = os.environ.copy()
    if is_termux():
        if not ensure_rust_on_termux():
            print(f"Rust unavailable; skipping {req} install.")
            return
        env["CRATE_CC_NO_DEFAULTS"] = "1"
        env["CARGO_BUILD_TARGET"] = "aarch64-linux-android"
    elif not rustup_target_reachable():
        print("Rustup lacks the required target; relying on a system Rust toolchain.")
        print("Install it with: rustup target add aarch64-unknown-linux-android")
    print(f"Running: {' '.join(cmd)}")
    rc = subprocess.call(cmd, cwd=str(ROOT), env=env)
    if rc != 0:
        print(f"pip install failed for {req} (exit {rc})")
        sys.exit(rc)


def prompt(key, label, kind, current, default=""):
    while True:
        if current:
            raw = _read_input(f"  {key} - {label} [{current}]: ")
        else:
            raw = _read_input(f"  {key} - {label}: ")
        if raw is None:
            return current
        raw = raw.strip()
        if raw == "":
            return current
        if raw == "!clear":
            return ""
        if raw == "!reset":
            return default
        try:
            if kind == "int":
                int(raw)
            elif kind == "int_empty":
                if raw != "":
                    int(raw)
            elif kind == "float":
                float(raw)
            elif kind == "level":
                if raw not in ("DEBUG", "INFO", "WARNING", "ERROR"):
                    raise ValueError("must be DEBUG, INFO, WARNING or ERROR")
            elif kind == "flag":
                if raw not in ("0", "1"):
                    raise ValueError("must be 0 or 1")
            return raw
        except ValueError as e:
            print(f"    invalid: {e}")


def quote(value):
    if value == "":
        return ""
    if value != value.strip() or "#" in value or "\\" in value:
        if '"' in value:
            print("    warning: value contains a double quote, writing it raw")
            return value
        return f'"{value}"'
    return value


def parse_env(path):
    values = {}
    if not path.exists():
        return values
    for line in path.read_text(encoding="utf-8").splitlines():
        m = re.match(r"^\s*([A-Za-z0-9_]+)\s*=\s*(.*)$", line)
        if not m:
            continue
        key, val = m.group(1), m.group(2).strip()
        if len(val) >= 2 and val.startswith('"') and val.endswith('"'):
            val = val[1:-1]
        values[key] = val
    return values


def load_env():
    return parse_env(ENV_FILE)


def load_defaults():
    return parse_env(EXAMPLE_FILE)


def update_env(values):
    lines = ENV_FILE.read_text(encoding="utf-8").splitlines(keepends=True)
    for key, value in values.items():
        pattern = re.compile(rf"^\s*{re.escape(key)}\s*=")
        matching = [i for i, line in enumerate(lines) if pattern.match(line)]
        if matching:
            lines[matching[0]] = f"{key}={quote(value)}\n"
            for i in reversed(matching[1:]):
                del lines[i]
        else:
            lines.append(f"{key}={quote(value)}\n")
    fd, path = tempfile.mkstemp(dir=str(ROOT), suffix=".env.tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.writelines(lines)
        os.replace(path, ENV_FILE)
    except OSError:
        try:
            os.unlink(path)
        except OSError:
            pass
        raise


def _request(url, headers, payload=None, timeout=25):
    data = None
    method = "POST" if payload is not None else "GET"
    if payload is not None:
        data = json.dumps(payload).encode("utf-8")
        headers = dict(headers)
        headers["Content-Type"] = "application/json"
    req = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return resp.status, resp.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8", "replace") if exc.fp else str(exc)
        return exc.code, body
    except Exception as exc:
        return None, str(exc)


def _ds_headers(token=None):
    headers = {
        "User-Agent": DS_UA,
        "Referer": "https://chat.deepseek.com/",
        "Origin": "https://chat.deepseek.com",
        "Accept": "*/*",
    }
    headers.update(DS_HEADERS)
    if token:
        headers["Authorization"] = "Bearer " + token
    return headers


def _qwen_headers(token=None):
    now = datetime.datetime.now().astimezone()
    offset = now.strftime("%z")
    timezone = f"{now.strftime('%a %b %d %Y %H:%M:%S')} GMT{offset}"
    headers = {
        "User-Agent": QWEN_UA,
        "X-Request-Id": str(uuid.uuid4()),
        "Timezone": timezone,
    }
    headers.update(QWEN_HEADERS)
    if token:
        headers["Authorization"] = "Bearer " + token
        headers["Cookie"] = "token=" + token
    return headers


def check_deepseek_token(token):
    did = str(uuid.uuid4())
    url = f"https://chat.deepseek.com/api/v0/client/settings?did={did}&scope=main"
    status, body = _request(url, _ds_headers(token))
    if status is None:
        return False, f"network error: {body}"
    try:
        payload = json.loads(body)
        if payload.get("code") == 0:
            return True, ""
        return False, "server rejected the token"
    except ValueError:
        return False, f"unexpected response: {body[:200]}"


def check_qwen_token(token):
    status, body = _request("https://chat.qwen.ai/api/v1/auths/", _qwen_headers(token))
    if status is None:
        return False, f"network error: {body}"
    if status != 200:
        return False, f"http {status}: {body[:200]}"
    try:
        payload = json.loads(body)
    except ValueError:
        return False, f"unexpected response: {body[:200]}"
    if payload.get("success") is True or payload.get("id"):
        return True, ""
    return False, "server rejected the token"


def split_tokens(raw):
    return [t.strip() for t in re.split(r"[, ]+", raw) if t.strip()]


def read_value(message, current, default=""):
    raw = _read_input(message)
    if raw is None:
        return current
    raw = raw.strip()
    if raw == "":
        return current
    if raw == "!clear":
        return ""
    if raw == "!reset":
        return default
    return raw


def collect_provider(name, current, defaults):
    upper = name.upper()
    tokens_key = upper + "_TOKENS"
    host = "chat.deepseek.com" if name == "DeepSeek" else "chat.qwen.ai"
    storage = "userToken" if name == "DeepSeek" else "token"
    print()
    print(f"[ {name} ]")
    print(f"  Grab a token: open {host} -> DevTools -> Application -> Local Storage -> {storage}")
    tokens = read_value(
        f"  {name} tokens, comma-separated [{current.get(tokens_key, '') or '(empty)'}]: ",
        current.get(tokens_key, ""),
        defaults.get(tokens_key, ""),
    )
    return {tokens_key: tokens}


def check_provider(name, creds):
    upper = name.upper()
    tokens = split_tokens(creds.get(upper + "_TOKENS", ""))
    if not tokens:
        return True, ""
    checker = check_deepseek_token if name == "DeepSeek" else check_qwen_token
    for token in tokens:
        ok, detail = checker(token)
        if not ok:
            return False, f"token invalid: {detail}"
    return True, ""


def validate_provider(name, creds, defaults):
    while True:
        ok, detail = check_provider(name, creds)
        if ok:
            print(f"  {name} credentials OK.")
            return creds
        print(f"  {name} credentials INVALID: {detail}")
        if _input_state.eof_seen or not ask(f"  Re-enter {name} credentials?", True):
            print(f"  Keeping {name} credentials as entered; the server may fail at startup.")
            return creds
        creds = collect_provider(name, creds, defaults)


def _desktop_dir():
    if sys.platform == "darwin" or sys.platform.startswith("linux"):
        desktop = os.path.expanduser("~/Desktop")
        if not os.path.isdir(desktop):
            os.makedirs(desktop, exist_ok=True)
        return desktop
    return os.path.join(os.path.expanduser("~"), "Desktop")


def _ps_quote(value):
    return "'" + str(value).replace("'", "''") + "'"


def create_shortcut():
    py = sys.executable
    root = str(ROOT)
    launcher = str(ROOT / "docs" / "start.py")
    if sys.platform.startswith("win"):
        script = "\n".join(
            [
                "$d=[Environment]::GetFolderPath('Desktop')",
                "$ws=New-Object -ComObject WScript.Shell",
                "$sc=$ws.CreateShortcut((Join-Path $d 'DanyAPI.lnk'))",
                "$sc.TargetPath=" + _ps_quote(py),
                "$sc.Arguments=" + _ps_quote(launcher),
                "$sc.WorkingDirectory=" + _ps_quote(root),
                "$sc.IconLocation=" + _ps_quote(py + ",0"),
                "$sc.Description='Start the DanyAPI server'",
                "$sc.Save()",
            ]
        )
        subprocess.check_call(["powershell", "-NoProfile", "-NonInteractive", "-Command", script])
        return os.path.join(_desktop_dir(), "DanyAPI.lnk")
    if sys.platform.startswith("linux"):
        desktop = _desktop_dir()
        content = f"[Desktop Entry]\nType=Application\nName=DanyAPI\nComment=Start the DanyAPI server\nExec={py} {launcher}\nPath={root}\nTerminal=true\n"
        path = os.path.join(desktop, "DanyAPI.desktop")
        Path(path).write_text(content, encoding="utf-8")
        os.chmod(path, 0o755)
        return path
    desktop = _desktop_dir()
    content = f"#!/bin/zsh\ncd {shlex.quote(root)}\nexec {shlex.quote(py)} {shlex.quote(launcher)}\n"
    path = os.path.join(desktop, "DanyAPI.command")
    Path(path).write_text(content, encoding="utf-8")
    os.chmod(path, 0o755)
    return path


def build_pow_solver():
    src = ROOT / "danyapi" / "deepseek" / "pow_solver.c"
    out = ROOT / "danyapi" / "deepseek" / ("pow_solver.exe" if os.name == "nt" else "pow_solver")
    cc = shutil.which("clang") or shutil.which("gcc") or shutil.which("cc")
    if cc is None:
        print("No C compiler (clang/gcc/cc) found; skipping the native PoW solver build.")
        print("The Python and Node fallbacks will still solve challenges, just slower.")
        return
    cc_name = os.path.basename(cc)
    if sys.platform == "darwin":
        base = ["-O3", "-funroll-loops", "-flto", "-fomit-frame-pointer"]
    elif os.name == "nt":
        base = ["-O3", "-funroll-loops", "-flto", "-fomit-frame-pointer", "-march=native", "-mtune=native"]
        if "clang" in cc_name:
            base.append("-fuse-ld=lld")
    else:
        base = ["-O3", "-pthread", "-funroll-loops", "-flto", "-fomit-frame-pointer", "-march=native", "-mtune=native"]
    variants = [base]
    if cc_name in ("gcc", "cc") or "gcc" in cc_name:
        variants.insert(0, [*base, "-ffast-math"])
    for i, flags in enumerate(variants):
        cmd = [cc, *flags, "-o", str(out), str(src)]
        print(f"Building native PoW solver ({'gcc tuned' if i == 0 and len(variants) > 1 else 'base'}): {' '.join(cmd)}")
        if subprocess.call(cmd, cwd=str(ROOT)) == 0:
            print(f"Native PoW solver built: {out}")
            return
    flags = [f for f in base if f not in ("-march=native", "-mtune=native", "-flto", "-ffast-math")]
    cmd = [cc, *flags, "-o", str(out), str(src)]
    print(f"Falling back to portable build: {' '.join(cmd)}")
    if subprocess.call(cmd, cwd=str(ROOT)) == 0:
        print(f"Native PoW solver built: {out}")
    else:
        print("Native PoW solver build failed; Python/Node fallbacks still work.")


def main():
    print("DanyAPI setup")
    print("==============")
    if not ENV_FILE.exists():
        if EXAMPLE_FILE.exists():
            shutil.copyfile(EXAMPLE_FILE, ENV_FILE)
            print("Created .env from .env.example.")
        else:
            ENV_FILE.write_text("", encoding="utf-8")
            print("Created an empty .env.")
    else:
        print("Found existing .env, keeping it.")
    if ask("Install dependencies now (pip install -r requirements.txt)?", True):
        run_pip("requirements.txt")
    if ask("Install development dependencies (tests + linting)?", False):
        run_pip("requirements-dev.txt")

    build_pow_solver()

    current = load_env()
    defaults = load_defaults()
    values = dict(current)
    deepseek = validate_provider("DeepSeek", collect_provider("DeepSeek", current, defaults), defaults)
    qwen = validate_provider("Qwen", collect_provider("Qwen", current, defaults), defaults)
    values.update(deepseek)
    values.update(qwen)

    print()
    print("Now the rest of the settings. Enter to keep the current value, !clear to erase, !reset to restore the default.")
    for title, fields in GROUPS:
        print()
        print(f"[ {title} ]")
        for key, label, kind in fields:
            values[key] = prompt(key, label, kind, values.get(key, ""), defaults.get(key, ""))

    update_env(values)
    print()
    print("Configuration saved to .env")

    has_ds = any(v for v in deepseek.values() if v)
    has_qwen = any(v for v in qwen.values() if v)
    if not has_ds and not has_qwen:
        print("Warning: no provider credentials configured. The server will not start until you add DeepSeek or Qwen tokens.")

    if ask("Create a DanyAPI launcher shortcut on the desktop?", True):
        try:
            path = create_shortcut()
            print(f"Shortcut created: {path}")
        except Exception as exc:
            print(f"Shortcut creation failed: {exc}")

    print()
    print(f"DanyAPI runs from: {ROOT}")
    print("The server auto-updates to the latest GitHub release at every launch (DANYAPI_AUTO_UPDATE=0 disables).")
    print("Start it anytime with the desktop shortcut or:")
    print("  python app.py        (from the DanyAPI folder)")
    print("  python -m danyapi")
    print("  python docs/start.py (auto-updates, then runs)")


if __name__ == "__main__":
    main()

import json
import os
import shutil
import subprocess
import sys
import urllib.request
import zipfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
REPO = "FANATFANATA/DanyAPI"
API = f"https://api.github.com/repos/{REPO}/releases/latest"
TAG_FILE = ROOT / ".installed-release"
ENV_FILE = ROOT / ".env"
USER_FILES = (".env",)


def env_flag(name, default):
    value = os.environ.get(name)
    if value is None and ENV_FILE.exists():
        for line in ENV_FILE.read_text(encoding="utf-8").splitlines():
            if line.strip().startswith(name + "="):
                value = line.split("=", 1)[1].strip().strip('"').strip("'")
                break
    if value is None or value.strip() == "":
        return default
    return value.strip().lower() not in ("0", "false", "no", "off")


def api_latest_tag():
    req = urllib.request.Request(API, headers={"User-Agent": "DanyAPI", "Accept": "application/vnd.github+json"})
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            data = json.loads(resp.read().decode("utf-8"))
            return data.get("tag_name")
    except Exception:
        return None


def git_local_tag():
    try:
        out = subprocess.check_output(["git", "describe", "--tags", "--abbrev=0"], cwd=str(ROOT), stderr=subprocess.DEVNULL)
        tag = out.decode("utf-8", "replace").strip()
        return tag or None
    except Exception:
        return None


def file_local_tag():
    if TAG_FILE.exists():
        tag = TAG_FILE.read_text(encoding="utf-8").strip()
        return tag or None
    return None


def run(cmd, cwd=None):
    return subprocess.call(cmd, cwd=str(cwd or ROOT))


def git_update(tag):
    if run(["git", "fetch", "origin", "--tags", "--force"]) != 0:
        return False
    if run(["git", "checkout", "-f", tag]) != 0:
        run(["git", "fetch", "--unshallow", "origin"])
        run(["git", "fetch", "origin", "--tags", "--force"])
        if run(["git", "checkout", "-f", tag]) != 0:
            return False
    if run(["git", "reset", "--hard", tag]) != 0:
        return False
    return True


def zip_update(tag):
    parent = ROOT.parent
    tmp_zip = parent / "danyapi-update.zip"
    old_dir = parent / ".DanyAPI.old"
    url = f"https://github.com/{REPO}/archive/refs/tags/{tag}.zip"
    print(f"DanyAPI: downloading {url}")
    try:
        urllib.request.urlretrieve(url, str(tmp_zip))
        with zipfile.ZipFile(tmp_zip) as zf:
            names = [n for n in zf.namelist() if n]
            roots = {Path(n).parts[0] for n in names}
            if len(roots) != 1:
                print("DanyAPI: update archive layout unexpected, aborting")
                tmp_zip.unlink(missing_ok=True)
                return False
            tmp_dir = parent / next(iter(roots))
            if tmp_dir.exists():
                shutil.rmtree(str(tmp_dir), ignore_errors=True)
            zf.extractall(str(parent))
    except Exception as exc:
        print(f"DanyAPI: update download failed: {exc}")
        tmp_zip.unlink(missing_ok=True)
        return False
    if not tmp_dir.exists():
        print("DanyAPI: update archive layout unexpected, aborting")
        tmp_zip.unlink(missing_ok=True)
        return False
    if old_dir.exists():
        shutil.rmtree(str(old_dir), ignore_errors=True)
    try:
        os.chdir(str(parent))
    except OSError:
        pass
    tmp_dir_str = str(tmp_dir)
    root_str = str(ROOT)
    old_dir_str = str(old_dir)
    try:
        shutil.move(root_str, old_dir_str)
    except Exception as exc:
        print(f"DanyAPI: could not replace installation: {exc}")
        return False
    try:
        shutil.move(tmp_dir_str, root_str)
    except Exception as exc:
        shutil.move(old_dir_str, root_str)
        shutil.rmtree(tmp_dir_str, ignore_errors=True)
        print(f"DanyAPI: could not replace installation: {exc}")
        return False
    for name in USER_FILES:
        if (old_dir / name).exists():
            try:
                shutil.copy2(str(old_dir / name), str(ROOT / name))
            except Exception as exc:
                print(f"DanyAPI: warning, could not restore {name}: {exc}")
    tmp_zip.unlink(missing_ok=True)
    shutil.rmtree(str(old_dir), ignore_errors=True)
    return True


def update_to(tag):
    print(f"DanyAPI: updating to {tag} ...")
    if (ROOT / ".git").exists():
        if not git_update(tag):
            print("DanyAPI: git update failed, aborting update.")
            return
    else:
        if not zip_update(tag):
            return
    if run([sys.executable, "-m", "pip", "install", "-r", "requirements.txt"]) != 0:
        print("DanyAPI: pip install failed, aborting update.")
        return
    TAG_FILE.write_text(tag, encoding="utf-8")
    print(f"DanyAPI: updated to {tag}")


def main():
    if not env_flag("DANYAPI_AUTO_UPDATE", True):
        return run([sys.executable, "-m", "danyapi"])
    latest = api_latest_tag()
    if not latest:
        print("DanyAPI: could not check for updates, starting anyway.")
        return run([sys.executable, "-m", "danyapi"])
    local = git_local_tag() or file_local_tag()
    if local != latest:
        try:
            update_to(latest)
        except Exception as exc:
            print(f"DanyAPI: update failed: {exc}")
    else:
        print(f"DanyAPI: already at {latest}")
    return run([sys.executable, "-m", "danyapi"])


if __name__ == "__main__":
    sys.exit(main())

