from __future__ import annotations

import json
import re

from hypothesis import given, settings
from hypothesis import strategies as st

from danyapi import tools as toolemu

_tool_call_json = st.one_of(
    st.fixed_dictionaries(
        {
            "tool_calls": st.lists(
                st.fixed_dictionaries(
                    {
                        "name": st.text(min_size=1, max_size=30),
                        "arguments": st.dictionaries(st.text(), st.none()),
                    }
                ),
                min_size=1,
                max_size=5,
            ),
        }
    ).map(json.dumps),
    st.fixed_dictionaries(
        {
            "function_call": st.fixed_dictionaries(
                {
                    "name": st.text(min_size=1, max_size=30),
                    "arguments": st.text(max_size=200),
                }
            ),
        }
    ).map(json.dumps),
    st.lists(
        st.fixed_dictionaries(
            {
                "name": st.text(min_size=1, max_size=30),
                "arguments": st.dictionaries(st.text(), st.none()),
            }
        ),
        min_size=1,
        max_size=5,
    ).map(json.dumps),
    st.fixed_dictionaries(
        {
            "name": st.text(min_size=1, max_size=30),
            "arguments": st.dictionaries(st.text(), st.none()),
        }
    ).map(json.dumps),
)


def _prefix_join(prefix: str) -> st.SearchStrategy[str]:
    return _tool_call_json.map(lambda j: f"{prefix}\n\n{j}")


def _halved(j: str) -> st.SearchStrategy[str]:
    if len(j) > 4:
        return st.just(j[: len(j) // 2 + 1])
    return st.just(j)


_malformed_json = st.one_of(
    st.text(max_size=100).flatmap(_prefix_join),
    _tool_call_json.flatmap(_halved),
    _tool_call_json.map(lambda s: re.sub(r"\}(?=\])", "", s, count=1)),
    st.text(min_size=1, max_size=20).map(lambda name: f'<invoke name="{name}"><parameter name="city">Moscow</parameter></invoke>'),
)

_raw_text = st.one_of(
    _malformed_json,
    _tool_call_json.map(lambda j: f"```json\n{j}\n```"),
    _tool_call_json.map(lambda j: f"||DSML||\n{j}"),
    st.text(max_size=250),
)


@settings(max_examples=60, deadline=None)
@given(text=_raw_text)
def test_parse_tool_calls_no_crash(text: str) -> None:
    result = toolemu.parse_tool_calls(text)
    assert result is None or (isinstance(result, tuple) and len(result) == 2)


@settings(max_examples=60, deadline=None)
@given(text=_raw_text)
def test_parse_tool_calls_result_structure(text: str) -> None:
    result = toolemu.parse_tool_calls(text)
    if result is None:
        return
    calls, _wrapper = result
    assert isinstance(calls, list)
    for call in calls:
        assert hasattr(call, "name")
        assert isinstance(call.name, str) and len(call.name) > 0


@settings(max_examples=60, deadline=None)
@given(text=_tool_call_json)
def test_parse_valid_tool_calls_succeeds(text: str) -> None:
    result = toolemu.parse_tool_calls(text)
    assert result is not None, f"Failed to parse valid tool call JSON: {text[:100]}"
    calls, _ = result
    assert len(calls) >= 1


@settings(max_examples=60, deadline=None)
@given(raw=st.text(max_size=250))
def test_fix_unbalanced_json_no_crash(raw: str) -> None:
    result = toolemu._fix_unbalanced_json(raw)
    assert result is None or isinstance(result, str)


def _balanced_brackets(text: str) -> bool:
    stack: list[str] = []
    in_string = False
    escaped = False
    for ch in text:
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
            continue
        if ch == '"':
            in_string = True
        elif ch in "[{":
            stack.append(ch)
        elif ch in "]}":
            if not stack or (ch == "]" and stack[-1] != "[") or (ch == "}" and stack[-1] != "{"):
                return False
            stack.pop()
    return not stack and not in_string


@settings(max_examples=60, deadline=None)
@given(raw=st.text(max_size=250))
def test_fix_unbalanced_json_produces_balanced_output(raw: str) -> None:
    result = toolemu._fix_unbalanced_json(raw)
    if result is None:
        return
    assert _balanced_brackets(result), f"Unbalanced brackets in: {result[:100]}"


@settings(max_examples=60, deadline=None)
@given(raw=st.text(max_size=200))
def test_loads_lenient_no_crash(raw: str) -> None:
    try:
        result = toolemu._loads_lenient(raw)
        assert isinstance(result, (dict, list, str, int, float, type(None)))
    except (ValueError, json.JSONDecodeError):
        pass


@settings(max_examples=60, deadline=None)
@given(raw=st.text(max_size=200))
def test_loads_lenient_idempotent(raw: str) -> None:
    try:
        r1 = toolemu._loads_lenient(raw)
        r2 = toolemu._loads_lenient(raw)
        assert json.dumps(r1, default=str, ensure_ascii=False) == json.dumps(r2, default=str, ensure_ascii=False)
    except (ValueError, json.JSONDecodeError):
        pass


def test_dsml_marker_no_catastrophic_backtracking() -> None:
    import time

    text = "\u00a6" * 40
    started = time.monotonic()
    toolemu._strip_dsml(text)
    assert time.monotonic() - started < 2.0


def test_iter_json_objects_bounded() -> None:
    import time

    text = "{" * 4000 + "}" * 4000
    started = time.monotonic()
    toolemu.parse_tool_calls(text)
    assert time.monotonic() - started < 2.0


def test_strip_trailing_commas_keeps_comma_in_single_quoted_string() -> None:
    assert toolemu._strip_trailing_commas("{'t': 'hi,}'}") == "{'t': 'hi,}'}"


def test_double_quoted_comma_in_string_preserved() -> None:
    result = toolemu.parse_tool_calls('{"name": "f", "arguments": {"text": "hi,}"}}')
    assert result is not None
    calls, _ = result
    assert json.loads(calls[0].arguments)["text"] == "hi,}"


if __name__ == "__main__":
    import pytest

    pytest.main([__file__, "-v", "--tb=short"])

from danyapi.deepseek.sse import SSEEvent
from danyapi.deepseek.stream import IncrementalSSE
from danyapi.qwen.stream import QwenStreamReconstructor, error_code


def test_incremental_parse_real_stream():
    raw = (
        'data: {"response.created":{"chat_id":"c1","parent_id":"p0","response_id":"r1","response_index":"0"}} \n'
        "\n"
        'data: {"choices": [{"delta": {"role": "assistant", "content": "", "phase": "answer", "status": "typing"}}], "response_id": "r1"}\n'
        "\n"
        'data: {"choices": [{"delta": {"role": "assistant", "content": "Hello", "phase": "answer", "status": "typing"}}], "response_id": "r1"}\n'
        "\n"
        'data: {"choices": [{"delta": {"content": "", "role": "assistant", "status": "finished", "phase": "answer"}}], "response_id": "r1"}\n'
        "\n"
    )
    rec = QwenStreamReconstructor()
    inc = IncrementalSSE()
    mid = len(raw) // 2
    for chunk in (raw[:mid].encode(), raw[mid:].encode()):
        for event in inc.feed(chunk):
            rec.handle(event)
    for event in inc.finish():
        rec.handle(event)
    assert rec.response_id == "r1"
    assert rec.content == "Hello"
    assert rec.finished


def test_thinking_summary():
    events = [
        {
            "choices": [
                {
                    "delta": {
                        "role": "assistant",
                        "content": "",
                        "phase": "thinking_summary",
                        "extra": {
                            "summary_title": {"content": ["Title A"]},
                            "summary_thought": {"content": ["First thought"]},
                        },
                        "status": "typing",
                    }
                }
            ],
            "response_id": "r1",
        },
        {
            "choices": [
                {
                    "delta": {
                        "role": "assistant",
                        "content": "",
                        "phase": "thinking_summary",
                        "extra": {
                            "summary_title": {"content": ["Title A", "Title B"]},
                            "summary_thought": {"content": ["First thought", "Second thought"]},
                        },
                        "status": "typing",
                    }
                }
            ],
            "response_id": "r1",
        },
        {
            "choices": [{"delta": {"role": "assistant", "content": "Answer", "phase": "answer", "status": "typing"}}],
            "response_id": "r1",
        },
        {
            "choices": [{"delta": {"role": "assistant", "content": " is here", "phase": "answer", "status": "typing"}}],
            "response_id": "r1",
        },
    ]
    rec = QwenStreamReconstructor()
    for data in events:
        rec.handle(SSEEvent(None, data))
    assert rec.reasoning == "First thought\n\nSecond thought"
    assert rec.content == "Answer is here"


def test_think_incremental():
    rec = QwenStreamReconstructor()
    for text in ("Let me think", " step by step"):
        rec.handle(SSEEvent(None, {"choices": [{"delta": {"role": "assistant", "content": text, "phase": "think"}}]}))
    c_diff, r_diff = rec.take_diffs()
    assert c_diff == ""
    assert r_diff == "Let me think step by step"
    assert rec.reasoning == "Let me think step by step"


def test_diffs():
    rec = QwenStreamReconstructor()
    rec.handle(SSEEvent(None, {"choices": [{"delta": {"content": "Hel", "phase": "answer"}}]}))
    c, _ = rec.take_diffs()
    assert c == "Hel"
    rec.handle(SSEEvent(None, {"choices": [{"delta": {"content": "lo", "phase": "answer"}}]}))
    c, _ = rec.take_diffs()
    assert c == "lo"
    assert rec.content == "Hello"


def test_error_capture():
    rec = QwenStreamReconstructor()
    rec.handle(SSEEvent(None, {"error": {"code": "Too_Many_Requests", "details": "slow down"}}))
    assert rec.error is not None
    assert rec.error["code"] == "Too_Many_Requests"
    assert rec.error["details"]


def test_done_and_stopped():
    rec = QwenStreamReconstructor()
    rec.handle(SSEEvent(None, {"done": True}))
    assert rec.finished
    rec2 = QwenStreamReconstructor()
