import json from pathlib import Path from unittest.mock import MagicMock
import pytest
from danyapi import store as store_mod from danyapi.store import JsonStore
@pytest.fixture def cache_dir(tmp_path, monkeypatch): monkeypatch.setattr(store_mod.settings, "cache_dir", str(tmp_path)) return tmp_path
def test_cache_root_uses_override(cache_dir): assert store_mod.cache_root() == cache_dir
def test_cache_root_falls_back_to_temp(monkeypatch): monkeypatch.setattr(store_mod.settings, "cache_dir", "") root = store_mod.cache_root() assert isinstance(root, Path) assert root.is_absolute()
def test_disabled_without_scope(cache_dir): store = JsonStore("n", None) assert not store.enabled store.set("k", "v") assert store.get("k2") is None assert "k" in store
def test_enabled_with_scope(cache_dir): assert JsonStore("sessions", "default").enabled
def test_set_get_roundtrip(cache_dir): store = JsonStore("a", "default") store.set("k", {"nested": [1, 2, 3]}) assert store.get("k") == {"nested": [1, 2, 3]}
def test_get_default(cache_dir): store = JsonStore("b", "default") assert store.get("missing") is None assert store.get("missing", 42) == 42
def test_pop_existing_and_missing(cache_dir): store = JsonStore("c", "default") store.set("k", "v") assert store.pop("k") == "v" assert "k" not in store assert store.pop("k", "dflt") == "dflt"
def test_discard(cache_dir): store = JsonStore("d", "default") store.set("k", "v") store.discard("k") assert "k" not in store store.discard("absent")
def test_clear(cache_dir): store = JsonStore("e", "default") store.set("a", 1) store.set("b", 2) store.clear() assert len(store) == 0
def test_items_len_contains(cache_dir): store = JsonStore("f", "default") store.set("a", 1) store.set("b", 2) assert sorted(store.items()) == [("a", 1), ("b", 2)] assert len(store) == 2 assert "a" in store assert "z" not in store
def test_flush_writes_file(cache_dir): store = JsonStore("persist", "default") store.set("key", "value") assert store._path is not None raw = json.loads(store._path.read_text(encoding="utf-8")) assert raw == {"key": "value"}
def test_reload_from_disk(cache_dir): JsonStore("reload", "default").set("key", "value") store2 = JsonStore("reload", "default") assert store2.get("key") == "value"
def test_corrupted_json_ignored(cache_dir): path = store_mod.cache_root() / "corrupt-scope.json" path.write_text("not json", encoding="utf-8") store = JsonStore("corrupt", "scope") assert len(store) == 0
def test_non_dict_json_ignored(cache_dir): path = store_mod.cache_root() / "list-scope.json" path.write_text("[1, 2, 3]", encoding="utf-8") store = JsonStore("list", "scope") assert len(store) == 0
def test_scope_sanitization(cache_dir): store = JsonStore("weird", "a b/c\\d") assert store._path is not None assert store._path.name.endswith(".json")
def test_cache_root_mkdir_error(tmp_path, monkeypatch): blocker = tmp_path / "blocker" blocker.write_text("file", encoding="utf-8") monkeypatch.setattr(store_mod.settings, "cache_dir", str(blocker)) assert store_mod.cache_root() == blocker
def test_load_skips_disabled(): store = JsonStore("n", None) store._load() assert store._data == {}
def test_write_error_logged(cache_dir, monkeypatch): import os
store = JsonStore("w", "default") monkeypatch.setattr(os, "replace", lambda *a, **k: (_ for _ in ()).throw(OSError("denied"))) store.set("k", "v") assert store.get("k") == "v"
def test_set_unchanged_skips_write(cache_dir): store = JsonStore("g", "default") store.set("k", "v") store._write = MagicMock() store.set("k", "v") store._write.assert_not_called() assert store.get("k") == "v"
def test_clear_empty_returns_early(cache_dir): store = JsonStore("h", "default") store.clear() assert len(store) == 0
def test_non_serializable_value_cleans_tmp(cache_dir): store = JsonStore("ns", "default") store.set("bad", object()) assert "bad" in store assert store._path is not None assert not (store._path.with_name(store._path.name + ".tmp")).exists()

from danyapi.deepseek.sse import SSEEvent, parse_sse
from danyapi.deepseek.stream import IncrementalSSE, MessageReconstructor, _init_message, _navigate, _set_path


def first_set_delta():
    return SSEEvent(
        None,
        {
            "o": "SET",
            "p": "response",
            "v": {
                "response": {
                    "message_id": "asst_1",
                    "parent_id": "user_1",
                    "role": "assistant",
                    "thinking_enabled": True,
                    "inserted_at": 1786469543117,
                    "accumulated_token_usage": 0,
                    "search_enabled": False,
                    "search_triggered": None,
                    "status": "WIP",
                    "ban_regenerate": False,
                    "feedback": None,
                    "fragments": [
                        {"type": "THINK", "content": ""},
                        {"type": "RESPONSE", "content": ""},
                    ],
                    "has_pending_fragment": False,
                    "conversation_mode": "DEFAULT",
                }
            },
        },
    )


def test_parse_sse():
    raw = (
        "event: ready\n"
        'data: {"response_message_id":"a","request_message_id":"b","model_type":"default"}\n'
        "\n"
        'data: {"o":"BATCH","v":[{"o":"SET","p":"response/fragments/0/content","v":"hi"}]}\n'
        "\n"
        "event: finish\n"
        "data: {}\n"
        "\n"
    )
    events = parse_sse(raw)
    assert len(events) == 3
    assert events[0].event == "ready"
    assert events[0].data["response_message_id"] == "a"
    assert events[1].event is None
    assert events[1].data["o"] == "BATCH"
    assert events[2].event == "finish"


def test_parse_sse_non_json_data():
    events = parse_sse("event: ping\ndata: hello world\n\n")
    assert len(events) == 1
    assert events[0].event == "ping"
    assert events[0].data == "hello world"


def test_parse_sse_multiple_data_lines():
    events = parse_sse('data: {"a":1}\ndata: {"b":2}\n\n')
    assert events[0].data == '{"a":1}\n{"b":2}'


def test_incremental_split():
    raw = 'event: ready\ndata: {"a":1}\n\ndata: {"o":"SET","p":"response/x","v":1}\n\n'
    inc = IncrementalSSE()
    collected = []
    mid = len(raw) // 2
    collected.extend(inc.feed(raw[:mid].encode()))
    collected.extend(inc.feed(raw[mid:].encode()))
    collected.extend(inc.finish())
    assert len(collected) == 2
    assert collected[0].event == "ready"


def test_crlf_separators():
    raw = 'event: ready\r\ndata: {"a":1}\r\n\r\ndata: {"o":"SET","p":"response/x","v":1}\r\n\r\n'
    inc = IncrementalSSE()
    collected = list(inc.feed(raw.encode())) + list(inc.finish())
    assert len(collected) == 2
    assert collected[0].event == "ready"
    assert collected[1].data["v"] == 1


def test_finish_with_leftover():
    inc = IncrementalSSE()
    inc._buffer = b'data: {"x": 1}\n\n'
    events = list(inc.finish())
    assert len(events) == 1
    assert events[0].data == {"x": 1}


def test_real_stream_pattern():
    rec = MessageReconstructor()
    rec.handle(
        SSEEvent(
            "ready",
            {
                "request_message_id": 1,
                "response_message_id": 2,
                "model_type": "default",
            },
        )
    )
    assert rec.response_message_id == 2
    rec.handle(
        SSEEvent(
            None,
            {
                "v": {
                    "response": {
                        "message_id": 2,
                        "parent_id": 1,
                        "role": "ASSISTANT",
                        "status": "WIP",
                        "fragments": [{"id": 2, "type": "RESPONSE", "content": "Г"}],
                    }
                }
            },
        )
    )
    assert rec.message["id"] == 2
    rec.handle(SSEEvent(None, {"p": "response/fragments/-1/content", "o": "APPEND", "v": "рави"}))
    for token in ("тация", " -", " это"):
        rec.handle(SSEEvent(None, {"v": token}))
    assert rec.content == "Гравитация - это"
    rec.handle(
        SSEEvent(
            None,
            {
                "p": "response",
                "o": "BATCH",
                "v": [
                    {"p": "accumulated_token_usage", "v": 103},
                    {"p": "quasi_status", "v": "FINISHED"},
                ],
            },
        )
    )
    rec.handle(SSEEvent(None, {"p": "response/status", "o": "SET", "v": "FINISHED"}))
    assert rec.status == "FINISHED"
    assert rec.message.get("accumulated_token_usage") == 103


def test_thinking_then_response_fragment():
    rec = MessageReconstructor()
    rec.handle(
        SSEEvent(
            None,
            {
                "v": {
                    "response": {
                        "message_id": 2,
                        "parent_id": 1,
                        "status": "WIP",
                        "fragments": [{"id": 2, "type": "THINK", "content": "Мы"}],
                    }
                }
            },
        )
    )
    rec.handle(SSEEvent(None, {"p": "response/fragments/-1/elapsed_secs", "o": "SET", "v": 3.5}))
    rec.handle(SSEEvent(None, {"p": "response/fragments", "o": "APPEND", "v": [{"id": 3, "type": "RESPONSE", "content": "Если"}]}))
    rec.handle(SSEEvent(None, {"p": "response/fragments/-1/content", "v": " вз"}))
    for token in ("ять", " четыре"):
        rec.handle(SSEEvent(None, {"v": token}))
    assert rec.reasoning == "Мы"
    assert rec.content == "Если взять четыре"


def test_hint_error_capture():
    rec = MessageReconstructor()
    rec.handle(
        SSEEvent(
            "ready",
            {
                "request_message_id": 1,
                "response_message_id": 2,
                "model_type": "expert",
            },
        )
    )
    rec.handle(
        SSEEvent(
            "hint",
            {
                "type": "error",
                "content": "Server is busy. Try again later, or use Instant Mode.",
                "clear_response": True,
                "finish_reason": "expert_busy_use_default",
            },
        )
    )
    assert rec.hint_error is not None
    assert rec.hint_error["finish_reason"] == "expert_busy_use_default"
    assert "busy" in rec.hint_error["message"].lower()
    rec2 = MessageReconstructor()
    rec2.handle(SSEEvent("hint", {"type": "info", "content": "ok", "finish_reason": None}))
    assert rec2.hint_error is None


def test_apply_deltas():
    rec = MessageReconstructor()
    rec.handle(first_set_delta())
    assert rec.message["id"] == "asst_1"
    rec.handle(
        SSEEvent(
            None,
            {
                "o": "BATCH",
                "v": [
                    {"o": "SET", "p": "response/fragments/0/content", "v": "Let me think step by step"},
                    {"o": "SET", "p": "response/fragments/1/content", "v": "Hello"},
                ],
            },
        )
    )
    assert rec.reasoning == "Let me think step by step"
    assert rec.content == "Hello"
    c_diff, r_diff = rec.take_diffs()
    assert c_diff == "Hello"
    assert r_diff == "Let me think step by step"
    rec.handle(
        SSEEvent(
            None,
            {
                "o": "BATCH",
                "v": [
                    {"o": "SET", "p": "response/fragments/1/content", "v": "Hello world"},
                    {"o": "SET", "p": "response/status", "v": "FINISHED"},
                ],
            },
        )
    )
    c_diff, r_diff = rec.take_diffs()
    assert c_diff == " world"
    assert rec.content == "Hello world"
    assert rec.status == "FINISHED"


