    assert events[0].data == "x"


def test_extend_with_updates_diffs_tracking():
    rec = MessageReconstructor()
    rec.message = {"fragments": [{"type": "RESPONSE", "content": "a"}]}
    rec.take_diffs()
    other = MessageReconstructor()
    other.message = {"fragments": [{"type": "RESPONSE", "content": "b"}]}
    rec.extend_with(other)
    c_diff, _ = rec.take_diffs()
    assert c_diff == "b"
    assert rec.content == "ab"

from danyapi.tokens import count_message_tokens, count_messages_tokens, count_prompt_tokens, estimate_tokens


def test_estimate_tokens_empty():
    assert estimate_tokens("") == 0
    assert estimate_tokens(None) == 0


def test_estimate_tokens_latin():
    assert estimate_tokens("Hello world") == 2
    assert estimate_tokens("a") == 1
    assert estimate_tokens("abcd") == 1
    assert estimate_tokens("Hello world, how are you?") == 6


def test_estimate_tokens_cjk():
    assert estimate_tokens("你好世界") == 4
    assert estimate_tokens("こんにちは") == 5
    assert estimate_tokens("안녕하세요") == 5


def test_estimate_tokens_mixed():
    assert estimate_tokens("Hello 你好") == 3


def test_count_message_tokens_plain():
    msg = {"role": "user", "content": "Hello world"}
    assert count_message_tokens(msg) == 5


def test_count_message_tokens_content_list():
    msg = {"role": "user", "content": [{"type": "text", "text": "Hello"}, {"type": "image_url", "image_url": {"url": "data:image/png;base64,xxx"}}]}
    assert count_message_tokens(msg) == 3 + 1 + 85


def test_count_message_tokens_tool_calls():
    msg = {"role": "assistant", "content": "", "tool_calls": [{"function": {"name": "get_weather", "arguments": '{"city":"Moscow"}'}}]}
    assert count_message_tokens(msg) > 3


def test_count_message_tokens_invalid():
    assert count_message_tokens(None) == 0
    assert count_message_tokens("not a dict") == 0
    assert count_message_tokens({}) == 3


def test_count_messages_tokens():
    messages = [{"role": "user", "content": "Hello"}, {"role": "assistant", "content": "Hi"}]
    assert count_messages_tokens(messages) == count_message_tokens(messages[0]) + count_message_tokens(messages[1])


def test_count_prompt_tokens():
    assert count_prompt_tokens("Hello world") == estimate_tokens("Hello world")
    assert count_prompt_tokens("") == 0

import json from typing import Any
import pytest
from danyapi.tools import ( ToolCall, _coerce_scalar, _content_text, _extract_calls, _extract_one_call, _fix_unbalanced_json, _has_history, _is_jsonish_arguments, _loads_lenient, _normalize_single_quotes, _parse_bare_array_calls, _parse_xml_tool_calls, _render_tool_call_mention, _strip_dsml, _tail_after_last_user, _tool_function, build_prompt, extract_last_user, extract_system, format_tool_message, is_tool_round, parse_tool_calls, parse_tool_calls_debug, render_json_mode, render_message, render_tool_schema, tool_call_deltas, tool_schema_map, )
WEATHER_TOOL = { "type": "function", "function": { "name": "get_weather", "description": "Get the weather in a city", "parameters": { "type": "object", "properties": {"city": {"type": "string"}}, "required": ["city"], }, }, }
class Message: def __init__(self, role="user", content: Any = "", tool_calls=None, tool_call_id=None, name=None): self.role = role self.content = content self.tool_calls = tool_calls self.tool_call_id = tool_call_id self.name = name
def test_render_tool_schema_basic(): schema = render_tool_schema([WEATHER_TOOL]) assert schema is not None assert schema is not None assert "get_weather" in schema assert '"city"' in schema assert "<tool_calls>" in schema assert "<invoke" in schema assert "<parameter" in schema
