def test_render_tool_schema_tool_choice_none(): assert render_tool_schema([WEATHER_TOOL], "none") is None
def test_render_tool_schema_tool_choice_required(): schema = render_tool_schema([WEATHER_TOOL], "required") assert schema is not None assert schema is not None assert "MUST call" in schema
def test_render_tool_schema_tool_choice_function_dict(): schema = render_tool_schema([WEATHER_TOOL], {"type": "function", "function": {"name": "get_weather"}}) assert schema is not None assert schema is not None assert "get_weather" in schema
def test_render_tool_schema_strict_flag_skipped(): tool = { "type": "function", "function": {"name": "calc", "strict": True, "parameters": {"type": "object", "properties": {"x": {"type": "number"}}}}, } schema = render_tool_schema([tool]) assert schema is not None assert schema is not None assert "strict" not in schema
