def test_is_tool_round_function_role(): assert is_tool_round([Message(role="function", content="42", name="calc")])
def test_is_tool_round_assistant_tool_calls(): msg = Message( role="assistant", tool_calls=[{"id": "call_1", "type": "function", "function": {"name": "get_weather", "arguments": "{}"}}], ) assert is_tool_round([msg])
