def test_build_prompt_system_and_tools_and_json(): messages = [Message(role="system", content="sys"), Message(role="user", content="q")] prompt, tool_mode = build_prompt(messages, [WEATHER_TOOL], None, False, {"type": "json_schema", "json_schema": {"schema": {"type": "object"}}}) assert tool_mode assert prompt.startswith("sys") assert "get_weather" in prompt assert "JSON Schema" in prompt assert "q" in prompt
def test_build_prompt_first_tool_round(): messages = [Message(role="user", content="What is the weather?")] prompt, tool_mode = build_prompt(messages, [WEATHER_TOOL], None, has_session=False) assert tool_mode assert "get_weather" in prompt assert "What is the weather?" in prompt
def test_build_prompt_continuation_with_session(): messages = [ Message(role="user", content="What is the weather?"), Message(role="assistant", tool_calls=[{"id": "call_1", "type": "function", "function": {"name": "get_weather", "arguments": '{"city": "Moscow"}'}}]), Message(role="tool", content="22C, sunny", tool_call_id="call_1"), ] prompt, tool_mode = build_prompt(messages, None, None, has_session=True) assert tool_mode assert "22C, sunny" in prompt assert "Continue the conversation" in prompt assert "What is the weather?" not in prompt
def test_build_prompt_continuation_no_session(): messages = [ Message(role="user", content="What is the weather?"), Message(role="assistant", tool_calls=[{"id": "call_1", "type": "function", "function": {"name": "get_weather", "arguments": '{"city": "Moscow"}'}}]), Message(role="tool", content="22C, sunny", tool_call_id="call_1"), ] prompt, tool_mode = build_prompt(messages, None, None, has_session=False) assert tool_mode assert "What is the weather?" in prompt assert "22C, sunny" in prompt assert "get_weather" in prompt
def test_build_prompt_continuation_with_session_skips_schema(): messages = [ Message(role="user", content="What is the weather?"), Message(role="assistant", content="It is 22C."), Message(role="user", content="And in Rome?"), ] prompt, tool_mode = build_prompt(messages, [WEATHER_TOOL], None, has_session=True) assert tool_mode assert "And in Rome?" in prompt assert "get_weather" not in prompt
def test_build_prompt_tool_round_with_session_skips_schema(): messages = [ Message(role="user", content="What is the weather?"), Message(role="assistant", tool_calls=[{"id": "call_1", "type": "function", "function": {"name": "get_weather", "arguments": '{"city": "Moscow"}'}}]), Message(role="tool", content="22C, sunny", tool_call_id="call_1"), ] prompt, tool_mode = build_prompt(messages, [WEATHER_TOOL], None, has_session=True) assert tool_mode assert "22C, sunny" in prompt assert "You have access to the following functions" not in prompt
def test_build_prompt_new_chat_with_history_renders_full_context(): messages = [ Message(role="user", content="What is the weather?"), Message(role="assistant", content="It is 22C."), Message(role="user", content="And in Rome?"), ] prompt, tool_mode = build_prompt(messages, None, None, has_session=False) assert not tool_mode assert "What is the weather?" in prompt assert "It is 22C." in prompt assert "And in Rome?" in prompt
def test_build_prompt_new_chat_with_history_and_tools_renders_full_context(): messages = [ Message(role="user", content="What is the weather?"), Message(role="assistant", content="It is 22C."), Message(role="user", content="And in Rome?"), ] prompt, tool_mode = build_prompt(messages, [WEATHER_TOOL], None, has_session=False) assert tool_mode assert "get_weather" in prompt assert "What is the weather?" in prompt assert "It is 22C." in prompt assert "And in Rome?" in prompt
def test_fix_unbalanced_json_stray_closers_dropped(): assert _fix_unbalanced_json("]{") == "{}" assert _fix_unbalanced_json("}") == "" assert _fix_unbalanced_json("[}") == "[]"
def test_fix_unbalanced_json_missing_brace_before_bracket(): assert _fix_unbalanced_json('{"a": 1]') == '{"a": 1}'
def test_fix_unbalanced_json_wrong_closer_repaired(): assert _fix_unbalanced_json('{"a": [1}]') == '{"a": [1]}'
def test_fix_unbalanced_json_truncated_nested(): assert _fix_unbalanced_json('[{"a": 1],') == '[{"a": 1}],'
def test_fix_unbalanced_json_unterminated_string_closed(): assert _fix_unbalanced_json('{"a": "abc') == '{"a": "abc"}' assert _fix_unbalanced_json('{"a": "unterminated{[') == '{"a": "unterminated{["}' assert _fix_unbalanced_json('[{"a": "x') == '[{"a": "x"}]'
def test_fix_unbalanced_json_escaped_backslash_at_end_closed(): fixed = _fix_unbalanced_json('[{"a": "x\\') assert fixed is not None assert fixed is not None assert fixed == '[{"a": "x\\\\"}]' assert json.loads(fixed) == [{"a": "x\\"}]
def test_fix_unbalanced_json_balanced_returns_none(): assert _fix_unbalanced_json('{"a": [1, 2]}') is None assert _fix_unbalanced_json('"just string"') is None assert _fix_unbalanced_json('{"a": "\\"b\\"}", "c": [1, 2]}') is None
def test_strip_dsml_empty(): assert _strip_dsml("") == "" assert _strip_dsml(None) is None
def test_strip_dsml_unicode_markers(): for pipe in ("\u2016", "\uff5c", "\u01c0", "\u01c1", "\u05c0", "\u00a6", "\u2551", "\ufe31", "\u2223", "\u2758"): stripped = _strip_dsml(f"{pipe}DSML{pipe}<thinking>x</thinking>{pipe}DSML{pipe}\nHello") assert "<thinking>" not in stripped assert f"{pipe}DSML{pipe}" not in stripped assert "Hello" in stripped
def test_strip_dsml_tags_with_suffix_preserves_json(): text = '<\u2016DSML\u2016tool_calls>{"tool_calls":[{"name":"f","arguments":{"city":"Moscow"}}]}</\u2016DSML\u2016tool_calls>' calls, wrapper = parse_tool_calls(text) assert calls is not None assert calls[0].name == "f" assert wrapper == ""
def test_strip_dsml_removes_hidden_reasoning(): text = '<||DSML||thinking>step 1 step 2</||DSML||thinking>\n{"tool_calls":[{"name":"f","arguments":{"x":1}}]}' calls, wrapper = parse_tool_calls(text) assert calls is not None assert calls[0].name == "f" assert "step 1" not in wrapper
def test_strip_dsml_json_in_attrs_preserved(): text = '<||DSML||tool_calls {"tool_calls":[{"name":"f","arguments":{"city":"Moscow"}}]}>' calls, _ = parse_tool_calls(text) assert calls is not None assert calls[0].name == "f"
def test_strip_dsml_render_message_cleans_dsml(): msg = Message(role="assistant", content="<||DSML||thinking>secret</||DSML||thinking>answer") rendered = render_message(msg) assert "<thinking>" not in rendered assert "DSML" not in rendered assert "answer" in rendered
_DSML_JUNK_MARKER = "\u044f\u255c\u042c\u044f\u255c\u042c"
def test_strip_dsml_junk_marker_normalizes_xml(): text = ( f"<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}tool_calls>" f'<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}invoke name="edit">' f'<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}parameter name="filePath">a.py' f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}parameter>" f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}invoke>" f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}tool_calls>" ) stripped = _strip_dsml(text) assert "<tool_calls>" in stripped assert '<invoke name="edit">' in stripped assert '<parameter name="filePath">a.py</parameter>' in stripped assert "DSML" not in stripped
def test_parse_tool_calls_junk_marker_edit(): text = ( f"<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}tool_calls>\n" f'<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}invoke name="edit">\n' f'<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}parameter name="filePath">D:\\steam\\a.lua</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}parameter>\n' f'<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}parameter name="oldString">old</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}parameter>\n' f'<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}parameter name="newString">new</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}parameter>\n' f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}invoke>\n" f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}tool_calls>" ) calls, wrapper = parse_tool_calls(text) assert calls is not None assert calls[0].name == "edit" assert json.loads(calls[0].arguments) == {"filePath": "D:\\steam\\a.lua", "oldString": "old", "newString": "new"} assert wrapper == ""
def test_parse_tool_calls_junk_marker_glob(): text = ( f"<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}tool_calls>\n" f"<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}glob>\n" f"<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}pattern>**/*.py</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}pattern>\n" f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}glob>\n" f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}tool_calls>" ) calls, wrapper = parse_tool_calls(text) assert calls is not None assert calls[0].name == "glob" assert json.loads(calls[0].arguments) == {"pattern": "**/*.py"} assert wrapper == ""
def test_parse_tool_calls_wrapped_xml_tag_as_tool_name(): text = "<tool_calls>\n<glob>\n<pattern>*/</pattern>\n</glob>\n</tool_calls>" calls, wrapper = parse_tool_calls(text) assert calls is not None assert calls[0].name == "glob" assert json.loads(calls[0].arguments) == {"pattern": "*/"} assert wrapper == ""
def test_parse_tool_calls_bare_xml_tag_as_tool_name(): text = "<glob>\n<pattern>*/</pattern>\n</glob>" calls, wrapper = parse_tool_calls(text) assert calls is not None assert calls[0].name == "glob" assert json.loads(calls[0].arguments) == {"pattern": "*/"} assert wrapper == ""
def test_parse_tool_calls_bare_xml_multiple_calls(): text = "<glob><pattern>a</pattern></glob>\n<glob><pattern>b</pattern></glob>" calls, wrapper = parse_tool_calls(text) assert calls is not None assert [call.name for call in calls] == ["glob", "glob"] assert [json.loads(call.arguments) for call in calls] == [{"pattern": "a"}, {"pattern": "b"}] assert wrapper == ""
def test_parse_tool_calls_bare_xml_selfclose(): text = '<glob pattern="*/*.py"/>' calls, wrapper = parse_tool_calls(text) assert calls is not None assert calls[0].name == "glob" assert json.loads(calls[0].arguments) == {"pattern": "*/*.py"} assert wrapper == ""
def test_parse_tool_calls_bare_xml_attrs_and_children(): text = '<glob recursive="true"><pattern>**/*.py</pattern></glob>' calls, wrapper = parse_tool_calls(text) assert calls is not None assert calls[0].name == "glob" assert json.loads(calls[0].arguments) == {"recursive": "true", "pattern": "**/*.py"} assert wrapper == ""
def test_parse_tool_calls_bare_xml_with_prose(): text = "Search now\n<glob>\n<pattern>*.py</pattern>\n</glob>\nDone" calls, wrapper = parse_tool_calls(text) assert calls is not None assert calls[0].name == "glob" assert json.loads(calls[0].arguments) == {"pattern": "*.py"} assert wrapper == "Search now Done"
def test_parse_tool_calls_bare_xml_skips_html(): assert parse_tool_calls("<b>bold</b>") is None assert parse_tool_calls('<div class="x">text</div>') is None assert parse_tool_calls("<code>func(x)</code>") is None
def test_parse_tool_calls_bare_xml_skips_content_only(): assert parse_tool_calls("<custom>hello</custom>") is None assert parse_tool_calls("<tool><pattern>*/</pattern></tool>") is None
def test_parse_tool_calls_bare_xml_param_selfclose_ignored(): assert parse_tool_calls('<glob><pattern value="*"/></glob>') is None
def test_parse_tool_calls_bare_xml_junk_marker(): text = ( f"<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}glob>\n" f"<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}pattern>**/*.py</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}pattern>\n" f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}glob>" ) calls, wrapper = parse_tool_calls(text) assert calls is not None assert calls[0].name == "glob" assert json.loads(calls[0].arguments) == {"pattern": "**/*.py"} assert wrapper == ""
def test_parse_tool_calls_junk_marker_json_preserved(): payload = json.dumps({"tool_calls": [{"name": "f", "arguments": {"city": "Moscow"}}]}) text = f"<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}tool_calls>{payload}</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}tool_calls>" calls, wrapper = parse_tool_calls(text) assert calls is not None assert calls[0].name == "f" assert json.loads(calls[0].arguments) == {"city": "Moscow"} assert wrapper == ""
def test_strip_dsml_junk_marker_hidden_reasoning(): text = f"<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}ds_safety>secret</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}ds_safety>answer" stripped = _strip_dsml(text) assert "secret" not in stripped assert "DSML" not in stripped assert "answer" in stripped
def test_strip_dsml_any_unicode_marker(): markers = ( "\u03b1\u03b2", "\u4e2d\u6587", "\U0001f600", "\u3042\u3044", "\u20ac\u00a9", "\u05e9\u05dc", "\u0627\u0628", "\u00e9\u00ea", "\u2500\u2501", "\uff0d\uff3f", "\u0416\u0419", "\u0301\u0300", ) for junk in markers: text = ( f"<{junk}DSML{junk}tool_calls>" f'<{junk}DSML{junk}invoke name="f">' f'<{junk}DSML{junk}parameter name="x">1</{junk}DSML{junk}parameter>' f"</{junk}DSML{junk}invoke>" f"</{junk}DSML{junk}tool_calls>" ) calls, wrapper = parse_tool_calls(text) assert calls is not None assert calls[0].name == "f" assert json.loads(calls[0].arguments) == {"x": "1"} assert wrapper == ""
def test_strip_dsml_any_unicode_marker_hidden(): for junk in ("\u03b1", "\U0001f600", "\u4e2d"): text = f"<{junk}DSML{junk}thinking>secret</{junk}DSML{junk}thinking>answer" stripped = _strip_dsml(text) assert "secret" not in stripped assert "DSML" not in stripped assert "answer" in stripped
def test_strip_dsml_paired_tag_block(): text = "hello <|ds_middle|>DSML<|ds_end|> world" stripped = _strip_dsml(text) assert "DSML" not in stripped assert "ds_middle" not in stripped assert "ds_end" not in stripped assert stripped == "hello world"
def test_strip_dsml_paired_tag_same_name(): text = "<|ds_safety|>DSML<|ds_safety|>secret<|ds_safety|>DSML<|ds_safety|>answer" stripped = _strip_dsml(text) assert "DSML" not in stripped assert "ds_safety" not in stripped assert "answer" in stripped
def test_strip_dsml_paired_tag_spaces(): text = "a <|ds_middle|> DSML <|ds_end|> b" stripped = _strip_dsml(text) assert "DSML" not in stripped assert "ds_middle" not in stripped assert "ds_end" not in stripped
def test_strip_dsml_two_char_wrap(): text = "before |>DSML<| after" stripped = _strip_dsml(text) assert "DSML" not in stripped assert "before" in stripped assert "after" in stripped
def test_strip_dsml_two_char_pipe_wrap(): text = "before ||DSML|| after" stripped = _strip_dsml(text) assert "DSML" not in stripped assert "before" in stripped assert "after" in stripped
def test_strip_dsml_json_tag_untouched_by_paired_rules(): text = '<|DSML|{"tool_calls":[{"name":"f","arguments":{"x":1}}]}>' stripped = _strip_dsml(text) assert stripped == '{"tool_calls":[{"name":"f","arguments":{"x":1}}]}'
def test_parse_tool_calls_paired_tag_block_cleaned(): text = '<|ds_middle|>DSML<|ds_end|>{"tool_calls":[{"name":"f","arguments":{"x":1}}]}' calls, wrapper = parse_tool_calls(text) assert calls is not None assert calls[0].name == "f" assert json.loads(calls[0].arguments) == {"x": 1} assert wrapper == ""
def test_strip_dsml_render_message_paired_tags(): msg = Message(role="assistant", content="<|ds_middle|>DSML<|ds_end|>answer") rendered = render_message(msg) assert "DSML" not in rendered assert "ds_middle" not in rendered assert "answer" in rendered
def test_strip_dsml_tag_json_without_name_preserved(): text = '<|DSML|{"tool_calls":[{"name":"f","arguments":{"x":1}}]}>' stripped = _strip_dsml(text) assert stripped == '{"tool_calls":[{"name":"f","arguments":{"x":1}}]}'
def test_strip_dsml_tag_without_name_replaced(): assert _strip_dsml("<|DSML|123>") == " "
def test_strip_dsml_tag_json_without_calls_replaced(): text = '<|DSML|{"answer": 42}>' stripped = _strip_dsml(text) assert "answer" not in stripped
def test_tool_call_create_variants(): assert ToolCall.create("f", None).arguments == "{}" assert ToolCall.create("f", "raw").arguments == "raw" assert ToolCall.create("f", {"a": 1}).arguments == '{"a": 1}' assert ToolCall.create("f", [1, 2]).arguments == "[1, 2]" assert ToolCall.create("f", 5).arguments == "5"
def test_tool_function_variants(): assert _tool_function(None) is None assert _tool_function("str") is None assert _tool_function({"function": 42}) is None assert _tool_function({"name": "x"}) == {"name": "x"} assert _tool_function({"function": {"name": "y"}}) == {"name": "y"}
def test_render_tool_schema_empty_names(): assert render_tool_schema([{"function": {"name": ""}}]) is None assert render_tool_schema([{"function": {"parameters": {}}}]) is None
def test_render_tool_schema_string_params(): tool = {"function": {"name": "f", "parameters": '{"type":"object"}'}} schema = render_tool_schema([tool]) assert schema is not None assert schema is not None assert '{"type":"object"}' in schema
def test_content_text_variants(): assert _content_text(42) == "" assert _content_text([42, {"type": "image_url"}]) == ""
def test_content_fingerprint_variants(): assert _content_text(42, with_images=True, separator="\n") == "" assert _content_text([{"type": "image_url", "image_url": "data:x"}], with_images=True, separator="\n") == "data:x" assert _content_text([42, "str"], with_images=True, separator="\n") == "str" assert _content_text([{"type": "other", "text": 5}], with_images=True, separator="\n") == "" assert _content_text([{"type": "image_url", "image_url": 42}], with_images=True, separator="\n") == ""
def test_render_tool_call_mention_variants(): assert _render_tool_call_mention(None) == "" assert _render_tool_call_mention({"name": "f", "arguments": [1]}) == "[assistant called f([1])]" assert _render_tool_call_mention({"function": {"name": "g", "arguments": "{}"}}) == "[assistant called g({})]"
def test_render_message_roles(): msg = Message(role="function", name="calc", content="42") assert render_message(msg) == "Function calc returned: 42" msg = Message(role="tool", content="ok") assert render_message(msg) == "Tool result: ok" msg = Message(role="other", content="x") assert render_message(msg) == "x"
def test_extract_last_user_image_only(): msg = Message(role="user", content=[{"type": "image_url", "image_url": {"url": "data:image/png;base64,x"}}]) with pytest.raises(ValueError): extract_last_user([msg])
def test_has_history_multiple_users(): assert _has_history([Message("user", "a"), Message("user", "b")]) assert not _has_history([Message("user", "a")])
def test_tail_after_last_user_no_user(): msgs = [Message("assistant", "a"), Message("assistant", "b")] assert _tail_after_last_user(msgs) == msgs
def test_render_json_mode_unknown(): assert render_json_mode({"type": "text"}) is None assert render_json_mode(42) is None assert render_json_mode("text") is None
def test_normalize_single_quotes_escapes(): assert _normalize_single_quotes(r"{'a': 'say \"hi\"'}") == '{"a": "say \\"hi\\""}' assert _normalize_single_quotes(r"{'a': 'it\'s'}") == '{"a": "it\'s"}' assert _normalize_single_quotes(r"{'a': 'x\\y'}") == '{"a": "x\\\\y"}'
def test_coerce_scalar(): assert _coerce_scalar("5", "integer") == 5 assert _coerce_scalar("5.5", "number") == 5.5 assert _coerce_scalar("abc", "integer") == "abc" assert _coerce_scalar("true", "boolean") is True assert _coerce_scalar("false", "boolean") is False assert _coerce_scalar("maybe", "boolean") == "maybe" assert _coerce_scalar("x", "null") is None assert _coerce_scalar(5, "integer") == 5 assert _coerce_scalar("str", "string") == "str"
def test_is_jsonish_arguments(): assert _is_jsonish_arguments({"a": 1}) assert _is_jsonish_arguments('{"a": 1}') assert not _is_jsonish_arguments("nope") assert not _is_jsonish_arguments(42)
def test_extract_one_call_variants(): call = _extract_one_call({"function": {"name": "f", "arguments": {}}}) assert call.name == "f" call = _extract_one_call({"name": "g", "arguments": {}}) assert call.name == "g" assert _extract_one_call({"name": ""}) is None assert _extract_one_call("str") is None
def test_extract_calls_bare_dict(): calls = _extract_calls({"name": "f", "arguments": {"x": 1}}) assert calls is not None assert calls is not None assert calls[0].name == "f"
def test_tool_schema_map(): tools = [ { "function": { "name": "a", "parameters": {"properties": {"x": {"type": ["null", "integer"]}, "y": {"type": "string"}, "z": {}}}, } }, {"function": {"name": "b"}}, ] result = tool_schema_map(tools) assert result == {"a": {"x": "integer", "y": "string"}, "b": {}}
def test_xml_invoke_inline_json(): from danyapi.tools import _xml_invoke_arguments
args = _xml_invoke_arguments('{"cmd": "ls"}') assert args == {"cmd": "ls"} assert _xml_invoke_arguments(" ") is None
def test_xml_tag_attrs(): from danyapi.tools import _xml_tag_attrs
attrs = _xml_tag_attrs('key="value" num="5" flag="true"', {"num": "integer", "flag": "boolean"}) assert attrs == {"key": "value", "num": 5, "flag": True} attrs = _xml_tag_attrs('key="value"') assert attrs == {"key": "value"}
def test_parse_xml_self_closing(): text = '<tool_calls><bash command="ls"/></tool_calls>' parsed = _parse_xml_tool_calls(text, {"bash": {"command": "string"}}) assert parsed is not None calls, _ = parsed assert calls is not None assert calls[0].name == "bash" assert json.loads(calls[0].arguments) == {"command": "ls"}
def test_parse_bare_array_non_array(): assert _parse_bare_array_calls("hello") is None assert _parse_bare_array_calls("not [json") is None
def test_loads_lenient_paths(): assert _loads_lenient('{"a": 1,}') == {"a": 1} assert _loads_lenient("{'a': 1}") == {"a": 1} assert _loads_lenient('{"a": 1}') == {"a": 1} with pytest.raises(ValueError): _loads_lenient("not json at all")
def test_loads_lenient_bare_quote_fails_late(): with pytest.raises(ValueError): _loads_lenient("{a: b c}") with pytest.raises(ValueError): _loads_lenient("{'a': b c}")
def test_build_prompt_history_no_session(): messages = [Message("user", "q1"), Message("assistant", "a1"), Message("user", "q2")] prompt, tool_mode = build_prompt(messages, has_session=False) assert "q1" in prompt assert "q2" in prompt assert not tool_mode
def test_build_prompt_session_json(): messages = [Message("user", "hello")] prompt, _ = build_prompt(messages, has_session=True, response_format="json_object") assert "valid JSON object" in prompt assert "hello" in prompt
def test_tool_call_deltas_with_text(): calls = [ToolCall.create("f", {"x": 1})] deltas = tool_call_deltas(calls, "pre") assert deltas[0] == {"role": "assistant", "content": "pre"}
def test_tool_function_non_string_name(): assert _tool_function({"name": 5}) is None
def test_content_text_string_items(): assert _content_text(["hello"]) == "hello" assert _content_text([{"text": "x"}]) == "x"
def test_content_fingerprint_string_items(): assert _content_text(["a"], with_images=True, separator="\n") == "a"
def test_extract_last_user_string_items(): msg = Message(role="user", content=["a", {"type": "text", "text": "b"}]) assert extract_last_user([msg]) == "ab"
def test_has_history_tool_role(): assert _has_history([Message("user", "a"), Message("tool", "42", tool_call_id="c")])
def test_is_tool_round_tail_variants(): assert is_tool_round([Message("tool", "x")]) assert is_tool_round([Message("assistant", tool_calls=[{"id": "c", "type": "function", "function": {"name": "f", "arguments": "{}"}}])]) assert is_tool_round([Message("assistant", content=[{"type": "tool_call", "id": "c", "function": {"name": "f", "arguments": "{}"}}])]) assert not is_tool_round([Message("user", "hi")])
def test_build_prompt_history_with_json_mode(): messages = [Message("user", "q1"), Message("assistant", "a1"), Message("user", "q2")] prompt, _ = build_prompt(messages, has_session=False, response_format="json_object") assert "valid JSON object" in prompt assert prompt.index("valid JSON") < prompt.index("q1")
def test_build_prompt_empty_history_fallback(): messages = [Message("user", ""), Message("user", "")] _prompt, tool_mode = build_prompt(messages, has_session=False) assert tool_mode is False
def test_normalize_single_quotes_escaped_other(): assert _normalize_single_quotes(r"{'a': '\t'}") == '{"a": "\\t"}'
def test_extract_wrapped_calls_tool_calls_dict(): from danyapi.tools import _extract_wrapped_calls
calls = _extract_wrapped_calls({"tool_calls": {"name": "f", "arguments": {"x": 1}}}) assert calls is not None assert calls[0].name == "f"
def test_parse_two_objects_second_is_tool_call(): text = '{"a": 1} {"tool_calls": [{"name": "f", "arguments": {"x": 1}}]}' parsed = parse_tool_calls(text) assert parsed is not None calls, _ = parsed assert calls is not None assert calls[0].name == "f"
def test_xml_invoke_empty_args_accepted(): text = '<tool_calls><invoke name="bash"> </invoke></tool_calls>' parsed = _parse_xml_tool_calls(text, {"bash": {"cmd": "string"}}) assert parsed is not None calls, _ = parsed assert calls is not None assert calls[0].name == "bash" assert json.loads(calls[0].arguments) == {}
def test_xml_open_pattern_overlap_skipped(): text = '<invoke name="other"><bash>x</bash></invoke>' parsed = _parse_xml_tool_calls(text, {"other": {"a": "string"}, "bash": {"cmd": "string"}}) assert parsed is not None calls, _ = parsed assert calls is not None assert [c.name for c in calls] == ["other"]
def test_xml_open_pattern_empty_merged_accepted(): text = "<bash></bash>" parsed = _parse_xml_tool_calls(text, {"bash": {"cmd": "string"}}) assert parsed is not None calls, _ = parsed assert calls is not None assert calls[0].name == "bash" assert json.loads(calls[0].arguments) == {}
def test_xml_open_pattern_with_schema(): text = "<bash><cmd>ls</cmd></bash>" parsed = _parse_xml_tool_calls(text, {"bash": {"cmd": "string"}}) assert parsed is not None calls, _wrapper = parsed assert calls is not None assert calls[0].name == "bash" assert json.loads(calls[0].arguments) == {"cmd": "ls"}
def test_xml_selfclose_overlap_skipped(): text = '<invoke name="other"><bash/></invoke>' parsed = _parse_xml_tool_calls(text, {"other": {"a": "string"}, "bash": {"cmd": "string"}}) assert parsed is not None calls, _ = parsed assert calls is not None assert [c.name for c in calls] == ["other"]
def test_tool_schema_map_skips_bad_tools(): tools = [ {"function": {}}, {"function": {"name": ""}}, ] assert tool_schema_map(tools) == {}
def test_tool_schema_map_normalizes_bad_params(): tools = [ {"function": {"name": "a", "parameters": "not json"}}, {"function": {"name": "b", "parameters": {"properties": "not dict"}}}, {"function": {"name": "c", "parameters": {"properties": {"x": "not dict"}}}}, ] assert tool_schema_map(tools) == {"a": {}, "b": {}, "c": {}}
