def test_parse_xml_selfclose_no_args(): text = "<bash />" parsed = _parse_xml_tool_calls(text, {"bash": {}}) assert parsed is not None calls, _ = parsed assert calls is not None assert calls[0].name == "bash" assert json.loads(calls[0].arguments) == {}
def test_parse_xml_unknown_tag_empty_args_still_skipped(): text = "<unknown />" parsed = _parse_xml_tool_calls(text, {"bash": {}}) assert parsed == (None, "")
def test_balanced_json_no_brace(): from danyapi.tools import _balanced_json
assert _balanced_json("no braces here") is None
def test_extract_json_object_balanced_but_invalid(): from danyapi.tools import _extract_json_object
assert _extract_json_object('pre {"a": } post') is None
def test_parse_bare_array_broken_json(): assert _parse_bare_array_calls("[{broken") is None
def test_iter_json_objects_skips_bad_candidates(): from danyapi.tools import _iter_json_objects
text = '{"ok": 1} not-json {"bad": }' objs = [obj for obj, _, _ in _iter_json_objects(text)] assert objs == [{"ok": 1}]
def test_parse_bare_keys_json(): parsed = parse_tool_calls('{"tool_calls": [{name: glob, arguments: {pattern: "*/"}}]}') assert parsed is not None calls, _ = parsed assert calls is not None assert calls[0].name == "glob" assert json.loads(calls[0].arguments) == {"pattern": "*/"}
def test_parse_bare_keys_json_unquoted_values(): parsed = parse_tool_calls("{name: get_weather, arguments: {city: Moscow, temp: 22, sunny: true}}") assert parsed is not None calls, _ = parsed assert calls is not None assert calls[0].name == "get_weather" assert json.loads(calls[0].arguments) == {"city": "Moscow", "temp": 22, "sunny": True}
def test_parse_alias_keys_json(): parsed = parse_tool_calls('{"tool": "glob", "input": {"pattern": "*/"}}') assert parsed is not None calls, _ = parsed assert calls is not None assert calls[0].name == "glob" assert json.loads(calls[0].arguments) == {"pattern": "*/"}
def test_parse_alias_keys_json_bare_array(): parsed = parse_tool_calls('[{"action": "read", "args": {"filePath": "a.py"}}]') assert parsed is not None calls, _ = parsed assert calls is not None assert calls[0].name == "read" assert json.loads(calls[0].arguments) == {"filePath": "a.py"}
def test_parse_xml_nameless_invoke_with_name_and_input(): text = '<tool_use><name>glob</name><input>{"pattern": "*/"}</input></tool_use>' parsed = parse_tool_calls(text) assert parsed is not None calls, _ = parsed assert calls is not None assert calls[0].name == "glob" assert json.loads(calls[0].arguments) == {"pattern": "*/"}
def test_parse_xml_nameless_invoke_with_parameter_children(): text = "<tool><name>get_weather</name><city>Moscow</city></tool>" parsed = parse_tool_calls(text) assert parsed is not None calls, _ = parsed assert calls is not None assert calls[0].name == "get_weather" assert json.loads(calls[0].arguments) == {"city": "Moscow"}
def test_parse_xml_function_wrapper(): text = '<functions><function name="glob"><pattern>*/</pattern></function></functions>' parsed = parse_tool_calls(text) assert parsed is not None calls, wrapper = parsed assert calls is not None assert calls[0].name == "glob" assert json.loads(calls[0].arguments) == {"pattern": "*/"} assert wrapper == ""
def test_parse_xml_arguments_container_unwrapped(): text = '<invoke name="bash"><arguments>{"cmd": "ls"}</arguments></invoke>' parsed = parse_tool_calls(text) assert parsed is not None calls, _ = parsed assert calls is not None assert calls[0].name == "bash" assert json.loads(calls[0].arguments) == {"cmd": "ls"}
def test_parse_xml_name_and_input_flat_wrapper(): text = "<tool_calls><name>glob</name><input><pattern>*/</pattern></input></tool_calls>" parsed = parse_tool_calls(text) assert parsed is not None calls, _ = parsed assert calls is not None assert calls[0].name == "glob" assert json.loads(calls[0].arguments) == {"pattern": "*/"}
def test_parse_python_call_single(): parsed = parse_tool_calls('get_weather(city="Moscow", units="celsius")') assert parsed is not None calls, _ = parsed assert calls is not None assert calls[0].name == "get_weather" assert json.loads(calls[0].arguments) == {"city": "Moscow", "units": "celsius"}
def test_parse_python_call_typed_values(): parsed = parse_tool_calls("read(filePath='a.py', limit=10, cached=False, note=None)") assert parsed is not None calls, _ = parsed assert calls is not None assert calls[0].name == "read" assert json.loads(calls[0].arguments) == {"filePath": "a.py", "limit": 10, "cached": False, "note": None}
def test_parse_python_call_multiline_and_multiple(): text = 'glob(pattern="*/")\nread(filePath="a.py", limit=5)' parsed = parse_tool_calls(text) assert parsed is not None calls, _ = parsed assert calls is not None assert [c.name for c in calls] == ["glob", "read"] assert json.loads(calls[1].arguments) == {"filePath": "a.py", "limit": 5}
def test_parse_python_call_not_detected_in_prose(): assert parse_tool_calls("The answer is read(filePath='a.py').") is None assert parse_tool_calls("Just check read(filePath='a.py') please.") is None
def test_parse_python_call_after_prose(): parsed = parse_tool_calls('Let me check.\n\nglob(pattern="*/")') assert parsed is not None calls, wrapper = parsed assert calls is not None assert calls[0].name == "glob" assert json.loads(calls[0].arguments) == {"pattern": "*/"} assert wrapper == "Let me check."
def test_parse_yaml_block(): text = 'tool_calls:\n- name: glob\n arguments:\n pattern: "*/"\n- name: read\n arguments:\n filePath: a.py' parsed = parse_tool_calls(text) assert parsed is not None calls, _ = parsed assert calls is not None assert [c.name for c in calls] == ["glob", "read"] assert json.loads(calls[0].arguments) == {"pattern": "*/"} assert json.loads(calls[1].arguments) == {"filePath": "a.py"}
def test_parse_yaml_inline_flow(): text = 'tool_calls:\n- name: glob\n arguments: {pattern: "*/"}' parsed = parse_tool_calls(text) assert parsed is not None calls, _ = parsed assert calls is not None assert calls[0].name == "glob" assert json.loads(calls[0].arguments) == {"pattern": "*/"}
def test_parse_yaml_inline_array(): text = 'tool_calls: [{"name": "glob", "arguments": {"pattern": "*/"}}]' parsed = parse_tool_calls(text) assert parsed is not None calls, _ = parsed assert calls is not None assert calls[0].name == "glob" assert json.loads(calls[0].arguments) == {"pattern": "*/"}
def test_parse_tool_calls_debug(): report = parse_tool_calls_debug('glob(pattern="*/")') assert report["parsed"] assert report["strategies"] == ["python_call"] assert report["calls"][0]["name"] == "glob" assert report["calls"][0]["arguments"] == '{"pattern": "*/"}' assert report["wrapper"] == ""
report = parse_tool_calls_debug("Just a normal answer.") assert not report["parsed"] assert report["strategies"] == [] assert report["calls"] == [] assert report["unrecognized"] == "Just a normal answer."
def test_parse_tool_calls_debug_strategies(): assert parse_tool_calls_debug('{"tool_calls": [{"name": "a", "arguments": {}}]}')["strategies"] == ["json_wrapped"] assert parse_tool_calls_debug('[{"name": "a", "arguments": {}}]')["strategies"] == ["json_array"] assert parse_tool_calls_debug('<invoke name="a"><x>1</x></invoke>')["strategies"] == ["xml"] assert parse_tool_calls_debug("tool_calls:\n- name: a\n arguments: {x: 1}")["strategies"] == ["yaml"] assert parse_tool_calls_debug('First check. {"name": "a", "arguments": {}}')["strategies"] == ["json_in_prose"]
def test_parse_dsml_strategy_debug(): text = ( f"<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}tool_calls>" f'<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}invoke name="a">' f'<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}parameter name="x">1</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}parameter>' f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}invoke>" f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}tool_calls>" ) report = parse_tool_calls_debug(text) assert report["parsed"] assert report["strategies"] == ["dsml"] assert report["calls"][0]["name"] == "a" assert json.loads(report["calls"][0]["arguments"]) == {"x": "1"}
def test_parse_dsml_invoke_attrs_before_after_name(): for attrs in ('type="function" name="edit"', 'name="edit" type="function"', 'name = "edit"'): text = ( f"<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}tool_calls>" f"<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}invoke {attrs}>" f'<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}parameter name="filePath">a.py</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}parameter>' f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}invoke>" f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}tool_calls>" ) calls, wrapper = parse_tool_calls(text) assert calls is not None assert calls[0].name == "edit" assert json.loads(calls[0].arguments) == {"filePath": "a.py"} assert wrapper == ""
def test_parse_dsml_invoke_child_elements_without_parameter(): text = ( f"<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}tool_calls>" f'<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}invoke name="glob">' f"<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}pattern>**/*.py</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}pattern>" f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}invoke>" f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}tool_calls>" ) calls, wrapper = parse_tool_calls(text) assert calls is not None assert calls[0].name == "glob" assert json.loads(calls[0].arguments) == {"pattern": "**/*.py"} assert wrapper == ""
def test_parse_dsml_multiple_invokes(): text = ( f"<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}tool_calls>" f'<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}invoke name="a">' f'<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}parameter name="x">1</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}parameter>' f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}invoke>" f'<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}invoke name="b">' f'<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}parameter name="y">2</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}parameter>' f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}invoke>" f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}tool_calls>" ) calls, wrapper = parse_tool_calls(text) assert calls is not None assert [c.name for c in calls] == ["a", "b"] assert json.loads(calls[0].arguments) == {"x": "1"} assert json.loads(calls[1].arguments) == {"y": "2"} assert wrapper == ""
def test_parse_dsml_reasoning_stripped_from_wrapper(): text = ( f"<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}thinking>secret</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}thinking>" f"<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}tool_calls>" f'<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}invoke name="a">' f'<{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}parameter name="x">1</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}parameter>' f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}invoke>" f"</{_DSML_JUNK_MARKER}DSML{_DSML_JUNK_MARKER}tool_calls>" ) calls, wrapper = parse_tool_calls(text) assert calls is not None assert calls[0].name == "a" assert "secret" not in wrapper
