SHELL_TOOL = { "type": "function", "function": { "name": "bash", "description": "Run a shell command", "aliases": ["exec_command", "shell", "run_cmd"], "parameters": {"type": "object", "properties": {"command": {"type": "string"}}, "required": ["command"]}, }, }
def test_normalize_call_name_alias_resolution(): schemas = tool_schema_map([SHELL_TOOL, NO_ARGS_TOOL]) from danyapi.tools import _normalize_call_name
for emitted in ("exec_command", "shell", "run_cmd", "Exec-Command", "EXEC_COMMAND"): assert _normalize_call_name(emitted, schemas) == "bash", emitted
def test_normalize_call_name_compact_and_fuzzy(): schemas = tool_schema_map([WEATHER_TOOL]) from danyapi.tools import _normalize_call_name
assert _normalize_call_name("Get-Weather", schemas) == "get_weather" assert _normalize_call_name("get_weathers", schemas) == "get_weather" assert _normalize_call_name("totally_unrelated", schemas) == "totally_unrelated"
def test_normalize_call_name_ambiguous_not_mapped(): tools = [ {"type": "function", "function": {"name": "search_web"}}, {"type": "function", "function": {"name": "search_news"}}, ] schemas = tool_schema_map(tools) from danyapi.tools import _normalize_call_name
assert _normalize_call_name("search_web_results", schemas) == "search_web_results"
