def test_tail_without_function_names_reminder(): messages = [ Message(role="user", content="What is the weather?"), Message(role="assistant", tool_calls=[{"id": "call_1", "type": "function", "function": {"name": "get_weather", "arguments": '{"city": "Moscow"}'}}]), Message(role="tool", content="22C, sunny", tool_call_id="call_1"), ] prompt, tool_mode = build_prompt(messages, [WEATHER_TOOL], None, has_session=True) assert tool_mode assert "Available functions:" not in prompt assert "You have access to the following functions" not in prompt assert "Continue the conversation" in prompt
def test_tail_without_tools_has_no_reminder(): messages = [ Message(role="user", content="What is the weather?"), Message(role="assistant", tool_calls=[{"id": "call_1", "type": "function", "function": {"name": "get_weather", "arguments": '{"city": "Moscow"}'}}]), Message(role="tool", content="22C, sunny", tool_call_id="call_1"), ] prompt, _ = build_prompt(messages, None, None, has_session=True) assert "Available functions:" not in prompt assert "Continue the conversation" in prompt
def test_history_mode_omits_recency_reminder(): messages = [ Message(role="user", content="What is the weather?"), Message(role="assistant", content="It is 22C."), Message(role="user", content="And in Rome?"), ] prompt, tool_mode = build_prompt(messages, [WEATHER_TOOL], None, has_session=False) assert tool_mode assert "get_weather" in prompt assert "And in Rome?" in prompt assert "Remember: to call any function" not in prompt
def test_history_mode_without_tools_no_reminder(): messages = [Message(role="user", content="hi")] prompt, _ = build_prompt(messages, None, None, has_session=False) assert "Remember: to call any function" not in prompt
def test_xml_known_parameterless_no_content_fallback(): text = "<pong>hello</pong>" result = parse_tool_calls(text, tool_schemas=tool_schema_map([NO_PARAMS_OBJECT_TOOL])) assert result is not None calls, _ = result assert calls[0].name == "pong" assert json.loads(calls[0].arguments) == {}
def test_xml_unknown_tool_keeps_content_fallback(): text = '<tool_calls><invoke name="mystery">hello</invoke></tool_calls>' result = parse_tool_calls(text) assert result is not None calls, _ = result assert calls[0].name == "mystery" assert json.loads(calls[0].arguments) == {"content": "hello"}
def test_parse_xml_selfclose_alias_inside_wrapper(): schemas = tool_schema_map([SHELL_TOOL]) calls, _ = parse_tool_calls("<tool_calls><Exec_Command/></tool_calls>", schemas) assert calls is not None assert [(c.name, json.loads(c.arguments)) for c in calls] == [("bash", {})]
def test_parse_xml_selfclose_casefold_inside_wrapper(): schemas = tool_schema_map([SHELL_TOOL]) calls, _ = parse_tool_calls("<tool_calls><BASH/></tool_calls>", schemas) assert calls is not None assert [c.name for c in calls] == ["bash"]
def test_parse_xml_selfclose_alias_with_sibling_inside_wrapper(): schemas = tool_schema_map([SHELL_TOOL]) calls, _ = parse_tool_calls('<tool_calls><bash command="ls"/><Exec_Command/></tool_calls>', schemas) assert calls is not None assert [(c.name, json.loads(c.arguments)) for c in calls] == [("bash", {"command": "ls"}), ("bash", {})]
def test_parse_xml_calls_wrapper_invisible(): text = '<calls>\n<invoke name="get_weather"><parameter name="city">Moscow</parameter></invoke>\n</calls>' calls, wrapper = parse_tool_calls(text) assert calls is not None assert len(calls) == 1 assert calls[0].name == "get_weather" assert json.loads(calls[0].arguments) == {"city": "Moscow"} assert wrapper == ""
def test_parse_xml_underscore_calls_wrapper_invisible(): text = '<_calls><invoke name="get_weather"><parameter name="city">Oslo</parameter></invoke></_calls>' calls, wrapper = parse_tool_calls(text, tool_schemas=tool_schema_map([WEATHER_TOOL])) assert calls is not None assert len(calls) == 1 assert calls[0].name == "get_weather" assert json.loads(calls[0].arguments) == {"city": "Oslo"} assert wrapper == ""
def test_parse_xml_calls_wrapper_selfclose_tool_invisible(): schemas = tool_schema_map([SHELL_TOOL]) calls, wrapper = parse_tool_calls('<calls><bash command="ls"/></calls>', schemas) assert calls is not None assert [(c.name, json.loads(c.arguments)) for c in calls] == [("bash", {"command": "ls"})] assert wrapper == ""
def test_parse_json_calls_key_wrapper(): text = '{"calls": [{"name": "get_weather", "arguments": {"city": "Moscow"}}]}' calls, wrapper = parse_tool_calls(text) assert calls is not None assert len(calls) == 1 assert calls[0].name == "get_weather" assert wrapper == ""
def test_parse_html_wrapped_known_tool_no_longer_shadowed(): schemas = tool_schema_map([NO_ARGS_TOOL]) calls, _ = parse_tool_calls("<div><ping/></div>", schemas) assert calls is not None assert [c.name for c in calls] == ["ping"]
def test_parse_plain_html_still_ignored(): assert parse_tool_calls("<div><span>hi</span></div>") is None assert parse_tool_calls("Just a normal <b>answer</b>.") is None
def test_debug_report_reports_renames(): schemas = tool_schema_map([SHELL_TOOL]) rep = parse_tool_calls_debug('<invoke name="exec_command"><parameter name="command">ls</parameter></invoke>', schemas) assert rep["parsed"] assert {"from": "exec_command", "to": "bash"} in rep["renamed"] assert rep["calls"][0]["name"] == "bash"
def test_debug_report_no_renames_when_exact(): schemas = tool_schema_map([SHELL_TOOL]) rep = parse_tool_calls_debug('<tool_calls><invoke name="bash"></invoke></tool_calls>', schemas) assert rep["parsed"] assert rep["renamed"] == []
def test_debug_report_unparsed_has_empty_renamed(): rep = parse_tool_calls_debug("no calls here", tool_schema_map([SHELL_TOOL])) assert not rep["parsed"] assert rep["renamed"] == []

